local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "গোপনরক্ষক, শুনেছেন কি? শহরতলির সেই প্রত্যন্ত শিল্প প্রদর্শনশালাটি বন্ধ হয়ে যাচ্ছে, আর সেটা ঠিক আমার জন্মদিনেই।\nপ্রদর্শনশালাটি শিল্পজগতের এক উদ্ভট সৃষ্টি — অর্ধেকটা ভবিষ্যতবাদের অপরিণত পরীক্ষা-নিরীক্ষা, আর অর্ধেকটা দুই শতাব্দী আগের আবর্জনার অবশেষ। এর সংকীর্ণ পেটের ভেতরে ভর্তি এমন সব উদ্ভট জিনিস যা নিলামঘরে কেউ ছুঁতেও সাহস পায় না: অশ্লীল ভাষায় কথা বলা প্রতিকৃতি, কখনো উড়ে থামে না এমন যান্ত্রিক পাখি, দেখলেই বমি পায় এমন সামুদ্রিক ভাস্কর্য, সম্পূর্ণ অশ্রু দিয়ে তৈরি মূর্তি, নিরন্তর স্বয়ংক্রিয়ভাবে লিখে চলা ভূতুড়ে পাণ্ডুলিপি, চুম্বন করলে ছড়া গুনগুন করে এমন মানুষের খুলি……\nআপনাকে বলে বোঝাতে পারব না আমি এই প্রদর্শনশালাটিকে কতটা ভালোবাসি! পঞ্চাশ বছর আগে আজকের দিনে, এটি নীরবে জন্ম নিয়েছিল সেই অবহেলিত কোণায়। পঞ্চাশ বছর পরে আজ, এটি নীরবে সেই কোণাতেই বিলীন হচ্ছে।\nআমার শৈশব থেকেই মানুষ আমাকে বলে এসেছে যে আজকের এই দিনটি একটি অভিশাপ, ঠিক আমার মতোই। আমার মনে হয় ভাগ্য হয়তো সত্যিই অদৃশ্য হাতে আগে থেকেই নির্ধারিত, কিন্তু নির্ধারিত হলেই বা কী! সেই প্রদর্শনশালা যা সৃষ্টি করেছে, তা এক অনন্য জগৎ — এত এত উন্মাদ কল্পনা সেই ছোট্ট জায়গায় স্তরে স্তরে জমে আছে, কী অপূর্ব দৃশ্য! জন্মের দিন থেকেই এটি তার প্রদর্শনী দিয়ে সৃষ্টিকর্ম চালিয়ে গেছে। এর সমাপ্তির এই দিনে, এর অন্তরঙ্গ বন্ধু ও পুরনো সঙ্গীরাও এর শেষ বিদায় জানাবে।\nগোপনরক্ষক, আপনি সংযোগে আমার চোখের জগৎ দেখেছেন, আমার মনে হয়, আপনিও নিশ্চয়ই আমার সাথে এই অদ্ভুত প্রদর্শনশালাটি দেখতে যেতে চাইবেন, তাই না?!\n\nপিকম্যান"
  },
