  Mail_116602_Desc = {
    Text = "প্রিয় রক্ষক:\n「চিরদীপ্তের সন্ধ্যা」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট 「দর্শন নৈবেদ্য」, 「প্রায়শ্চিত্ত নৈবেদ্য」 এবং 「নিষ্ঠাবান নৈবেদ্য」 প্রতিটি 「রোজ স্ক্রিপ *40」-এ রূপান্তরিত হবে। অনুগ্রহ করে আপনার পুরস্কারগুলি যাচাই করতে ভুলবেন না।"
