  Mail_117308_Desc = {
    Text = "প্রিয় রক্ষক:\n        「ইভ অব বিস্মৃতি」-কে তোমার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে রক্ষকদের আরও উন্নত গেমিং অভিজ্ঞতা দিতে, আমরা আন্তরিকভাবে তোমাকে নিম্নলিখিত অভিজ্ঞতা-সমীক্ষাটি পূরণ করার আমন্ত্রণ জানাচ্ছি। তোমার সহযোগিতার প্রতি কৃতজ্ঞতার নিদর্শন হিসেবে, আমরা পুরস্কার হিসেবে [Silver*200] প্রস্তুত করেছি, যা তুমি সমীক্ষা সম্পন্ন করার পর গ্রহণ করতে পারবে। সমীক্ষা জমা দেওয়ার শেষ সময় 10ই নভেম্বর সকাল 9টা, তাই অনুগ্রহ করে সময়মতো এটি পূরণ করে দিও।\n        <SurveyLink:[Click here to fill out]>\n        আমরা প্রতিটি রক্ষকের প্রস্তাব গভীর মনোযোগ দিয়ে বিবেচনা করব, আর তোমার প্রতিক্রিয়া অবশ্যই মিথাগ বিশ্ববিদ্যালয়কে আরও উন্নত করে তুলবে!\n        —রৌপ্য চাবি তোমার পথ আলোকিত করুক।"
  },
  Mail_117308_Name = {
