  Mail_117309_Desc = {
    Text = "প্রিয় রক্ষক, \n        「মরিমেন্স」-এর প্রতি আপনার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে রক্ষকদের আরও উন্নত গেমিং অভিজ্ঞতা দেওয়ার লক্ষ্যে আমরা আপনাকে আন্তরিকভাবে আমন্ত্রণ জানাচ্ছি নিম্নের অভিজ্ঞতা-সমীক্ষাটি পূরণ করার জন্য। আপনার সহযোগিতার কৃতজ্ঞতাস্বরূপ আমরা পুরস্কার হিসেবে প্রস্তুত করেছি [Silver*200], যা সমীক্ষা সম্পন্ন করার পর আপনি গ্রহণ করতে পারবেন। এই সমীক্ষা পূরণের শেষ সময় 30শে মার্চ সকাল 9টা; অনুগ্রহ করে সময়ের মধ্যে তা পূরণ করুন।\n        <SurveyLink:[Click here to fill out]>\n        আমরা প্রতিটি রক্ষকের প্রস্তাব গভীর মনোযোগ দিয়ে বিবেচনা করব, আর আপনার প্রতিক্রিয়া নিঃসন্দেহে মিথাগ বিশ্ববিদ্যালয়কে আরও উন্নত করে তুলবে।\n        —রৌপ্য চাবি তোমার পথ আলোকিত করুক।"
