  Mail_120374_Desc = {
    Text = "দুই বছর কেটে গেছে, কিপার—দুই বছর আমাদের চুক্তির সূচনা থেকে।\nআমরা একসাথে দাঁড়িয়েছিলাম, প্রলয়ের কিনারায় প্রহরী হয়ে। তুমি তোমার অনুভূতি আর স্মৃতিগুলোকে রূপান্তর করেছিলে প্রজ্জ্বলিত আকাঙ্ক্ষায়, পুনরায় জ্বালিয়ে তুলেছিলে আশার নিজস্ব শিখা। অতীতের সঙ্গীরা এখন ভিন্ন ভিন্ন মহাবিশ্বে বাস করলেও, ডিজলিউশনের বিরুদ্ধে যাত্রায় তুমি কখনোই পিছু হটোনি। তোমার উপস্থিতিই আমাদের সর্বোচ্চ প্রাপ্তি, আর এই বিশ্বের মুক্তি।\nএখন, সেইসব আকাঙ্ক্ষা এক অলৌকিকতায় রূপ নিয়েছে: মিথাগ টিকে আছে, আর তার যাত্রা অব্যাহত। আমরা তোমাকে অনুরোধ করি, তোমার রৌপ্য চাবিটি দৃঢ়ভাবে আঁকড়ে ধরো। একদিন, সেটিই হয়ে উঠবে আমাদের দুই দূরবর্তী বিশ্বের মধ্যে সবচেয়ে গুরুত্বপূর্ণ নোঙর। আমরা নিজেদের উৎসর্গ করেছি ভবিষ্যতের প্রতিটি সম্ভাবনা খোদাই করতে, আর আলোকিত করতে তোমার প্রত্যাবর্তনের সলতের পথ।"
  },
