  Mail_120909_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n        V2.4.0 আপডেটে, আমরা 「সোর্স লিকুইড দান - অ্যালামনাই ডোনেশন ফান্ড」-এর পুরস্কার বৃদ্ধি করেছি। আপডেটের আগে যেসব গোপনীয়তার রক্ষক ইতিমধ্যে অতিরিক্ত পুরস্কার সংগ্রহ করেছেন, তাদের জন্য আমরা সংশ্লিষ্ট পুরস্কার পরিপূরক হিসেবে পাঠাচ্ছি। অনুগ্রহ করে গ্রহণ করুন।"
