  Mail_121162_Desc = {
    Text = "সম্মানিত সিক্রেটকিপার:\n        V2.4.0 আপডেটে, আমরা 「অবতরণ ক্রনিকল」, 「ভিন্নবিশ্ব ক্রনিকল」, 「পুনরুদ্ধার ক্রনিকল」 এবং 「ধ্বংসনগর ক্রনিকল」-এর বিনামূল্যে পুরস্কার বৃদ্ধি করেছি। আপডেটের আগে যেসব সিক্রেটকিপার ইতিমধ্যে বিনামূল্যে পুরস্কার সংগ্রহ করেছেন, তাদের জন্য আমরা সংশ্লিষ্ট পুরস্কার পরিপূরক হিসেবে পাঠাব। অনুগ্রহ করে গ্রহণ করুন।"
  },
  Mail_121162_Name = {
    Text = "V2.4.0 আর্কাইভ পুরস্কার পুনঃপ্রদান"
