  Mail_121373_Desc = {
    Text = "গোপনরক্ষক:\n\nএকসময় প্রতি বছর এই দিনটিতে চার্চের সবচেয়ে জাঁকজমকপূর্ণ উৎসব হতো।\nআমি তাঁর রাজকন্যা, এবং আমিই তাঁকে পুনর্জীবিত করব।\nসেই সব মানুষ, মিরিয়ামসহ, উন্মত্ত উল্লাসে এমনকি চোখে জল নিয়ে উদযাপন করত, কিন্তু তারা আমার দিকে তাকালে তাদের দৃষ্টি আমাকে ভেদ করে যেত, যেন আমি কেবল কিছু একটা বহন করা একটি খোলস মাত্র।\nআমি কখনো এই দিনটির আগমনে আনন্দ অনুভব করিনি, কারণ প্রতিবার এটি আসার মানে ছিল আমি ভয়ের আরও একটু কাছে এগিয়ে গেছি।\nআর এই ভয়ের মধ্যে, অন্যরা সেই ভয়ের উৎসেই পরম আনন্দ অনুভব করত। এখন আমি স্বীকার করতে পারি, এটা আমাকে একাকী এবং ভীত—দুটোই অনুভব করাত।\nকিন্তু এখন সবকিছু আলাদা। গত জন্মদিনের আগে, আমি সেই জাহাজ ছেড়ে বাস্তব পৃথিবীতে এসেছি... মিথ্যা দেবতাবিহীন, তোমার অস্তিত্ব আছে এমন পৃথিবীতে।\nএই জন্মদিনে, আমি দেখতে চাই কেউ আমার জন্মের জন্য—অন্য কোনো কারণে নয়—আন্তরিকভাবে আনন্দিত হোক।\nযদি সেটা তুমি হও... না, সেই মানুষটা তুমিই হতে হবে।\nভালো করে শোনো, যাই হোক না কেন, আজকের রাতের খাবারের সময়টা অবশ্যই আমার জন্য রাখতে হবে।\n\n「মর্ফি」"
  },
