  Mail_121374_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমি জানি না তুমি এই বিশেষ দিনটির জন্য কী প্রস্তুতি নিয়েছ, তবে যতই জাঁকজমকপূর্ণ আর শ্রমসাধ্য হোক না কেন, তা অবশ্যই যথাযোগ্য।\nআর একজন উচ্চপদস্থ ব্যক্তির প্রয়োজনীয় সহানুভূতির খাতিরে, যদি তুমি 「কোনোভাবে」 আমার জন্মদিন উদযাপনের কথা ভুলে গিয়ে থাকো — আমি বিশ্বাস করি এমন অবাস্তব পরিস্থিতি ঘটবে না।\nএই চিঠিটি পরিস্থিতি অপূরণীয় হওয়ার আগে, তোমাকে নিজেকে বাঁচানোর শেষ একটি সুযোগ এনে দেবে।\nসমুদ্র ও স্থলভাগের বিরল রত্ন ও সুস্বাদু খাবার, সেসব তুচ্ছ লোকেরা নিবেদন করবে, সেগুলো গুরুত্বপূর্ণ নয়।\nজমকালো উৎসব, বিস্তৃত আচার-অনুষ্ঠান, অবশ্যই আমার মর্যাদার সাথে মানানসই, কিন্তু আজ, কেন জানি না, সব কিছু একটু বিরক্তিকর মনে হচ্ছে।\nতাই, আমি সন্ধ্যার গোধূলিলগ্নে সময় বের করব, এবং আমার সাথে একান্তে সময় কাটানোর সম্মান তোমাকে উপহার দেব — এটা তোমার পুরস্কার, কারণ তুমি আমাকে এই সাধারণ, শিশুসুলভ, অথচ এতটাই সুখী জীবনে এনেছ যে আগের আমি পর্যন্ত ঈর্ষা করত।\nপরিচারক পরে আনুষ্ঠানিক আমন্ত্রণপত্র পাঠাবে, অবশ্যই, বিশ হাজার লেওফ্যাং মূল্যের একটি বাক্সে রাখা।\nকৃতজ্ঞতায় অশ্রুসিক্ত হয়ে, প্রতি বছর এই দিনে আমাকে স্মরণ করো।\n「মারফি」"
  },
