  Mail_121651_Desc = {
    Text = "প্রিয় রক্ষক,\nগত সপ্তাহের মায়াবী অবগাহনে, তুমি 「{s1}「 উপাধি অর্জন করেছ।\nগত সপ্তাহের সর্বনির্বাচন মোডে, তুমি 「{s2}「 উপাধি অর্জন করেছ, মোট জয় সংখ্যা {s3}।\nগত সপ্তাহের ড্রাফট পিক মোডে, তুমি 「{s4}「 উপাধি অর্জন করেছ, মোট জয় সংখ্যা {s5}।\nতোমার সামগ্রিক চ্যালেঞ্জ পারফরম্যান্সের ভিত্তিতে, তুমি নিম্নলিখিত অতিরিক্ত পুরস্কার পাবে; গ্রহণ করতে ভুলে যেয়ো না।"
