    Text = "প্রিয় রক্ষক:\n「কুয়াশা-আবৃত ধর্মানুষ্ঠান」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট থাকা 「কুয়াশা」-র দৃষ্টি, 「কুয়াশা」-র স্বপ্ন এবং 「কুয়াশা」-র উৎস 1: 「গোলাপ স্‌ক্রিপ *40」 হারে রূপান্তরিত হবে। অনুগ্রহ করে তোমার পুরস্কারগুলো যাচাই করতে ভুলে যেয়ো না।"
