  Mail_122568_Desc = {
    Text = "আহ, হতভাগা শিশু। তুমি এখনও টেরই পাওনি, কী গভীর হতাশার অতল তুমি এখন মুখোমুখি হতে চলেছ। কবে বুঝবে, তোমার সব নির্বাচনই সম্পূর্ণ অর্থহীন? এমন এক অধরা, নিরাশার লক্ষ্যে তোমার তুচ্ছ ছোট্ট জীবনটা বাজি রাখা? কী বীরত্ব! কী ভয়ংকর মাদকতা! তুমি সবসময় নিজেকে এমন এক উচ্চাভিলাষী ভঙ্গিতে বহন করো, যেন এইমাত্রই তুমি নিজেকে উৎসর্গ করবে পৃথিবীকে বাঁচানোর জন্য। সত্যিই, সম্পূর্ণরূপে হাস্যকর।"
  },
