  Mail_122571_Desc = {
    Text = "আমরা সবে মাত্র আবার একত্রিত হলাম, আর সত্যিকারের কিছু ভাগ করে নেওয়ার আগেই সময় ফুরিয়ে আসছে... কিন্তু জানো, %player%, বিদায় কোনোদিনই আমাদের গল্পের শেষ নয়।\n\nএকটা কথা আমি কখনো তোমাকে বলিনি... অনেক আগে থেকেই আমি তোমার জন্য গোলাপের এক তোড়া প্রস্তুত করে রেখেছিলাম। শুধু পাঠাইনি, আর ততক্ষণে তা ম্লান হয়ে গেছে। কিন্তু আমি তোমাকে এই প্রতিশ্রুতি দিচ্ছি—পরেরবার যখন আমাদের দেখা হবে, আমি অবশ্যই নতুন এক তোড়া প্রস্তুত করব।\n\nআর তুমি, তুমি আমাকে প্রতিশ্রুতি দিয়েছিলে যে তুমি আবার আমার কাছে ফিরে আসবে। আমরা আঙুল গুঁজে সেই প্রতিশ্রুতি করেছি। তুমি কোনোভাবেই সেই প্রতিশ্রুতি ভাঙতে পারো না।\nচিঠি লিখতে বসলে সবসময়ই মনে হয় তা যথেষ্ট নয়; কাগজে আমি আমার সব অনুভূতি ঢেলে দিতে পারি না। তবু... যখন ভাগ্য আবার আমাদের মুখোমুখি করবে, আমি নিজ হাতে তোমাকে সেই গোলাপের তোড়া তুলে দেব। মনে রেখো, আমাদের প্রতিশ্রুতি অবশ্যই রাখতে হবে!\n\nরূপালি চাবি তোমার পথ আলোকিত করুক। বিদায়... আমার %player%।"
