  Mail_122573_Desc = {
    Text = "আমি নীরবে অসংখ্যবার দেখেছি সভ্যতার স্ফুলিঙ্গগুলোকে সময়ের নদীতে মিটমিট করে জ্বলে উঠতে, দেখেছি স্মৃতির নগরীকে শূন্যতায় প্রাচীর পতনের মতো ভেঙে পড়তে। ইতিহাস রূপান্তরিত হয় পাণ্ডুলিপিতে, যার নিয়তি কেবল কালো শিখার খাদ্য হওয়া। যুগের প্রজ্ঞা জমা হয় বালুর মিনারের মতো, তবু শেষ পর্যন্ত একমাত্র সত্যটিকে ভাষায় ধরতে ব্যর্থ হয়।"
