  Mail_122574_Desc = {
    Text = "একজন প্রিয় মানুষকে হারানোর অসহনীয় যন্ত্রণা, নিজের অসহায়ত্বের প্রতি তীব্র ঘৃণা… আমি একসময় সেই অন্ধকারে গভীরে আটকানো ছিলাম, একেবারেই নিজেকে টেনে তুলতে অক্ষম। কিন্তু এখন, আমি দূরের বাতিঘরের আহ্বান শুনতে পাই, আর অনুভব করি তার উষ্ণ, দৃঢ়চেতা দিশা। পরম উপকারক, আপনি যখন আমাকে আত্মজাগরণ দিয়েছেন, তখন থেকেই মনে হয় আমি অবশেষে পা রেখেছি সেই পথে, যা আমার জন্যই নির্ধারিত ছিল—একটি পথ, যা সত্যিই আমার, এক অখণ্ড, ন্যায়সঙ্গত সলতের পথ।"
