    Text = "সম্মানিত রহস্যরক্ষক:\n        V2.4.0 আপডেটে, আপনি 「স্বপ্নদর্শন」 মোডে 「বিদায় নেভারল্যান্ড」 এবং 「বিদায়, নেভারল্যান্ড」 চ্যালেঞ্জের 3-তারা পুরস্কার প্রাপ্তিতে অস্বাভাবিক সমস্যার সম্মুখীন হয়েছিলেন। আপনার পূর্ববর্তী অনুসন্ধান ও চ্যালেঞ্জ ক্লিয়ারের রেকর্ড অনুযায়ী, আমরা আপনাকে পূর্বে প্রাপ্ত না হওয়া পুরস্কারগুলো একবারে প্রদান করছি। অনুগ্রহ করে গ্রহণ করুন।"
