  Mail_123501_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nএই বিশেষ দিনে, আমার মতো একটি আদুরে মেয়ের সাথে একটি দারুণ মজার ডেটে যেতে চাও না?\nএসো না এসো না, ভুতুড়ে বাড়িতে একটু ঘুরে আসলে তোমার তো আর ভয়ে প্রাণ বেরিয়ে যাবে না~ তুমি তো একজন 'গোপনরক্ষক', মানুষের সাজা 'ভূত-প্রেত-দানব' দেখে নিশ্চয়ই ভয় পাবে না, তাই তো?\n(চিঠির কাগজে একটি লাইন অযত্নে কেটে দেওয়া হয়েছে: আমি কিন্তু সত্যিই জন্মদিনের পরিকল্পনা করছি, মোটেও মজা করার জন্য তোমাকে ভয় পেতে দেখতে চাইছি না……)\nঠিক আছে, আর মজা করছি না। আজ যখন আমার জন্মদিন, আমি কিছুতেই এটা নষ্ট করতে চাই না! তাই এখন, আমি, মোশিয়া, আনুষ্ঠানিকভাবে তোমাকে লন্ডন সিটিতে নতুন খোলা সেই রেস্তোরাঁয় রাতের খাবারের জন্য আমন্ত্রণ জানাচ্ছি——\nসেখানকার গরম চা আর স্টিউ করা মাছ আমাকে 'নিজ দেশের' স্বাদের কথা মনে করিয়ে দেয়, আর এই পৃথিবীতে তুমি ছাড়া আমার সাথে ভাগ করে নেওয়ার মতো আর কেউ নেই……\nতাই তুমি অবশ্যই আসবে, তাই না? আমার মতো এত আদুরে একটি মেয়েকে যদি মন খারাপ করাও, সাবধান, পরের বার তুমি ঘুমানোর সময় কুড়াল হাতে তোমার বিছানার পাশে দাঁড়িয়ে থাকব!\n\nমোশিয়া"
  },
  Mail_123501_Name = {
    Text = "「আমাকে খোলো」"
  },
  Mail_123501_Sender = {
    Text = "মুশেট"
  },
  Mail_123543_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআরেকটি বছর, আমার প্রিয়।\nচাকচিক্যের আলো-ছায়ায়, চারদিকে ভেসে বেড়ানো গুজব আর কেলেঙ্কারির মাঝে, প্রতিটি দুর্বলতার চিহ্ন সতর্কতার সাথে লুকিয়ে রেখে, প্রতিটি মূল্যের বিনিময়ে সর্বোচ্চ লাভ আদায় করা——এমনটাই হওয়া উচিত ছিল, তাহলেই আমি এখনও বিজয়ীর ভঙ্গিতে এখানে দাঁড়িয়ে থাকতে পারতাম।\nকিন্তু তা হয়নি, আমি মাঝে মাঝে কিছুটা অলস ও দুর্বল হয়ে পড়েছি, এবং তুমি যখন চিঠি পাঠাও, তখন সেই মেয়েদের ইচ্ছাগুলো পূরণ করতে আমি বেশ আনন্দের সাথে রাজি হয়ে যাই।\nতবে আমি এটাকে কোনো খারাপ বিষয় মনে করি না, আমি ইতিমধ্যে এক দীর্ঘ গোপন যুদ্ধে অনেক বেশি সময় কাটিয়ে ফেলেছি। অবশ্যই, যতক্ষণ একটুও সম্ভাবনা থাকবে, সামান্যতম সুযোগ থাকবে, আমি বারবার 'সেই ব্যক্তির' হাত থেকে পালানোর চেষ্টা করে যাব।\nশুধু, সেই উষ্ণ ও মধুর ফাঁকগুলোতে, অথবা আজকের মতো বিশেষ দিনগুলোতে, আমি নিজেকে একটু ছুটি নেওয়ার অনুমতি দিই, যেমন——আপনাকে একসাথে একটি অপেরা দেখতে এবং একটি রাতের খাবারে আমন্ত্রণ জানানো।\nকারণ আমি জানি, আমি কখনোই একা নই, আমি ইতিমধ্যে আমার মনের মতো একজন সহযোগী পেয়ে গেছি।\n\nসোরেল"
  },
  Mail_123543_Name = {
    Text = "সহযোগী..."
  },
  Mail_123543_Sender = {
    Text = "সোরেল"
  },
  Mail_123544_Desc = {
    Text = "চিঠি খুলে শুভেচ্ছা জানাই:\n\nঅনেকদিন যোগাযোগ হয়নি, গোপনরক্ষক। ক্ষমা করবেন, এই সময়ে চিঠিপত্র বিনিময় না হওয়াটা ইচ্ছাকৃতভাবে আপনার সাথে সম্পর্ক দূরে রাখার জন্য নয়, শুধু প্রতিবার কলম তুলে নিলে, শুভেচ্ছার প্রথম লাইনটি লেখার সাহস জোগাড় করতে পারিনি।\nএই সময়ের মধ্যে, আমি অসংখ্য ভেঙে পড়া সময়ের মধ্য দিয়ে পার হয়েছি, এবং তাই বারবার পৃথিবীকে সমাপ্তির দিকে এগিয়ে যেতে দেখেছি, একের পর এক অপূরণীয় বিয়োগান্তক দৃশ্য প্রত্যক্ষ করেছি। যেন একজন দর্শক, এই শীতল নীরব শূন্যতায়, নীরবে সবকিছু ঘটতে দেখছি।\nপ্রতিবার এমন সময়ে, আমি ভাবি, আমাদের এই জীবন কি অযৌক্তিকতা আর বিচ্ছেদে পূর্ণ হতেই নির্ধারিত? সেই সময়ের নিজেই হোক, বা কাদাসে আপনি যা কিছুর মুখোমুখি হয়েছেন, ভাগ্য কি ইতিমধ্যেই সব চিত্রনাট্য লিখে রেখেছে, আর আমরা কেবল সেই চিত্রনাট্য অনুযায়ী প্রয়োজনীয় চরিত্র অভিনয় করতে পারি?\nআমি কোনো সিদ্ধান্তে পৌঁছাতে পারিনি, আমি তাঁর মতো নই, জগতের সবকিছু স্পষ্ট দেখতে পারি না, তাই আমি ভাবি, যদি……তাঁর ক্ষমতার একাংশের অধিকারী আপনি, এই প্রশ্নের উত্তর দিতে পারবেন কি?\nতাই আমি এই চিঠিটি লিখেছি, আশা করি এটি আমার দৃষ্টিকে আপনার পাশে নিয়ে যাবে, এবং আশা করি আপনার সাথে মিলে এই হয়তো চিরকাল উত্তরহীন ধাঁধাটি নিয়ে আলোচনা করতে পারব। তাই কি ধৃষ্টতা করে অনুরোধ করতে পারি, এই চিঠিটি আপনার সাথে রাখুন, এবং আপনার সাথে……সামনের পথের মুখোমুখি হতে দিন?\n………………………………\nআমি সময়-স্থান বিঘ্নিত করার ঝুঁকি নিয়ে আপনার কাছে যেতে পারি না, কিন্তু অনুগ্রহ করে আমাকে……এই শূন্য মৃত নীরবতায়, আরেকবার আপনাকে দেখতে দিন।\n\n「রামোনা」"
  },
