  Mail_123545_Desc = {
    Text = "শ্রদ্ধেয় ফ্যাকাশে দূত:\n\nএর আগে আমি মিসাগের সেই অত্যন্ত বুদ্ধিমতী মহিলাকে জিজ্ঞেস করেছিলাম, কিছু ফুল চাষ করার জন্য কোনো অব্যবহৃত জায়গা আছে কিনা।\nশ্রীমতী ডোর সহজেই আমার জন্য একটি ঘর খুঁজে দিলেন। যদিও প্রথমবার দরজা খুলতেই ভেতর থেকে ভেসে আসা বাসি গন্ধে আমার মনে হয়েছিল আমি হয়তো ভুল জায়গায় এসেছি, কিন্তু কিছুটা পরিচর্যার পর এখন এটি তার দায়িত্ব চমৎকারভাবে পালন করতে পারছে — এই ছোট্ট শিশুদের একটি উষ্ণ আশ্রয় দিতে পারছে।\nতবে অভিজ্ঞতার অভাবে, এই শিশুদের স্বাভাবিক বৃদ্ধি নিশ্চিত করতে আমাকে কিছুটা বাহ্যিক সাহায্য নিতে হয়েছে।\nসৌভাগ্যবশত, মিস ওরলার নির্দেশনায় আমি সফলভাবে তাদের বর্তমান পর্যায় পর্যন্ত লালন-পালন করতে পেরেছি।\nঅবশ্যই, এতে কোনো বিশেষ ক্ষমতা ব্যবহার করা হয়নি।\nযদি আমার হিসাবে কোনো ভুল না থাকে, তাহলে এগুলো আমার জন্মদিনের দিনই ফুটবে। যদিও আমি বারবার বলে এসেছি যে জন্মদিনে বিশেষ কিছু নেই, কিন্তু এমন বিরল কাকতালীয় ঘটনা দেখলে সত্যিই মনে না করে পারা যায় না যে, হয়তো এটি পিতৃদেবতার পক্ষ থেকে আমার জন্য সাজানো একটি ছোট্ট উপহার।\nআপনি কি এই ছোট্ট বাগানে আমার সাথে একটু সময় কাটাতে আগ্রহী, এই সাধারণ অথচ বিশেষ দিনটি একসাথে উদযাপন করতে?\nআমি নিজের হাতে বেক করা বিস্কুট এবং আপনি গতবার যে লাল চা সুপারিশ করেছিলেন তা প্রস্তুত করে রেখেছি। এই বিরল উপহার এবং জীবনের অনন্য সুগন্ধ আপনার সাথে ভাগ করে নেওয়ার অপেক্ষায় আছি।\n\nসালভাদো"
  },
