  Mail_123546_Desc = {
    Text = "পার্টনার:\n\nতুমি কি কখনো এই গল্পটা শুনেছ?\nএকসময় একটা দানব ছিল, যে দুর্ঘটনাক্রমে একটা বোতলে বন্দি হয়ে গিয়েছিল, শত শত বছর ধরে।\nপ্রথম শতাব্দীতে, সে প্রতিশ্রুতি দিয়েছিল যে তাকে মুক্ত করবে তাকে অসীম সম্পদ ও ক্ষমতা দেবে।\nদ্বিতীয় শতাব্দীতে, সে প্রতিশ্রুতি দিয়েছিল যে তাকে মুক্ত করবে তাকে চিরস্থায়ী স্বাস্থ্য ও আয়ু দেবে।\nতৃতীয়, চতুর্থ, পঞ্চম... অনেক অনেক দিন পর, অবশেষে সে সেই জেলেকে পেল যে বোতলের ছিপি খুলেছিল— সে জেলের ডাকে সাড়া দেয়নি, এমনকি পৃথিবীটাকে তছনছ করার ইচ্ছাও আর ছিল না তার, শুধু একটা সাধারণ খালি বোতলের ভান করে, নীরবে আবার সমুদ্রে ফেলে দেওয়া হলো।\nছোটবেলায় আমি এই গল্পটা বুঝতে পারিনি। যতক্ষণ না আমি জানলাম দীর্ঘ আশাহীন অপেক্ষা আসলে কতটা বিষণ্ণ ও যন্ত্রণাদায়ক, যেখানে আকাঙ্ক্ষা হতাশার চেয়েও অসহনীয় হয়ে ওঠে।\nতবুও আমার বিবেক কিছু বোঝার আগেই, আমার হৃদয় বারবার আমাকে একই জায়গায় আটকে রেখেছে।\nদানব আর মানুষের মধ্যে পার্থক্য সম্ভবত এটাই যে, আমি এই যন্ত্রণার জন্য কিছুটা কৃতজ্ঞ। কারণ যখন আমরা আলাদা থাকি, এটা আমাকে তোমার অস্তিত্ব ও মূল্যবোধের কথা মনে করিয়ে দেয়, যাতে তোমাকে ছাড়া কোনো প্রান্তে আমি হারিয়ে না যাই।\nআমার জন্মের এই দিনে, তোমাকে সবচেয়ে বেশি মনে পড়ার এই দিনে, এটা এখনও ভারী হয়ে আমাকে বেঁধে রাখে, আমাকে এখনও তোমার জন্য অপেক্ষা করায়, তোমাকে মনে করায়।\nআশা করি পরের আজকের দিনে, আমি নিজের হাতে তোমাকে আমার কাটা প্রথম টুকরো কেক দিতে পারব।\n\nরামোনা"
  },
  Mail_123546_Name = {
    Text = "একটি গল্প..."
  },
  Mail_123546_Sender = {
    Text = "রামোনা"
  },
  Mail_123547_Desc = {
    Text = "মিসাগের ক্যান্টিন এবং লজিস্টিক বিভাগ আমার ঘরের দরজায় একগাদা অপ্রয়োজনীয় জিনিস রেখে গেছে, যেগুলো চলাফেরায় চরম বিঘ্ন ঘটাচ্ছে। তোমরা যত তাড়াতাড়ি সম্ভব এগুলো ফেরত নিয়ে যাও।\nকী হয়েছে, এই পৃথিবীতে খাদ্যসামগ্রী এত বেশি যে আর কোনো অর্থবহ জায়গায় পাঠানোর নেই?\nএই দিনটা আমার শক্তিশালী হওয়ার পথে শুধু একটা পাদটীকা, আরেকটা চক্র পেরিয়ে যাওয়ার চিহ্ন মাত্র। এক বছর, তারপর আরেক বছর—প্রতি বছর আমি আগের বছরের চেয়ে আরও শক্তিশালী হব।\nউপহারগুলো রাখার জায়গা না থাকলে অন্য আমাকে দিয়ে দাও, সে সম্ভবত খুবই খুশি হবে।\nআর আমি... তোমাদের সেই বোকা বোকা সরলতা আর জেদের খাতিরে... যেসব বিষয়ে আমি সবচেয়ে কম পারদর্শী, সেগুলোর খাতিরে।\nযতদিন আমি টিকে থাকব, ততদিন আমি শক্তিশালী হতে থাকব, আর সেই সাথে...\nএখনও বুঝতে পারছ না? তোমরা বোকাদের শত্রু, আমারও শত্রু হবে।\nএই বিরক্তিকর কথা আমি একবারই বলব। আগামী বছর আর উপহার পাঠাবে না, আর জন্মদিনের রাতের খাবারের তো প্রশ্নই ওঠে না।\n\n「H」"
  },
  Mail_123547_Name = {
    Text = "কোনো উপহার নয়।"
  },
  Mail_123547_Sender = {
    Text = "「এইচ」"
  },
  Mail_123548_Desc = {
    Text = "প্রিয় রহস্যরক্ষক:\n\nতুমি কি জানো? কিছুদিন আগে, একজন রহস্যময় মহিলা হঠাৎ মিসাগে দেখা করতে এসেছিলেন। তিনি এমন একটি ঝকঝকে কালো রঙের আঁটসাঁট লম্বা গাউন পরেছিলেন যা আমি আগে কখনো দেখিনি — আমি জেনকিন আর মেসনকে জিজ্ঞেস করেছিলাম, তারাও এত সুন্দর পোশাক কখনো দেখেনি।\nকীভাবে বর্ণনা করব? সেই পোশাকটা যেন সবচেয়ে সুন্দর লম্বা চুল দিয়ে বোনা, নরম, হালকা আর মার্জিত, আর এর উপরিভাগে জলের মতো এক বিশেষ দীপ্তি বয়ে যাচ্ছিল...\nজেনকিন দেখল আমি খুব কৌতূহলী, তাই সাহস করে সেই রহস্যময় মহিলাকে জিজ্ঞেস করল। তিনি হেসে বললেন যে গাউনটির উপাদান হলো প্রাচ্য থেকে আসা রেশম, 「রেশমকীট」 নামক এক ধরনের শূককীট যে সুতো বের করে তা দিয়ে বোনা, আর এই ধরনের পোশাকটিকে বলা হয় 「চিপাও」... তারপর, তিনি এগিসকে একটি বড় থান — তিনি বলেছিলেন সেটাকে 「এক থান」 বলে — একই রকম 「রেশম」 উপহার দিলেন...\n「রেশম」 অত্যন্ত মূল্যবান, তাই তিনি যে নকশা সাথে দিয়েছিলেন তা অনুসরণ করে আমি প্রত্যেক সঙ্গীর জন্য একটি করে 「থলি」 সেলাই করেছি। এ বছরের জন্মদিনের অনুষ্ঠানে, আমি সবাইকে 「থলি」 উপহার দেব... রহস্যরক্ষক, তুমি কি সময় করে আসতে পারবে?\nযদি তুমি খুব ব্যস্ত থাকো, তাহলে আমি ব্রাউনকে দিয়ে থলিটা তোমার আবাসে পাঠিয়ে দেব।\n\nএগিস"
  },
  Mail_123548_Name = {
    Text = "রহস্যময়ী নারী"
  },
  Mail_123548_Sender = {
    Text = "আইগিস"
  },
  Mail_123549_Desc = {
    Text = "ছোট্ট চারাগাছ:\n\nতুমি কি জানো গাছ কীভাবে সময় আর বেড়ে ওঠার কথা লিখে রাখে? একটার পর একটা বার্ষিক বলয়ের মাধ্যমে।\nসেগুলো দেহের গভীরে লুকিয়ে থাকে, কখনো সহজে কাউকে দেখায় না, যতক্ষণ না একটি ক্ষুদ্র নতুন অঙ্কুর ধীরে ধীরে বেড়ে উঠে আকাশছোঁয়া মহীরুহ হয়ে ওঠে, আকাশের এক কোণকে ধরে রাখে। সেই কালের চিহ্নগুলো নিঃশব্দে হৃদয়ের গভীরে লুকিয়ে থাকে।\nআজ, নতুন একটি বার্ষিক বলয় রচনার শুরু। নতুন এই বছরে, আমাদের এখনো অনেক অপ্রত্যাশিত ঝড়-বৃষ্টির মুখোমুখি হতে হবে।\nকিন্তু আমি তোমার কাছে যে বীজটি গচ্ছিত রেখেছি, সেটি নিশ্চয়ই তার উপযুক্ত মাটি খুঁজে পাবে, তারপর শিকড় ছড়িয়ে অঙ্কুরিত হবে, তাই না?\n\nতাইয়ীসি"
  },
  Mail_123549_Name = {
    Text = "বৃদ্ধির বলয়..."
  },
  Mail_123549_Sender = {
    Text = "থাইস"
  },
  Mail_123644_Desc = {
    Text = "নিজের অজান্তেই, মিসাগে কাটানো এটা আমার তৃতীয় জন্মদিন। আমি অনেক কিছু শিখেছি।\nযেমন, আমার জন্মদিনের এই দিনটি একই সাথে শীতযাত্রা উৎসবও—উপহার দেওয়ার জন্য একটি উপযুক্ত দিন।\nযদিও তোমার অত্যন্ত শক্তিশালী অসংখ্য শত্রু আছে, কিন্তু আমি সবচেয়ে ভালো যেটা পারি তা হলো মানুষ হত্যা করা। মানুষকে খুশি করার অন্য কোনো উপায় আমার জানা নেই, উপহার বাছাইতেও আমি দক্ষ নই, তবে প্রতিবার সফলভাবে কাজ সম্পন্ন করলে আমার নিয়োগকর্তারা বেশ খুশি হন বলে মনে হয়।\nতাই আমি ইতিমধ্যেই ঠিক করে ফেলেছি তোমাকে কী উপহার দেব—একটি হত্যার অনুরোধ, লক্ষ্যবস্তু যে কেউ হতে পারে, কোনো সময়সীমা নেই।\nশুধু আমাকে বলো, লক্ষ্য কে, এবং তুমি চাও সে কীভাবে মরুক? যদি এমন কেউ হয় যাকে আমি পরাজিত করতে পারি, আমি দ্রুততম গতিতে তার ঘাড় মটকে দেব। আর যদি সে দেবতার মতো দুর্ধর্ষ কেউও হয়, আমি তোমাকে প্রতিশ্রুতি দিতে পারি—আমার মৃত্যুর আগে আমি কখনো হাল ছাড়ব না।\n\nশিলো"
  },
  Mail_123644_Name = {
    Text = "কারো মৃত্যু চাই?"
