  Mail_124059_Desc = {
    Text = "প্রিয় রক্ষক:\n「অতল যজ্ঞ·রিরান」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট 「উৎসর্গকারীর অশ্রু」, 「উৎসর্গকারীর রক্ত」 এবং 「উৎসর্গকারীর মজ্জা」 প্রতিটি আইটেমের জন্য 「রোজ স্ক্রিপ* 40」 হারে রূপান্তরিত হবে। অনুগ্রহ করে তোমার পুরস্কারগুলো পরীক্ষা করতে ভুলবে না।"
  },
  Mail_124059_Name = {
    Text = "অতল যজ্ঞের মুদ্রা রূপান্তরিত"
