  Mail_124059_Sender = {
    Text = "মিথাগ বিশ্ববিদ্যালয় কমিটি"
  },
  Mail_124290_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআপনি যেমন জানেন, আনন্দ আমার কাছে আসলে কিছুটা অপরিচিত একটি অনুভূতি।\nআমি প্রায়ই মনে করি, সাধারণ জগৎ হলো জলের উপরিভাগের এক কোলাহল যা আমি বুঝতে পারি না, আমি এতে মিশে যাওয়ার আগেই আমার জন্য নির্ধারিত শুষ্কতা এসে পড়ে।\nএটি মাঝে মাঝে আমাকে আকৃষ্ট করে, কিন্তু বেশিরভাগ সময় আমাকে বিভ্রান্ত ও শ্বাসরুদ্ধ করে তোলে। শুধু আজকের মতো প্রতিটি দিনে, বাবা আর মাকে কষ্ট না দেওয়ার জন্য, আমি প্রাণপণে সহ্য করে যাই……যতক্ষণ না মুক্তির সেই দিন আসে, যতক্ষণ না সমুদ্র আমাকে গ্রহণ করে।\nআমি ভেবেছিলাম, শুধু গভীর জলই আমার আশ্রয়স্থল। কিন্তু, গোপনীয়তার রক্ষক, আপনার কারণে, এবং মিসাগের সকলের উপস্থিতির কারণে, আমার মতো সাধারণ জগতের সাথে বেমানান কেউও কিছু প্রকৃত উষ্ণতা অনুভব করতে শুরু করেছে। যেমন শাপলা যখন জলের উপরে ভেসে ওঠে, সূর্যের আলোও তার পাতা ও পাপড়িকে চুম্বন করে।\nযদিও এলোমেলো, তবুও আমি মনে করি এই অনুভূতিগুলো যেভাবেই হোক কাগজে লিখে আপনার কাছে পাঠানো দরকার, আমার মাঝে মাঝে এই খেয়ালিপনা ক্ষমা করবেন।\nআমি শুধু চাই আপনি জানুন, অকালে নির্জনতায় চাপা পড়া জলের মধ্যে, আপনি আমাকে কতটা মূল্যবান ভাসমানতা এনে দিয়েছেন।\nআপনি চিরকাল আনন্দে থাকুন, চিরকাল শান্তিতে থাকুন।\n\nনিমফিয়া"
  },
  Mail_124290_Name = {
    Text = "ভাসমানতা..."
