  Mail_124291_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআজ ভোরবেলা, আমার বিছানার পাশে একটি চিঠি দেখা গেল। এতে আমাকে আমার নিজের জন্মদিনের ভোজসভায় আমন্ত্রণ জানানো হয়েছে, এবং প্রেরক হলো 「চিত্রকর」 ক্লাব।\nতখনই আমার মনে পড়ল যে গত মাসে কিছুটা অবসর পেয়ে আমি শানের অনুরোধে 「চিত্রকর」 ক্লাবের নতুন সৃজনশীল প্রতিযোগিতায় মডেল হতে রাজি হয়েছিলাম। এর আগে আমি কতবার যে প্রত্যাখ্যান করেছি তার হিসাব নেই। মডেলের মঞ্চে নিশ্চল দাঁড়িয়ে সবাইকে আমাকে আঁকতে দেওয়ার সেই সময়গুলোতে, আমার মনে পড়ে গেল সমুদ্রযাত্রীদের বেদিতে থাকার দিনগুলোর কথা। তখনও আমি সকলের দৃষ্টির কেন্দ্রবিন্দু ছিলাম, কিন্তু সেই দৃষ্টিতে ছিল শুধু ভয় আর সমীহ — এক বিন্দু আবেগ, প্রশংসা বা মুগ্ধতা ছিল না।\nআজ রাতে চিত্রকর ক্লাবের মূল হলে আয়োজিত জন্মদিনের কোল্ড বুফেতে, সেদিনের দশজনেরও বেশি চিত্রকরের যত্নে আঁকা হাতে-আঁকা শিল্পকর্মগুলোও প্রদর্শিত হবে। যদিও তোমার রুচিবোধ নিয়ে আমার তেমন আস্থা নেই, তবু শিল্পের সংস্পর্শে আসা কখনও মন্দ হতে পারে না। দেবীমাতা তোমাকে বিশেষ অতিথি হিসেবে আমন্ত্রণ জানাচ্ছেন — এসো, একসাথে তাদের 「আমার」 ব্যাখ্যা উপভোগ করি।\n\n「মারফি」"
  },
  Mail_124291_Name = {
    Text = "চিত্রকর..."
