  Mail_124291_Sender = {
    Text = "\"মার্ফি\""
  },
  Mail_124292_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nসিলভিয়া আমাকে বলেছে, মাঝে মাঝে ঘনিষ্ঠ কারো কাছে নিজের চাহিদা প্রকাশ করলে সেই ভয়টা কমতে পারে যা প্রতিটি মুহূর্তে আমাকে তাড়া করে। আমি নিশ্চিত নই এটা কাজ করবে কিনা, তবে নিঃসন্দেহে আজ একটা ভালো সময়।\nতুমি কি আমার একটা ইচ্ছা পূরণ করবে? আমি আজকের ল্যাবরেটরির পুরো রেশন তোমাকে দিতে পারি।\nনা, এক প্যাকেট কফি বিন নয়।\nযদিও সেই ভয়ংকর অন্ধকার আমার প্রায় সব ঘনিষ্ঠ সম্পর্ক কেড়ে নিয়েছে, ছায়ার মতো আমাকে তাড়া করে ভয় দেখাচ্ছে, তবুও তুমি তো এটাকে জয় করেছ।\nতুমি আমাদের মিসাগে নিরাপদে বাঁচতে দিয়েছ, অথবা অন্তত এখন পর্যন্ত নিরাপদে বাঁচতে দিয়েছ।\nএবার অস্বাস্থ্যকর ক্যাফেইন নির্ভরতা থেকে মুক্তি পাওয়ার সময় এসেছে, গোপনীয়তার রক্ষক, তুমি কি আজ সন্ধ্যায় একটু সময় বের করতে পারবে?\nতুমি যদি আমার পাশে থাকো, তাহলে হয়তো আমি সাহস করে আলো কম এমন কোনো জায়গায় একটু ঘুমিয়ে নিতে পারব, এমনকি সামান্য একটু হলেও।\n\nনিশ্চিন্তে ঘুমানো কেমন লাগে তা মনে করতে চাওয়া ভিনকোর"
