  Mail_124293_Desc = {
    Text = "গোপনরক্ষক{Male=先生,Female=小姐}：\n\nআজ ভোরে একটি স্বপ্ন আমাকে জাগিয়ে তুলল।\nআমি স্বপ্নের প্রতিটি মুহূর্ত মনোযোগ দিয়ে স্মরণ করলাম: উষ্ণ রোদের নিচে মৃদু বাতাস বইছে, গোলাপ আর টিউলিপে ছেয়ে গেছে সমস্ত ভূমি, হাজারটি রূপালি গাংচিল আনন্দিত মানুষদের সাথে সমস্বরে গান গাইছে……এত সুখের দৃশ্যে আমি অনেকদিন নিজেকে খুঁজে পাইনি। মনে হলো আমি হয়তো শৈশবের জমিদারিতে, কোরেতের ফুলঘরে, অথবা সিদাইয়ের কোনো উদ্যানে……কিন্তু যখন আমি ঘুরে দাঁড়ালাম, আমি দেখলাম মিসাগের সেই সুন্দর গথিক ভবনগুলো, আর আপনাকে, গোপনরক্ষক{Male=先生,Female=小姐}। আপনি ফুল আর রোদের মাঝে দাঁড়িয়ে, এই কবিতার সবচেয়ে মনোরম পঙ্ক্তি হয়ে উঠেছিলেন।\nআমি সিদাইকে গভীরভাবে ভালোবাসি, গোপনরক্ষক{Male=先生,Female=小姐}। কিন্তু সেই মুহূর্তে হঠাৎ আমি উপলব্ধি করলাম, আমি এখানকার সবকিছুতে অভ্যস্ত ও মুগ্ধ হতে শুরু করেছি, এই পৃথিবীতে অবশেষে সিদাইয়ের চেয়েও বেশি আমার হৃদয়কে আকুল করে এমন একটি জায়গা খুঁজে পেয়েছি।\nজন্মদিন হলো একটি যুগের সমাপ্তি, আবার আরেকটি যুগের সূচনাও। নতুন যুগের শুরুর এই দিনে, জানি না মিসাগের পেছনের বাগানে প্রস্ফুটিত রোদ আর গোলাপের মাঝে, সেই ব্যক্তি কি থাকবেন যিনি আমাকে সাথে নিয়ে মৃদু বাতাসের সুর শুনতে চান, যিনি আমার হৃদয়কে আকুল করেন?\n\nঅরলা"
  },
  Mail_124293_Name = {
    Text = "ফুল ও কবিতার স্বপ্ন"
