  Mail_124293_Sender = {
    Text = "হর্লা"
  },
  Mail_124294_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nকিছুদিন আগে, আমি সবসময় ভাবছিলাম তোমাকে একটা বিশেষ উপহার দেব। জেনকিন প্রস্তাব দিল যে তোমার জন্য নিজের হাতে একটা নতুন পোশাক বানালে কেমন হয়, আমার মনে হলো এর চেয়ে ভালো আইডিয়া আর হতে পারে না।\nএটা আমার বস্ত্র কারখানায় কাজ করার সময়কার সবচেয়ে দক্ষ কাটিং স্টাইল, আশা করি এখনকার দিনে এটা খুব বেশি সেকেলে লাগবে না……অন্যরাও বিরলভাবে আমার সিদ্ধান্তকে সমর্থন করেছে, উপরের ওই প্রাণবন্ত ডোরাকাটা আর চেক প্যাটার্নগুলো বিভিন্ন আমি মিলে তৈরি করেছে। আর এই বাঁকাচোরা আদুরে ইঁদুরের নকশাটা বিড়াল 「24」 জোর দিয়ে যোগ করতে চেয়েছে, বলেছে এটা ব্রাউনকে প্রতিনিধিত্ব করে, বিড়াল ব্যক্তিত্বের আমার সবচেয়ে প্রিয় জিনিস——জানি না এটা মানানসই কিনা, তবে আশা করি তোমার ভালো লাগবে।\nনতুন বছরে, আমার এখনও তেমন কোনো জন্মদিনের ইচ্ছা নেই। তুমি সবসময় এত স্নেহশীল, প্রতি বছর আমাকে ভালোভাবে উদযাপন করতে বলো। কিন্তু উদযাপিত হওয়ার চেয়ে, তোমার জন্য নিজের হাতে কিছু সেলাই করতে পারাটা আমাকে বেশি স্বস্তি আর আনন্দ দেয়।\nদয়া করে হৃদয়ের ভালোবাসায় পরিপূর্ণ এই নতুন পোশাকটা গ্রহণ করো।\n\nমেসন"
