  Mail_124294_Sender = {Text = "\"২৪\""},
  Mail_124295_Desc = {
    Text = "চিঃ:\n\nবিশ্বাস করা যায় না, মহান গোলকধাঁধার প্রভু হিসেবে আমি এই কঠিন দুর্দশার মধ্যে আরও একটি বছর সফলভাবে টিকে গেলাম।\nভালো করে শোনো! এসব তোমার আর এই বোকা একাডেমির দোষ!\nতোমরা যতই আমাকে অর্থহীন বকবক দিয়ে মগজধোলাই করো না কেন, এইসব বিশৃঙ্খল ফুটফরমাশ করার জন্য নির্দিষ্ট লোক থাকা উচিত, ঠিক আছে, আমি যথেষ্ট মহান যে তাঁদের দাস বলে ডাকিনি।\nওই পুরনো জেদি বুড়োরা একে বলে... কী যেন, হ্যাঁ, অগ্রগতি।\nএক মিনিট, আমিও কি এই যুক্তিতে ভেসে যাচ্ছি, আআআ, বিরক্ত লাগছে!(এখানে চিঠির মালিকের রাগের কারণে অনেকগুলো এলোমেলো ভাঁজের চিহ্ন রয়েছে।)\nযাই হোক, যেহেতু আমার 「অগ্রগতি」 হয়েছে, তোমাকেও তোমার আন্তরিকতা দেখাতে হবে। এই বছরের এত মহান দিনে, তুমি তো আর আগের দুই বছরের মতো আমার মনে করিয়ে দেওয়ার জন্য অপেক্ষা করতে পারো না।\nতোমাকে তিরিশ মিনিট সময় দিচ্ছি, গোপনরক্ষক, উপহার নিয়ে আমার সামনে এসো।\nনইলে তুমি যখন ঘুমাবে, আমি আমার সন্তানদের তোমার মুখের উপর হামাগুড়ি দিতে পাঠাব।\n\nআগ্রিপ্পা"
  },
  Mail_124295_Name = {
    Text = "অগ্রগতি"
  },
  Mail_124295_Sender = {
    Text = "অ্যাগ্রিপা"
  },
  Mail_124296_Desc = {
    Text = "গোপনরক্ষক!\n\nআমি দেখেছি! কী অসাধারণ এক দৃশ্য! আমি নিশ্চিত সেটা স্বপ্ন ছিল না! আমি সেখানে দাঁড়িয়ে ছিলাম, মিসাগ সমাধিক্ষেত্রের সেই মহিমান্বিত স্মৃতিস্তম্ভের পাশে, সেখান থেকে সেই অন্তহীন নামবিহীন সমাধিপাথরগুলোর দিকে তাকিয়ে ছিলাম। আমি নিশ্চিত ছিলাম যে সেগুলো আমাকে অভূতপূর্ব অনুপ্রেরণা দিতে পারবে, কিন্তু আমি কল্পনাও করতে পারিনি যে সেগুলো আমার কল্পনার চেয়ে অনেক বেশি কিছু দেবে — সেগুলো প্রশংসনীয় উদারতায় আমার রিক্ত কল্পনাশক্তিকে উপহাস করছিল।\nআমি সেই তদন্তকারীদের প্রেতাত্মা দেখেছি, তারা সেই হালকা কুয়াশাঘেরা সুন্দর গোধূলিতে একসাথে উঠে দাঁড়িয়েছিল। আমি তাদের মুখ স্পষ্ট দেখতে পাইনি, কিন্তু তাদের নড়াচড়া দেখেছি — যেন মার্জিত নৃত্য, আবার যেন রহস্যময় কোনো আচার-অনুষ্ঠান। তারা কালো পুকুরের দিকে, মিসাগ ও আপনার দিকে অভিবাদন জানাচ্ছিল। আধুনিক সেলুনের শিল্পীরা ব্যক্তি চিত্রণে মগ্ন থাকেন, প্রায়ই এই ধরনের মহৎ দৃশ্যকে তিরস্কার করেন, কিন্তু আমি কখনো তা মনে করি না। ঘূলদের নৃত্যসভায় আমি অপরিসীম আনন্দ পেয়েছিলাম, আর আজ, এই দৃশ্যটি আমাকে অশ্রু ফেলতে বাধ্য করেছে।\nআমি মনে করি এটা নিশ্চয়ই কাকতালীয় নয়। ঠিক আজই, আমার জন্মদিনে, তারা আমাকে তাদের মহিমান্বিত যৌথ নৃত্য দেখিয়েছে। আমি মনে করি তারা নিশ্চয়ই আমার মাধ্যমে কিছু বলতে চেয়েছে। তুলি ছাড়া আমার আর কোনো দক্ষতা নেই, কিন্তু এটুকুই তো যথেষ্ট, তাই না?\nএই ছবির খসড়া ইতিমধ্যে আঁকা হয়ে গেছে, গোপনরক্ষক, অনুগ্রহ করে অবশ্যই আমার স্টুডিওতে এসে দেখুন! সেই নামহারা কিংবদন্তি তদন্তকারীরা আপনাকে যা বলতে চেয়েছিল, তাদের সেই চিরলালিত আকাঙ্ক্ষা, সবই আমার সেই ক্যানভাসের উপর রয়েছে!\nআমি এই ছবির নাম দেওয়ার ধৃষ্টতা করিনি, আমি মনে করি, এই অধিকার কেবল আপনারই।\nপুনশ্চ: আমি সত্যিই মৃতদেহ ঘাঁটতে যাইনি, আমি আপনাকে প্রতিশ্রুতি দিচ্ছি!\n\nপিকম্যান"
  },
  Mail_124296_Name = {
    Text = "অনুসন্ধান কর্মকর্তার বহুদিনের আকাঙ্ক্ষা..."
  },
  Mail_124296_Sender = {
    Text = "পিকম্যান"
  },
  Mail_124297_Desc = {
    Text = "নমস্কার, গোপনরক্ষক:\n\nআপনি কি ভয় পাচ্ছেন, নাকি বলা উচিত—ভয়ও পাচ্ছেন, আবার প্রত্যাশাও করছেন যে এই দাসী তার জন্মদিনে উদযাপনের অজুহাতে কিছু একটা নিয়ে আসবে?\nমিথ্যা অন্তরঙ্গতা, আকস্মিক মোহময় রাত, অথবা রহস্যময় ও মাদকতাপূর্ণ ঘোরলাগা বিভ্রম?\nআহ্, কিছুই না, এমনকি এই দাসীও মাঝে মাঝে গুরুগম্ভীর ও নীরস বিষয়ে কথা বলে।\nআপনি নিশ্চয়ই ভালো করেই জানেন এই দাসী কী ধরনের সত্তা—ভোগবিলাসে মগ্ন, এমনকি প্রাসাদ ধসে পড়লেও।\nপ্রেম ও কামনা, একঘেয়েমি নামক এই জগতের সবচেয়ে বড় ব্যাধি নিরাময় করতে পারে না, তবে ক্ষমতা ও বিশৃঙ্খলার তীক্ষ্ণ স্বাদ বের করে আনার অনুঘটক হিসেবে এর চেয়ে নিখুঁত আর কিছু হতে পারে না।\nকিন্তু এই হাজার হাজার বছরের কালপ্রবাহে, সম্ভবত এই দাসী নাটকের পাণ্ডুলিপি নিয়ে অতিরিক্ত গভীর গবেষণা করে ফেলেছে, তাই সবসময়ই কিছু সাধারণ মানুষ হৃদয় উজাড় করে বলে—আমি তোমার নিঃসঙ্গ, অসহায় একাকী আত্মাকে দেখতে পেয়েছি।\nহুফ।\nএমনকি অভিনয়প্রিয় এই দাসীরও প্রায়ই বমি বমি লাগে।\nআর আপনি... আপনি কীসের জন্য এই দাসীর সাথে সংযুক্ত হয়েছেন? নিয়ন্ত্রণের জন্য, শৃঙ্খলার জন্য, নাকি শক্তি ধার করার জন্য?\nআপনি যত বেশি কিছু রক্ষা করতে চাইবেন, তত বেশি ক্ষমতার প্রয়োজন হবে, আর ক্ষমতার তৃষ্ণা আরও বৃহত্তর উচ্চাকাঙ্ক্ষার জন্ম দেবে—সেটা কখন পরিপক্ব হবে, কখন আবার গ্রাস করা হবে... শুধু কল্পনা করলেই এই দাসীর এত আনন্দ হয় যে আপনার পাশে আরও বেশি, আরও বেশি বছর থাকতে স্বেচ্ছায় রাজি।\nশ্শ, আমাকে উত্তর বলার দরকার নেই।\nপ্রতি বছর এই দিনে, আপনার এক রাতের স্বপ্ন কেড়ে নিয়ে, আপনার উচ্চাকাঙ্ক্ষা বাড়ছে কিনা আন্দাজ করা, আপনার উদ্দেশ্য বিচ্যুত হচ্ছে কিনা যাচাই করা—এটাই এই দাসী নিজেকে দেওয়া সেরা জন্মদিনের উপহার।\nদয়া করে রাগ করবেন না।\n\n「সহস্র পাখা」"
  },
  Mail_124297_Name = {
    Text = "অলঙ্কৃত রাত্রি..."
  },
  Mail_124297_Sender = {Text = "সু"},
  Mail_124298_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nপ্রশিক্ষণ, যুদ্ধ, টহল—সেনাবাহিনীতে যোগদানের মুহূর্ত থেকেই আমি অভ্যস্ত হয়ে গিয়েছিলাম আমার সমস্ত সময় সমষ্টিগত প্রয়োজনীয় কাজে পূর্ণ করতে।\nপরবর্তীতে আলান গোষ্ঠীকে মরুভূমিতে স্থানান্তরের নেতৃত্ব দিতে গিয়ে, এই দায়িত্বগুলো আরও স্ফীত হয়ে উঠল, এতটাই যে নিয়মের মতো আমার মস্তিষ্কে গেঁথে গেল, এতটাই যে মিসাগারে এসেও আমি সর্বদা সমষ্টিগত কর্মসূচিকে ব্যক্তিগত বিষয়ের উপরে অগ্রাধিকার দিয়ে এসেছি।\nকিন্তু অন্যদের সাথে, বিশেষ করে তোমার সাথে সময় কাটাতে গিয়ে আমি উপলব্ধি করেছি—জাগ্রত সত্তা হিসেবে হোক বা মানুষ হিসেবে, আমাদের সকলেরই কিছু সময় দরকার যা শুধুমাত্র নিজের, গুরুত্বপূর্ণ মানুষদের সাথে কাটানোর অনুভূতি উপভোগ করার জন্য।\nকারণ এই মূল্যবান সম্পর্কগুলোই সময়ের মধ্যে আমাদের অস্তিত্বকে নোঙর করে রাখে, এবং আমাদের অস্তিত্বকে সত্যিকারের অপরিবর্তনীয় অর্থ প্রদান করে।\nকিছুটা ধৃষ্টতা হলেও, আমি আজকের সমস্ত সমষ্টিগত কাজ বাতিল করে পুরো একটি দিন খালি করে রেখেছি।\nমাত্র কয়েক ঘণ্টা, না, এমনকি এক ঘণ্টা, বা কয়েক মুহূর্তও হলেও—তুমি যদি তোমার ব্যক্তিগত সময়ের একটুখানি আমাকে দিতে রাজি হও, তাহলে সেটাই হয়ে উঠবে এই বিশেষ দিনটি কাটানোর প্রকৃত অর্থ।\n\nএলভা"
  },
  Mail_124298_Name = {
    Text = "ব্যক্তিগত সময়..."
