  },
  Mail_124299_Desc = {
    Text = "ছোট্ট বন্ধু:\n\nএক বছরের সময় তোমার কাছে হয়তো দীর্ঘ, কিন্তু মূল সারসত্তার সাগরের পরিব্রাজকের কাছে, এটি সময়ের অসীম মহাসাগরে ক্ষণিকের এক মুঠো জল মাত্র। সৌভাগ্যবশত, এই জলের মধ্যেও কিছু স্মরণীয় স্ফটিক-স্বচ্ছ জলবিন্দু রয়েছে।\nচিন্তামুক্ত দোকানের ছাড়ের দিন, স্বাভাবিকভাবেই তার মধ্যে সবচেয়ে সংরক্ষণযোগ্য সেই একটি। শুধু এই কারণে নয় যে এটি সোনার কুপন নিয়ে আসে, বরং আরও গুরুত্বপূর্ণ হলো, আমি জানি এই দিনে একজন অতিথি অবশ্যই এই ছোট্ট দোকানে আসবে।\nমানুষে মানুষে সকল সংযোগই ব্যবসা, আর সকল ব্যবসাও মানুষে মানুষে সংযোগ। প্রতিটি অতিথি একটি নির্দিষ্ট সময়ে তাদের জন্য নির্ধারিত দোকানে প্রবেশ করে, প্রতিটি দোকান একটি নির্দিষ্ট সময়ে তার জন্য নির্ধারিত অতিথিকে স্বাগত জানায়। দীর্ঘ সময়ের মধ্যে, আমি অগণিত মূল্যবান সম্পদ দেখেছি, কিন্তু শেষ পর্যন্ত, এই সরল মুহূর্তগুলোই সবচেয়ে মূল্যবান সংগ্রহে পরিণত হবে — এগুলোই এই দীর্ঘ সময়ের অস্তিত্বের কারণ।\nএই এক বছরের সবচেয়ে মূল্যবান নতুন সংগ্রহটি প্রদর্শনী আলমারিতে রাখা আছে, নীরবে তার জন্য নির্ধারিত সেই অতিথির অপেক্ষায়।\nতাড়াতাড়ি এসো, ছোট্ট বন্ধু।\nচিন্তামুক্ত দোকান আজ অনেক আগেই বন্ধ হয়ে গেছে। আজ, এর দরজা শুধু একজনের জন্যই খোলা।\n\nদাফদেল"
  },
  Mail_124299_Name = {
    Text = "নতুন সংগ্রহযোগ্য..."
  },
  Mail_124299_Sender = {
