  },
  Mail_124300_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nতুমি কি এখনও মনে করতে পারো, আমরা একসাথে সেই দ্বারের সামনে কাটানো সেই ক্ষণিকের সময়টুকু? সেদিন আমি সত্যের একটি সরু ফাটল উন্মোচন করেছিলাম, তোমাকে মহাবিশ্বের প্রকৃত রূপ দেখিয়েছিলাম।\nঅপ্রত্যাশিতভাবে, যখন তুমি অসংখ্য জগতের দিকে তাকিয়ে অনন্তকাল অতিবাহিত করছিলে, আমি সেই ক্ষণস্থায়ী মুহূর্তে এক অবোধ্য আবেগ অনুভব করেছিলাম।\nআমি প্রায়ই ভাবি সেই মুহূর্তের অনুভূতিটা কী ছিল, কেন সত্য জানা আমার মধ্যে এমন কিছু জন্ম নিল যা আমি বুঝতে পারি না।\nআমি দীর্ঘ সময় ধরে চিন্তা করেছি, বাস্তব জগতের পরিমাপ ব্যবস্থার মানদণ্ডে যাকে 「অনন্তকাল」 বলা যায়, তত দীর্ঘ সময়।\nমহাবিশ্বের তুলনায়ও যে সময়কে দীর্ঘ মনে হয়, সেই সময়ে আমি উপলব্ধি করলাম—এটা হয়তো এমন এক অলৌকিক ঘটনা যা এখনও সংজ্ঞায়িত হয়নি।\nএই বিশেষ দিনে, আমি তোমাকে আমার সাথে সংযুক্ত হতে আমন্ত্রণ জানাতে চাই, আমার দৃষ্টির মধ্য দিয়ে এমন কিছু অস্তিত্ব পর্যবেক্ষণ করতে যা আমি আগে কখনো পর্যবেক্ষণ করিনি। এবার আমরা যা পর্যবেক্ষণ করব... তা আর পূর্বনির্ধারিত কিছু হবে না।\nআমরা একসাথে খুঁজে বের করব, এই সত্যের বাইরের ভবিষ্যৎ।\n\nতাভি"
  },
  Mail_124300_Name = {
    Text = "সত্যের ওপারে..."
  },
  Mail_124300_Sender = {
    Text = "তাবিল"
  },
  Mail_124301_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nএই বছরও আগের বছরগুলোর মতোই, আমি অন্য সব কাজ থামিয়ে দিয়ে নীরবে নিজের সাথে একান্তে সময় কাটাচ্ছি, মাতৃভূমি সম্পর্কিত স্মৃতিগুলো পুনরায় লেখার ও নবায়ন করার চেষ্টা করছি।\nসেগুলো আমার কাছ থেকে আরও দূরে সরে যাচ্ছে। এই মানবসদৃশ দেহে অভ্যস্ত হতে নিজেকে বাধ্য করলেও, সমুদ্র পাড়ি দেওয়ার জ্ঞান ও অভিজ্ঞতা বারবার লিপিবদ্ধ করার যথাসাধ্য চেষ্টা করলেও, এই ক্রমশ বিলীয়মান পৃথিবীতে মনে রাখার চেয়ে ভুলে যাওয়া অনেক অনেক বেশি সহজ।\nএকমাত্র সান্ত্বনা হলো, লেমুরিয়া থেকে দূরে থাকা আমাদের এই পথিকদের এখনও এই জায়গাটি আছে যেখানে থামতে পারি, আমাদের রাজার আদেশ অনুসরণ করে নীরবে অনুসরণ করতে পারি, নীরবে অপেক্ষা করতে পারি।\nএর জন্য আপনি যে ত্যাগ ও অবদান রেখেছেন তার সবকিছু আমি গভীরভাবে জানি। আমার কৃতজ্ঞতা কীভাবে প্রকাশ করব তা জানি না। এই দেহ লেমুরিয়ায় ফিরে যেতে পারার আগে, যদি কোথাও আমাকে কাজে লাগাতে পারেন, আমিও এর জন্য আমার সমস্ত আলো উৎসর্গ করতে প্রস্তুত।\n\nআপনার বিশ্বস্ত ফারোস"
  },
  Mail_124301_Name = {
