  Mail_124302_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nমিসাগে যোগদানের দিন থেকেই, অসংখ্য নিয়মকানুন আমাকে জড়িয়ে ধরেছে। সভাস্থলে ভৃত্যদের নিয়ে হাঁটাচলা নিষেধ, ক্যাম্পাসের চত্বরে ছাত্রদের গালে পা দেওয়া নিষেধ, সভাকক্ষে বহু মানুষের সম্মিলিত অনুষ্ঠান আয়োজন নিষেধ……\nমিসাগের সেই বিরক্তিকর নীতিরক্ষকরা আমাকে শৃঙ্খলিত করেছে, এটা ইসারাউয়ের রানির প্রাপ্য জীবন নয়। আমার প্রাপ্য সবকিছু আমি ভোগ করব — মাদকতাময় সুরা, কোমল পৃষ্ঠদেশ, আর প্রিয় ভৃত্যগণ…… আমার এই স্বেচ্ছাচারী জন্মদিনে, এমন ভাবনা স্বাভাবিকভাবেই জেগে ওঠে।\nরাত গভীর হয়েছে, তুচ্ছ বিষয়ে আমার ধৈর্য ফুরিয়ে গেছে। আমি তোমাকে মধ্যরাতের কোনো অভিযানে পাঠাব না, তোমাকে নিজে অনুমান করতেও বলব না। আমার দরকার তুমি আমার পাশে থাকো।\nএখনই আমার প্রাসাদে এসো, দ্বিধা করো না, তোমার সব অপ্রয়োজনীয় পোশাক ও উপাধি খুলে ফেলো।\nআজ রাতে, এবং এরপর প্রতিটি রাতে, তুমি আমার।\n\nএটাকে তুমি তোমার প্রথম স্থায়ী দায়িত্ব হিসেবে গণ্য করতে পারো।\n\nওয়ান্ডা"
  },
  Mail_124302_Name = {
