  },
  Mail_124303_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nটিঙ্কেট আমাকে বলেছে, সে তার ব্যক্তিগত কনসার্টের আয় দিয়ে জন্মদিনের পর একটি আন্তঃনাক্ষত্রিক ভ্রমণের পরিকল্পনা করেছে এবং আমাকেও সাথে নিয়ে যেতে চায়। কিন্তু... আমি যদি সাথে যাই, সে নিশ্চয়ই আমার দেখাশোনা করতে গিয়ে মনোযোগ হারাবে। আমি চাই না আমার কারণে তার আনন্দে ভাটা পড়ুক।\nসে জীবনের আলোকে এত ভালোবাসে, এই মহাবিশ্বের অগণিত রং আর প্রবাহিত নক্ষত্রপুঞ্জের প্রতি এত মুগ্ধ। আমাকে সাথে নিলে, সে হয়তো সেভাবে স্বচ্ছন্দে গান গাইতে পারবে না, মন ভরে তাকিয়ে থাকতে পারবে না...\nতাই... তুমি কি আমার হয়ে তাকে একটু বোঝাতে পারবে? অনুগ্রহ করে তাকে একাই ভ্রমণে যেতে দাও, বিভিন্ন গ্রহে কনসার্ট করতে দাও, সে যে সব দৃশ্যের স্বপ্ন দেখে সেগুলোকে আলিঙ্গন করতে দাও... অথবা তুমি কি আমার বদলে এই ভ্রমণে যাবে? সর্বোপরি, টিঙ্কেট আর আমি দুজনেই তোমার প্রতি কৃতজ্ঞ, তোমার উপকারের প্রতিদান দিতে চাই... যদি তুমি রাজি হও...\nশুধু, অনুগ্রহ করে তাকে বোলো না যে এটা আমার ইচ্ছা। আমি তার মুক্ত যাত্রাপথে বাধা হয়ে দাঁড়াতে চাই না।\n\nফেইন্ট"
  },
  Mail_124303_Name = {
