  },
  Mail_124304_Desc = {
    Text = "প্রিয় উপকারী:\n\nপলিডিউসিসের সাথে মিসাগে কাটানো এই দিনগুলো, এত শান্ত, এত উজ্জ্বল, যেন এক স্বপ্নের মতো……\nপলিডিউসিস এখনও সেই শিষ্টাচার মেনে চলে, মার্জিত ও ভদ্র কথা বলে, তবু আমি স্পষ্ট অনুভব করতে পারি, সে ধীরে ধীরে আগের সেই সে-তে ফিরে যাচ্ছে। 「পবিত্র পুত্র」-এর সেই শ্বাসরুদ্ধকর দূরত্ব, কোমল দৈনন্দিনতার মাঝে নীরবে গলে যাচ্ছে। এই সমস্ত কোমল পরিবর্তন, সবই আপনার কৃপায়।\nআমি প্রায়ই ভাবি, এই ঋণ কীভাবে শোধ করা যায়? আমি পলিডিউসিসের মতো দক্ষ নই, যে আপনাকে চমকে দেওয়ার মতো উপহার তৈরি করতে পারে। উড়ানের আনন্দও আপনি আমার সাথে বহুবার উপভোগ করেছেন। এই বিশেষ দিনে কীভাবে আপনার সাথে আনন্দ ভাগ করে নেওয়া যায়, তা নিয়ে আমি দীর্ঘক্ষণ নীরবে ভেবেছি।\nহয়তো……আপনি কি আমার পালক পছন্দ করবেন? অনেকেই বলে, এতে এমন এক কোমলতা আছে যা মনকে শান্ত করে। তাই, যদি কোনোদিন আপনি ক্লান্ত বোধ করেন, অথবা শুধু একটু নিরিবিলি কোণ চান, দয়া করে যেকোনো সময় আমার কাছে আসুন। আমার ডানা, সর্বদা আপনার জন্য অবনত থাকবে।\n\nক্যাস্টর"
  },
