  Mail_124304_Sender = {
    Text = "ক্যাস্টর"
  },
  Mail_124305_Desc = {
    Text = "আমার ছোট্ট·বন্দী:\n\nশুনেছি মিসাগে সম্প্রতি একটা রোল-প্লেয়িং গেম খুব জনপ্রিয় হচ্ছে, ডাইনি, ওয়্যারউলফ কী সব... ছিঃ, শুনতে একটুও রোমান্টিক লাগছে না~ আমি কিন্তু আরও মজার একটা খেলার কথা ভেবেছি!\nএরকম, তুমি বন্দী সাজবে, আর আমি পাহারাদার। যখন আমি ছোট্ট চাবুক ঘোরাব, তখন আমি জোরে জোরে আর্তনাদ শুনতে চাই~ মোমবাতির মোম তোমার শরীরের উপর গড়িয়ে পড়বে, জ্বলন্ত যন্ত্রণা আর আনন্দ নিয়ে আসবে... আহ, শুধু কল্পনা করতেই মিষ্টি লাগছে~\nআরে, এতটুকু পড়েই নিশ্চয়ই আবার ভ্রু কুঁচকে ফেলেছ? একদম বাধ্য ছেলে না তুমি, আজ কিন্তু আমার জন্মদিন~ প্রিয় ছোট্ট বন্দী, আমার একটুখানি খামখেয়ালি ইচ্ছা তো পূরণ করা উচিত, তাই না?\nসত্যিই যদি না হয় তাহলে... তাহলে... তুমি পাহারাদার হও, আমি তোমার বন্দিনী হই, কেমন? আমি তোমাকে সন্তুষ্ট করবই~\n\nপান্ডিয়া"
  },
  Mail_124305_Name = {
    Text = "ভূমিকা পালন..."
  },
  Mail_124305_Sender = {
    Text = "প্যান্ডিয়া"
  },
  Mail_124306_Desc = {
    Text = "গোপনীয়তার রক্ষক:\nপরম উপকারী, আজ আমার জন্মদিন। এই বিশেষ দিনে আমি আপনাকে আমার সাম্প্রতিক অবস্থার কথা জানাতে চাই: গোলিয়া এবং শিক্ষিকা লুওতানের নির্দেশনায়, আমি মনে হচ্ছে... ক্রমশ আমার রক্তধারায় লুকিয়ে থাকা শক্তিকে স্পর্শ করতে পারছি। এটি আর ঘুমিয়ে নেই, বরং প্রতিটি অনুশীলনের সাথে সাথে আমার শরীরের ভেতরে গুঞ্জন তুলছে, প্রবাহিত হচ্ছে, ধীরে ধীরে মুক্ত হচ্ছে।\n\n\n\nঠিক কখন আমি চূড়ান্ত রূপান্তর সম্পন্ন করে আরও বিশুদ্ধ গভীর সমুদ্র বংশধর হয়ে উঠতে পারব, তা আমি নিশ্চিত করে বলতে পারি না। হয়তো আগামীকাল, হয়তো পরের সপ্তাহে, হয়তো পরের মাসে... কিন্তু দয়া করে জেনে রাখুন, এই পথ যতই দীর্ঘ হোক, পথে যতই কষ্ট থাকুক, সেদিন আপনি আমাকে যে উৎসাহের কথা বলেছিলেন, আমি সেগুলো সবসময়... মনে গেঁথে রেখেছি। আমি চেষ্টা চালিয়ে যাব।\n\nআরেকটি বিষয়ে আমাকে ক্ষমা চাইতে হবে, আমি এইমাত্র মিসাগ ডাকঘর থেকে জানতে পেরেছি যে, চিঠির সাথে নগদ টাকা পাঠাতে হলে অতিরিক্ত ২ টাকা হ্যান্ডলিং ফি দিতে হয়।\nগত বছরের বকেয়া পূরণ করতে, আমি আমার সঞ্চয় থেকে আরও কিছু অর্থ খরচ করব। এগুলো আমার জন্য সহজে অর্জিত নয়, কিন্তু গভীর সমুদ্রের রক্তধারার প্রতিশ্রুতি অবশ্যই পূরণ করতে হয়।\n\nকেইকেস"
  },
  Mail_124306_Name = {
    Text = "পরিসেবা ফি..."
