  Mail_124307_Desc = {
    Text = "গোপনীয়তা রক্ষাকারী：\n\nভালো করে শোনো, আজ রাতে যাই হোক না কেন, আমার সাথে 'সেই দোকানে' যেতেই হবে।\nছদ্মবেশের জামাকাপড় তোমাকে পাঠিয়ে দিয়েছি, অবশ্যই, কোনোভাবেই, কেউ যেন আমাদের চিনতে না পারে!\n'সেই দোকানে'র সীমিত সংস্করণের মিষ্টি বিক্রি শুরু হয়েছে, কোথা থেকে আসা সেই জঘন্য লোকটা নিশ্চয়ই একদল লোককে ঘুষ দিয়ে রেখেছে, তাদের এই মহিলার গতিবিধি জানতে দেওয়া যাবে না।\nযদিও সেই লোকটা আমাকে কিনতে না দেওয়ার জন্য লন্ডিনিয়ামের সব কেক দোকানের সীমিত সংস্করণ আগেই বুক করে ফেলেছে, কিন্তু সেটা তো……হুমহুম।\nএই মহিলা আগেই 'সেই দোকানে'র প্রধান শেফকে বশ করে রেখেছে, তাকে দিয়ে সবচেয়ে সুস্বাদু সেই পদটা মেনু থেকে সরিয়ে দিয়েছে।\nহুম, আজ এই মহিলা সেই লোকটাকে বুঝিয়ে দেবে যে, কিছু কিছু জিনিস শুধু টাকা দিয়ে হয় না।\nতখন আমরা চুপচাপ পেছনের দরজা দিয়ে ঢুকে যাবো, তিন স্তরের এনক্রিপশনযুক্ত লোহার বাক্সটা খুলবো, তাহলেই সেই সীমিত সংস্করণের মধ্যে সীমিত সংস্করণটা পেয়ে যাবো।\nপারিশ্রমিক হিসেবে, আমি তোমাকে একটুকরো (কেটে দেওয়া), অর্ধেক কেক দেবো!\nআজ রাত এগারোটায়, আমি ঘরে তোমার জন্য অপেক্ষা করবো, তোমাকে অবশ্যই, নিশ্চিতভাবে আসতে হবে! বুঝেছো!\nঅবশ্যই গোপন রাখবে, নাহলে খবর ফাঁস হয়ে সেই লোকটা আমাদের গতিবিধি জেনে গেলে, সব শেষ হয়ে যাবে!\n\nমার্ফি"
  },
  Mail_124307_Name = {
    Text = "কেক ছিনতাইয়ের যুদ্ধ..."
