  Mail_124308_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআপনাকে দুঃখের সাথে জানাচ্ছি যে, লন্ডিনিয়েন থিয়েটার মাস্টার ক্যাসিয়ার জাদু শো সম্পূর্ণরূপে বাতিল করেছে। কারণগুলো হলো: টিকিটের দাম অত্যধিক, সম্প্রতি মানুষ এত বেশি অদ্ভুত ঘটনা দেখেছে যে জাদুর প্রতি আগ্রহ হারিয়ে ফেলেছে, পরপর কয়েকটি শোতে দর্শক নিখোঁজ হয়েছে এবং এখনও ফেরেনি, পুলিশ বারবার থিয়েটারের মালিকের কাছে এসে মাস্টার ক্যাসিয়াকে শো স্থগিত রেখে তদন্তে সহযোগিতা করতে বলেছে ইত্যাদি ইত্যাদি।\nসম্প্রতি ব্ল্যাক পুলের অস্বাভাবিক কার্যকলাপের প্রভাবে আমার পারফরম্যান্সে মাঝে মাঝে ছোটখাটো ভুল হয়েছে, এগুলো তুচ্ছ বিষয়, কিন্তু দ্বিতীয় কারণটি মাস্টার ক্যাসিয়ার কাছে একেবারেই অসহনীয়!\nএই নিয়ে আমি দীর্ঘ সময় চিন্তা করেছি এবং অবশেষে একটি নিখুঁত নতুন পারফরম্যান্সের কথা ভেবেছি! মৃতদেহ নিয়ন্ত্রণ, মৃতের পুনরুত্থান, মাত্রা অতিক্রম, আবেগ সংক্রমণ, বিশাল শুঁড়... সব কিছুই তুচ্ছ! আগে সেই জঘন্য ডাইমেনশন হাউন্ডের প্রভাবে সময় নিয়ন্ত্রণ এই পেশায় সবসময় নিষিদ্ধ ছিল, কিন্তু সেই দুষ্ট কুকুরটিকে সিল করার পর, মাস্টার ক্যাসিয়ার জাদু কর্মজীবন আবার নতুন উচ্চতায় পৌঁছাবে!\nশোয়ের সময় আজ রাতেই নির্ধারিত, সম্পূর্ণ বিনামূল্যে। গোপনীয়তার রক্ষকের জন্য প্রথম সারির ঠিক মাঝখানের আসন সংরক্ষিত রাখা হয়েছে, এবং চমকপ্রদ ইন্টারঅ্যাক্টিভ পর্ব আপনার জন্য অপেক্ষা করছে! নতুন যুগের সর্বশ্রেষ্ঠ জাদু শোয়ের প্রথম ইন্টারঅ্যাক্টিভ দর্শক হওয়ার সম্মান উপভোগ করুন!\nমাস্টার ক্যাসিয়ার গৌরব পুনরুদ্ধারের জন্য!\n\nক্যাসিয়া"
  },
  Mail_124308_Name = {
    Text = "ক্যাসিয়া, আবারও জাদুর জয়ধ্বনি তুলুক!"
  },
  Mail_124308_Sender = {
    Text = "ক্যাসিয়া"
  },
  Mail_124309_Desc = {
    Text = "মালিক:\n\nসিলভিয়া দিদি এইমাত্র এসে আমাকে বলল, এবারের জন্মদিনে তারা আমাকে ফেরিস হুইলে চড়াতে নিয়ে যাবে।\nলিলি ছবির বইতে পড়েছে, ফেরিস হুইল হলো একটা অনেক অনেক বড় চাকা, যেটার উপরে বসলে ধীরে ধীরে ধীরে ধীরে আকাশে উঠে যাওয়া যায়, পাশে পাখিদের উড়ে বেড়ানো দেখা যায়, শুনতেই অনেক সুখের লাগে।\nতবে সিলভিয়া দিদি বলেছে \"আসলে কিছুটা পার্থক্য আছে\"। লিলিও বুঝতে পারেনি ব্যাপারটা কী।\nসে আরও বলেছে, ফেরিস হুইল যেখানে যায় সেটা অনেক উঁচু, তাই আমার সাথে একজন অভিভাবক নিয়ে যাওয়া ভালো হবে।\nলিলি জানে না অভিভাবক মানে কী, কিন্তু লিলি মালিকের সাথে মেঘের মাঝে ভ্রমণ করতে চায়।\nদুপুরের খাবারের পর, আমি আর সিলভিয়া দিদি ছাত্রাবাসের বাইরে তোমার জন্য অপেক্ষা করব।\n\nলিলি"
  },
