  Mail_124310_Desc = {
    Text = "গোপনীয়তার রক্ষক (এবার আমি অবশেষে সঠিক লিখেছি! দারুণ না!)：\n\nআবারও এই মিষ্টি মিষ্টি কথা লেখার সময় এসেছে, আমি ইতিমধ্যে অভ্যস্ত হয়ে গেছি। তুলনা হলো এই মুহূর্ত এই সময়ে এখন, আমি আর ব্রাউন আজ তোমাকে কী খাওয়াব তা নিয়ে মাথা ঘামাচ্ছি!\nপূর্ব এলাকার গলির রাস্তার খাবার অবশ্যই সুস্বাদু, কিন্তু আজ আমি তোমাকে আর ব্রাউনকে ভালো কিছু খাওয়াতে চাই——মানে তোমাদের পশ্চিম এলাকার লোকেরা যা খেতে পছন্দ করে সেসব।\nযেমন সেইসব সস আর মশলায় ভরা বিশেষ রান্না, পরিমাণ কম, থালা বড়, আর দামও অবিশ্বাস্য রকম বেশি, একেবারে ডাকাতির মতো। এটা ভাবতেই মনে হচ্ছে আমার মানিব্যাগে হাওয়া ঢুকছে, সেটা নিশ্চয়ই টাকা চলে যাওয়ার সময় রেখে যাওয়া ক্ষত।\nকিন্তু তুমি দিদি আর ব্রাউনের পরে আমার সবচেয়ে গুরুত্বপূর্ণ, সবচেয়ে প্রিয় মানুষ, পূর্ব এলাকার লোকেরা কিন্তু নিজের মানুষের সাথে কৃপণতা করে না, তাই আজকের সব খরচ আমি আর ব্রাউন বহন করব।\nআমাদের অবমূল্যায়ন করো না, আমরা দুধ বিলি, খবরের কাগজ বিলি, বার্তা পৌঁছানো, কাজ চালানো আর অন্যান্য কাজ করে বেশ ভালো টাকা কামিয়েছি, তুমি নিশ্চিন্তে থাকো!\n\nতোমার ভালো বন্ধু জেনকিন আর ব্রাউন"
  },
  Mail_124310_Name = {
    Text = "আজকের বিল আমাদের!"
  },
  Mail_124310_Sender = {
    Text = "জেনকিন"
  },
  Mail_124311_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nতুমি নিশ্চয়ই সিলভিয়ার মিসাগার্ড আন্ডারগ্রাউন্ড ক্যাসিনো সম্পূর্ণ ধ্বংস করার মহান কীর্তির কথা শুনেছ? কিন্তু আজ আমার জন্মদিন, আর অ্যাড্রেনালিন ছুটে যাওয়ার মতো কোনো দারুণ কার্যকলাপ না থাকলে বছরে একবারের এই বিশেষ দিনটা কি নষ্ট হয়ে যাবে না?\nবারবার ভেবেচিন্তে, আমি তোমাকে আমার বিশ্বস্ত ওয়াটসন হিসেবে বিশেষভাবে আমন্ত্রণ জানানোর সিদ্ধান্ত নিয়েছি, যাতে আমরা একসাথে সেই রাতের চোরদের ধরতে পারি যারা সম্প্রতি সিতে থেকে এখানে পালিয়ে এসে গ্র্যান্ড মিউজিয়ামের ধনসম্পদ চুরি করেছে।\nক্যাম্পাসের বাইরে সেই 「অ্যাপোলো বার」-এ একটু পান করার সময়, আমি ঘটনাক্রমে তাদের উৎসাহের সাথে দামি গহনা লুট করার কৃতিত্ব নিয়ে বড়াই করতে শুনেছিলাম। বারটেন্ডার গুরুত্ব দেয়নি, কিন্তু আমি ঠিকই বুঝতে পেরেছি — পান্না, নীলকান্তমণি, হীরার মুকুট — চুরি হওয়া জিনিসগুলোর সাথে হুবহু মিলে যায়। সতর্ক না করে দেওয়ার জন্য, আমি তাদের গায়ে ভালো করে চিহ্ন দিয়ে রেখেছি, তারা তাদের আস্তানায় ফিরলে একসাথে চোর ও মালামাল দুটোই হাতেনাতে ধরার পরিকল্পনা করেছি।\nআজ রাত সাতটায়, স্কুলের গেটে মিসাগার্ড এক্সপ্রেস স্টপে, আমরা দেখা করব।\n\nলেক"
  },
  Mail_124311_Name = {
    Text = "শিকার পরিকল্পনা..."
  },
  Mail_124311_Sender = {
    Text = "রাইকার"
  },
  Mail_124312_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nমিসাগের সময় যেন অন্য যেকোনো জায়গার চেয়ে অনেক হালকাভাবে প্রবাহিত হয়। কয়েকবার করতালি, কয়েকবার মঞ্চ থেকে বিদায়, আর এভাবেই আরও একটি বছর পেরিয়ে গেল।\nএই এক বছরে আমার কিছু নতুন অভ্যাস তৈরি হয়েছে। আগে যখন আমি মঞ্চে উঠতাম, যতই ভিড়ে ঠাসা থাকুক না কেন, আমার চোখে প্রেক্ষাগৃহ সবসময় শূন্য মনে হতো। আমি ফাঁকা মঞ্চে দাঁড়িয়ে, ফাঁকা প্রেক্ষাগৃহের সামনে নৃত্য করতাম, আর সমগ্র বিশ্বে শুধু এক জোড়া নৃত্য-জুতোর শব্দই প্রতিধ্বনিত হতো। কিন্তু এখন, যখনই পর্দা ওঠে, আমি তোমাকে দেখতে পাই। হাজারো আসন শূন্য পড়ে থাকে, শুধু তুমি একা আমার দিকে তাকিয়ে থাকো। তোমার দৃষ্টিতে আমার নৃত্য আবার নতুন করে অর্থ খুঁজে পেয়েছে।\nএক বছর পেরিয়ে গেছে, তোমার নৃত্যভঙ্গি এখনও ততটাই জড়সড়, কিন্তু দর্শক আসনে বসে তোমার সেই উচ্ছল দৃষ্টি মঞ্চের ওপরের সেই সাধারণ নৃত্যপদক্ষেপকে সহজেই ছাপিয়ে যায়। সেই দৃষ্টি যেন এক ঝর্নাধারা, যা আমার ক্রমশ সাধারণ হয়ে যাওয়া নৃত্যপদক্ষেপগুলোকে একে একে ধুয়ে শুদ্ধ করে দেয়। নৃত্যশিল্পী ও দর্শকের এই যুগলনৃত্যে, আমি ধীরে ধীরে সেই মন্দিরের কাছে পৌঁছাচ্ছি যা আমি সবসময় খুঁজে চলেছি। অবশেষে আমি উপলব্ধি করেছি যে, নৃত্যের জন্য দর্শক আর নৃত্যশিল্পী সমান গুরুত্বপূর্ণ।\nকয়েক মাস ধরে আমি একটি নৃত্যের জন্য প্রস্তুতি নিচ্ছি। এটি তোমার দৃষ্টির স্নানে লালিত হয়েছে, তোমার ছায়ায় জন্ম নিয়েছে। এখন, এটি প্রস্তুত।\nআমার মনে হয়, এটি আশা করবে যে আজ রাতে তুমিই হবে প্রথম ব্যক্তি যে এর সাক্ষী হবে।\n\nলিজ"
  },
  Mail_124312_Name = {
    Text = "নর্তকী ও দর্শক..."
  },
  Mail_124312_Sender = {Text = "লিজ"},
  Mail_124313_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nএই স্থানের আতিথেয়তার কল্যাণে, এই বছরে আমি রাজার সাথে বহু সময় কাটিয়েছি। যদিও দেবরাজ্যের আগমন এখনও সুদূর, তবু লিমুরিয়ার সময় যেন মিসাগে প্রলম্বিত হচ্ছে।\nতুমি এবং রাজা উভয়েই আমাকে বলেছিলে যে বিশ্বাস আমার জীবনের সবকিছু হওয়া উচিত নয়। আমি একসময় একগুঁয়েভাবে নিজের মতে অটল ছিলাম, কিন্তু সম্প্রতি যা ঘটেছে তা আমার মানসিকতায় কিছুটা পরিবর্তন এনেছে বলে মনে হয়। অতিরিক্ত ঘন ঘন প্রার্থনা হয়তো আমার প্রভুকে বিরক্ত করতে পারে। নিষ্ঠাপূর্ণ সেবার পাশাপাশি, আমার প্রভু হয়তো চান যে তাঁর ভক্তদেরও নিজেদের একটি সাধারণ জীবন থাকুক।\nএই উপলব্ধির পর, আমি কিছু ছোটখাটো পরিবর্তন আনার চেষ্টা করেছি। আমি লন্ডিনিয়ামের সমস্ত বিখ্যাত মিষ্টান্ন শিল্পীদের কাছে গিয়েছি এবং তাদের কাছে বেকিংয়ের পদ্ধতি শিখেছি। তাদের কিছু গোপন রেসিপি ছিল, যা আমি আমার প্রভুর আশীর্বাদের মাধ্যমে তাদের মুখ থেকে বের করেছি। গতকাল, আমি প্রথমবারের মতো কিছু চেষ্টা করেছি, কয়েকজন ভক্ত আমাকে বলেছে যে স্বাদ বেশ ভালো, কিন্তু তাদের স্বাদবোধ তাদের আনুগত্যের মতোই সন্দেহজনক।\nআমি তোমাকে আজ আমার উঠানে এসে স্বাদ নেওয়ার জন্য আমন্ত্রণ জানাতে চাই। আমি তোমার রুচিবোধে বিশ্বাস করি, এবং তোমার অকপটতায়ও। যদি সুস্বাদু না হয়, আশা করি তুমি সরাসরি বলবে, আমি আন্তরিকভাবে উন্নতি করার চেষ্টা করব।\nকৃতজ্ঞতাসহ।\n\nমিরিয়াম"
  },
  Mail_124313_Name = {
    Text = "আরেকটি বিশেষত্ব..."
  },
  Mail_124313_Sender = {
    Text = "মিরিয়াম"
  },
  Mail_124314_Desc = {
    Text = "মাননীয় গোপনরক্ষক:\n\nজীবন ও মৃত্যুর অর্থ নিয়ে আলোচনা শুনতে শুনতে নিশ্চয়ই আপনি ক্লান্ত হয়ে পড়েছেন? সমাধি-অস্থি নগরীর সেই অমর আত্মাদের উজ্জ্বল স্মৃতির মধ্যে আমি যে সবচেয়ে গুরুত্বপূর্ণ বিষয়টি শিখেছি তা হলো — আহারের অর্থ অনুসন্ধানের চেয়ে বেশি গুরুত্বপূর্ণ হলো সামনের টেবিলে রাখা খাবারটি নিজেই।\nমানবজাতির আদিম যুগে, আমাদের পূর্বপুরুষেরা আহারের সমস্ত সারমর্ম ইতিমধ্যেই আবিষ্কার করে ফেলেছিলেন — আবেগ, আকাঙ্ক্ষা, উপভোগ। বেঁচে থাকার জন্য আহার নয়, আহারের জন্যই বেঁচে থাকা। দুঃখের বিষয়, সেই আদিম ও নিষ্কলুষ আকাঙ্ক্ষাগুলো দীর্ঘ সময়ের স্রোতে ধীরে ধীরে বিস্মৃত হয়ে গেছে, আর এই জনগোষ্ঠী ক্রমশ জটিল থেকে জটিলতর হয়ে উঠেছে।\nতাই, আজকের নৈশভোজের বিষয়বস্তু আমি রেখেছি 「বিশুদ্ধতা」। এই আনুষ্ঠানিক দিনে, সমস্ত জটিলতা আমাদের থেকে দূরে সরে যাবে। এই টেবিলের উপর থাকবে কেবল বিশুদ্ধ, আদিম আবেগ ও আকাঙ্ক্ষা, কেবল রসজ্ঞ ও খাদ্য, কেবল আপনি আর আমি।\nআমার আন্তরিকতম আমন্ত্রণ গ্রহণ করুন। আপনি আমাকে প্রত্যাখ্যান করবেন না, তাই তো?\n\nদুলেসাইন"
  },
