  },
  Mail_124315_Desc = {
    Text = "আমার প্রিয়তম গোপনরক্ষক মহোদয়:\n\nআমার হৃদয় যেন বেড়ে উঠছে……আমি জানি জাগ্রত সত্তার কাছে এটা অদ্ভুত শোনাবে, কিন্তু এটা আগের থেকে আলাদা হয়ে গেছে, আমি কীভাবে আপনাকে বর্ণনা করব?\nসেই সব ভালো মানুষেরা যতই কোমলভাবে, সহানুভূতির সাথে আমার সাথে আচরণ করুক, আমাকে উষ্ণ করার চেষ্টা করুক, দাদা চলে যাওয়ার পর আমার বুকে সবসময় একটা শূন্যতা ছিল। আমি যত বেশি রোদে হাঁটতাম, সেই উষ্ণতা তত বেশি আমাকে আঁচড়াত। বরং অন্ধকার আর স্যাঁতসেঁতে জায়গা আমাকে বেশি স্বস্তি দিত, যেন ঠান্ডা জায়গায় থাকলে দাদার কঠোর ও যন্ত্রণাদায়ক ভালোবাসা কখনো দূরে যায়নি।\nকিন্তু এখন, আপনার সাথে ক্রমশ ঘনিষ্ঠ হওয়ার এই বছরগুলোর পর, প্রতিবার আপনাকে দেখলে, প্রতিবার আপনার দেওয়া যন্ত্রণা আমার চামড়া-মাংসে পড়লে, হাড় পর্যন্ত পৌঁছালে——আহ্, আমার বুকের ভেতরের সুখ দিনে দিনে বাড়ছে। যতক্ষণ আপনি নির্দয়ভাবে আমাকে শাস্তি দেন, অপমান করেন, পদদলিত করেন, আমি জানি, এই পৃথিবীতে সবসময় এমন একটা জায়গা আছে যেখানে আমি সত্যিই থাকতে পারি।\nএই সুখ কি পরের বছরও টিকে থাকবে, তার পরের বছরও? যদি জন্মদিনে করা ইচ্ছা সত্যি হয়, আমার একমাত্র ইচ্ছা হলো আপনার অবজ্ঞাপূর্ণ দৃষ্টিতে সবসময় পর্যবেক্ষিত হওয়া, আর যন্ত্রণা……আরও বেশি বেশি যন্ত্রণা। আপনি হাত তোলার সময়, আমি প্রথমে যা অনুভব করব তা হলো সেই পরিচিত, নিষ্ঠুর, সুখের সুগন্ধ।\n\nআপনার শাস্তি পেতে অত্যন্ত আকাঙ্ক্ষিত রেয়া"
  },
  Mail_124315_Name = {
    Text = "আমার হৃদয়..."
  },
  Mail_124315_Sender = {Text = "লি"},
  Mail_124316_Desc = {
    Text = "গোপনীয়তার রক্ষক\n\nযদিও আমি আপনার সাম্প্রতিক অনুশীলনের অগ্রগতি সম্পর্কে জানতে আগ্রহী, তবে নিশ্চিন্ত থাকুন, আজ আমি আপনাকে সংগীত অনুশীলনের তাগিদ দিতে আসিনি।\nআজ ভোরে, আমি যথারীতি সংগীত কক্ষে গিয়েছিলাম, কিন্তু আমি পঁয়ত্রিশ মিনিট দেরি করেছিলাম। ভোর সাতটায় সংগীত অনুশীলন — এই অভ্যাস আমি কয়েক দশক ধরে বজায় রেখেছি, আর আজ তা সহজেই ভেঙে গেল। কারণটি হলো, স্কুলের করিডোর দিয়ে যাওয়ার সময় আমি একটি রবিন পাখির কূজন শুনতে পেয়েছিলাম।\nবহু বছরের অভ্যাস ভেঙে যাওয়া মেনে নেওয়া সহজ নয়, আমার জন্য তো আরও কঠিন। অদ্ভুত বিষয় হলো, আমি কল্পনা করেছিলাম যেমন হতাশা ও ক্রোধ অনুভব করব, তেমনটি হয়নি। শুরুতে কিছুটা উদ্বিগ্ন হয়েছিলাম। কিন্তু তারপর, আমাকে স্বীকার করতেই হবে, আমার মনে যে সুর ঘুরপাক খাচ্ছিল তা ছিল আনন্দের।\nলন্ডিনিয়াম সবসময় রবিন পাখির কূজনে জেগে ওঠে, এই শব্দ আমি প্রতিদিন শুনি, অদ্ভুতভাবে, এত বছরে এই প্রথম আমি তাদের লক্ষ্য করলাম। আমি করিডোরে দাঁড়িয়ে নীরবে তাদের গান শুনছিলাম, সেই পঁয়ত্রিশ মিনিটে আমার মনে হয়েছিল এই মহাবিশ্বের সর্বোচ্চ সুরটি তাদের ক্ষুদ্র কণ্ঠনালীতেই লুকিয়ে আছে।\nহয়তো এখানকার জীবন মানুষকে শিথিল করে তোলে, হয়তো এখানকার পরিবেশ মানুষকে কোমল করে দেয়। যাই হোক, আমি মনে করি এটি নিশ্চয়ই আপনার সাথে সম্পর্কিত।\nআমি দশ মিনিটেই এই পরিবর্তনকে সানন্দে গ্রহণ করেছি। জীবন সংগীতের মতোই — এর চিরন্তন ছন্দ ও পরিবর্তন আছে, জন্মের দিন থেকেই হয়তো এই পরিবর্তনগুলো ঘটার নিয়তি নির্ধারিত ছিল। আমি আপনাকেও ধন্যবাদ জানাতে চাই, যে আমাকে এমন সুযোগ দিয়েছেন মন স্থির করে সেসব শোনার যা আমি এতদিন উপেক্ষা করেছিলাম। আনন্দ, হ্যাঁ। আমি মনে করি, এটি হবে আমার একটি নতুন অধ্যায়ে প্রবেশের সূচনা।\nএই কারণে, আমি আপনাকে আজ গোধূলিতে আমার সাথে স্কুলের বাইরের গভীর বনে যেতে আমন্ত্রণ জানাতে চাই। গোধূলিতে প্রকৃতির শব্দ ভোরের থেকে আলাদা, কিন্তু আমি মনে করি, উভয়ই আমাদের সংগীত জীবনে নতুন প্রেরণা হয়ে উঠবে।\n\nহ্যামলিন"
  },
