  Mail_124317_Desc = {
    Text = "মহানুভব:\n\nআমি এইমাত্র ফেইন্ট দিদির আপনাকে লেখা জন্মদিনের মেইলটা দেখলাম……যেমনটা ভেবেছিলাম, দিদি সবসময় অন্যদের কথা ভাবেন। কিন্তু বোনদের মধ্যে কোনো ঋণ থাকে না, আমিও কখনো তাঁকে আমার বোঝা মনে করিনি। তাঁর সুরক্ষা না থাকলে আজ আমার এই সফরসঙ্গীত কনসার্টের সুযোগই হতো না।\nসম্মানিত মহানুভব, আপনি সবসময় আমার সবচেয়ে গুরুত্বপূর্ণ শ্রোতা। তাই এবার আমিও চুপচাপ আপনার জন্য একটি জাহাজের টিকিট প্রস্তুত করেছি——আন্তরিকভাবে আপনাকে আমাদের সাথে এই নক্ষত্রযাত্রায় যোগ দেওয়ার আমন্ত্রণ জানাচ্ছি। আপনি সঙ্গে থাকলে দিদির মনের ভারও অনেকটা কমে যাবে বলে বিশ্বাস করি।\nএছাড়া নিশ্চিন্ত থাকুন, যাত্রাপথে আমরা কখনোই আপনার ব্যক্তিগত সময়ে বিরক্ত করব না। আমি এবং দিদি দুজনেই চাই, আপনি এই যাত্রাটি পুরোপুরি উপভোগ করুন, স্বাধীনভাবে প্রতিটি নীহারিকা, প্রতিটি অজানা সাক্ষাৎ অনুভব করুন।\n\nটিংকেট"
  },
  Mail_124317_Name = {
    Text = "ভ্রমণ নিমন্ত্রণ..."
  },
  Mail_124317_Sender = {
