  Mail_124318_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nজন্মদিন আবার এগিয়ে আসছে, কিন্তু মনের ভাবনা বারবার সিতে দ্বীপে ফিরে যায়। বিশেষ করে সেই শিল্প প্রদর্শনীর ভাস্কর্যগুলোর কথা মনে পড়ে। তাদের নীরব ভঙ্গিমা অসংখ্যবার আমার অনুপ্রেরণার দরজায় করাঘাত করেছে।\nকর্মশালায় সারাদিন ভাস্কর্যের সঙ্গী হয়ে থাকি, শিল্পের আদান-প্রদানের অভাবে দীর্ঘদিন ধরে একঘেয়ে লাগছে। গত বছর এই সময়ে, নিজের জন্মদিন উদযাপন করতে, আমি অসংখ্য ভাস্কর্য কেক তৈরি করেছিলাম। প্রথমদিকের উৎসাহ এখন শান্ত হয়ে এসেছে।\nএখন চলাফেরায় অসুবিধা, সিতে দ্বীপে ফিরে যাওয়া এক বিলাসিতা হয়ে দাঁড়িয়েছে। যদি তোমার সেখানে তদন্তে যাওয়ার পরিকল্পনা থাকে, তাহলে কি শিল্প প্রদর্শনীর নতুন কাজগুলোর দিকে একটু নজর রাখবে? আমি তোমার চোখ দিয়ে আবার সেই বৈচিত্র্যময় ও উদার শিল্পের সৌন্দর্য স্পর্শ করতে চাই।\nপ্রতিদান হিসেবে, আমি তোমার জন্য আরেকটি ভাস্কর্য তৈরি করব, নাম দেব 'সিতে দ্বীপে গোপনীয়তার রক্ষক', কেমন?\n\nশান"
  },
