  },
  Mail_124770_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nপ্রতি বছর এই দিনে আমার গবেষণাগারে প্রবেশের অনুমতি বাতিল করা হয়, যার ফলে দিনটি এক অপ্রীতিকর উপায়ে বিশেষ হয়ে ওঠে। অদক্ষ তুচ্ছ কাজে সময় নষ্ট না করার জন্য আমি আর্কাইভে গিয়েছিলাম।\nসেখানে আমি দুটি জিনিস খুঁজে পেয়েছি। তার মধ্যে একটি ছিল একটি অনুশীলন খাতা, যা মূল্যহীন শূন্যতায় ভরা।\nঅন্যটিও একটি অনুশীলন খাতা, যা আমাকে উপলব্ধি করিয়েছে যে আমি জ্ঞানের মহাসাগরের বিশালতাকে অবমূল্যায়ন করেছিলাম, কারণ এতে লেখা যুক্তি ও সিদ্ধান্তগুলো আমাকে জানিয়েছে যে পৃথিবীতে এমন কিছুও আছে যার অস্তিত্ব না-থাকার চেয়েও কম মূল্যবান।\nআর এই দুটি অনুশীলন খাতায় একই নাম লেখা ছিল — আমাদের মহান মিসাগ গোপনীয়তার রক্ষক %player%।\nএরিকা আমাকে জানিয়েছে যে তুমি জানতে চাও আমাকে জন্মদিনে কী উপহার দেবে।\nতুমি আমাকে একটি উত্তর উপহার দিতে পারো।\nআমিও জানতে আগ্রহী, কোন উত্তরের সত্যটি আমাকে বেশি চমকে দেবে। এটা কি নিছক অলসতা ও উদাসীনতার চরম প্রকাশ, নাকি তুমি সারা শিক্ষাবর্ষ আন্তরিকভাবে পড়াশোনা করেছ এবং শেষ পর্যন্ত নিরর্থক হতাশায় এই একাডেমিক আবর্জনা রেখে গেছ।\nযদি প্রথমটি হয়, তাহলে যথেষ্ট যুক্তিসঙ্গত কারণ থাকলে এবং তুমি প্রমাণ করতে পারলে যে ক্লাসে শেখানো সমস্ত জ্ঞান তুমি সম্পূর্ণরূপে আয়ত্ত করেছ, আমি তোমার পক্ষে একাডেমিতে হোমওয়ার্ক অব্যাহতির আবেদন জমা দিতে পারি। অবশ্যই, এর মানে এই নয় যে আমি এই ধরনের শিথিলতাকে সমর্থন করি যা তোমাকে সম্পূর্ণ অলস করে দিতে পারে, তবে যতক্ষণ তুমি আমার পরীক্ষায় উত্তীর্ণ হতে থাকবে, আমি সেই ধরনের গোঁড়া মানুষ নই — আমার ছাত্রদের কিছু বিশেষ সুবিধা দিতে আমার আপত্তি নেই।\nযদি দ্বিতীয়টি হয়, তোমার প্রথম অভিভাবক হিসেবে, আমাকে বিশ্বাস করো, তুমি যতই দুর্গম উপাদান হও না কেন, আমার আয়ত্তে থাকা কৌশলগুলোর মধ্যে আমরা অবশ্যই একটি খুঁজে পাব, যা দিয়ে তোমার অত্যন্ত দরিদ্র বুদ্ধিবৃত্তিকে উন্নত করা যাবে এবং তোমাকে অজ্ঞতায় ভরা কষ্টকর প্রচেষ্টার যন্ত্রণা থেকে মুক্ত করা যাবে।\nআজ বিকেল চারটায় আমি আর্কাইভে থাকব, ব্যক্তিগতভাবে তোমার ক্লাসের জ্ঞান আয়ত্তের পরীক্ষা নেব। দেরি কোরো না।\n\nডোর"
  },
  Mail_124770_Name = {
    Text = "বিশেষাধিকার..."
  },
  Mail_124770_Sender = {Text = "ডল"},
  Mail_124771_Desc = {
    Text = "মিসাগের ছোট্ট কুকুর:\n\nএই বছরও তুমি সেই চক্রাকার দৈনন্দিনতায় আটকে আছ — বিপদ ঘটাচ্ছ, পৃথিবী বাঁচাচ্ছ, বন্ধু তৈরি করছ, নতুন জ্ঞান শিখছ, এবং পৃথিবীর জন্য সবকিছু স্বাভাবিক — এই মিথ্যা ভ্রম তৈরি করে যাচ্ছ।\nদেখা যাচ্ছে, তোমার মস্তিষ্ক শরীর থেকে বের করে নিলেও, চেতনাকে এক মাত্রা থেকে অন্য মাত্রায় টেনে নিলেও, তোমার এই হাস্যকর রকমের উদ্ভট ছোটাছুটি আর ব্যস্ততায় কোনো প্রভাব পড়ে না।\nসত্যিই কত ব্যস্ত আর কোলাহলপূর্ণ, প্রিয় ছোট্ট কুকুর।\nতুমি সেই সত্যগুলো বিশ্বাস করো না, তুমি জোর করে তাদের যন্ত্রণা দীর্ঘায়িত করতে চাও, ধ্বংসের প্রক্রিয়াকে আরও ঢিমেতালে টেনে নিয়ে যেতে চাও — তোমার উদ্দেশ্য কী, তুমি কি আসলে বোকা সাজছ, নাকি মানুষ সত্যিই এতটা বোকা হতে পারে? এমনকি আমি তোমার এই শরীরের মস্তিষ্কের কর্টেক্স চিরে দেখেছি, তবুও এসব আমার কাছে অমীমাংসিত রহস্যই রয়ে গেছে।\nঅভিনন্দন, তুমি সত্যিই আমার মনে এক ফোঁটা দোলাচল তৈরি করেছ — আমি সন্দেহ করতে শুরু করেছি, যদি তোমাকে পর্যবেক্ষণ করা আমাকে এত বিপুল আনন্দ দেয়, তাহলে কি সবকিছুকে এখনও অর্থহীন বলা যায়?\nতুমি যেসব অর্থহীন কাজে পারদর্শী, সেরকমই অর্থহীনভাবে প্রার্থনা করো — প্রার্থনার লক্ষ্য কে, তাতে কিছু যায় আসে না।\nপ্রার্থনা করো যেন তুমি চিরকাল আমাকে শৃঙ্খলিত রাখতে পারো, ছোট্ট কুকুর — তাহলে আমি আর তুমি, দুজনেই এই অর্থহীন পৃথিবীতে কিছুটা আনন্দ খুঁজে পাব।\n\n「দোর」"
  },
  Mail_124771_Name = {
    Text = "প্রার্থনা"
  },
  Mail_124771_Sender = {
    Text = "মেল্টডাউন·ডল"
  },
  Mail_124772_Desc = {
    Text = "পার্টনার:\n\nপ্রতি বছর জন্মদিনে তোমাকে চিঠি লেখা, কখন যে একটা রীতি হয়ে গেছে বুঝতেই পারিনি।\nআমার মনে আছে, প্রথমবার তোমাকে জন্মদিনে চিঠি লেখার সেই দিনটা — সেটাই ছিল প্রথমবার যখন বাবা আমাকে নিজের জন্মদিনের পরিকল্পনা নিজে করতে দিয়েছিলেন। আমি তোমাকে আমার সাথে বাইরে যেতে আমন্ত্রণ জানিয়েছিলাম। তারপর থেকে, আমরা একসাথে অনেক অনেক 'প্রথমবার' পার করেছি।\nসেই সময়ের পর থেকে অনেক কিছুই বদলে গেছে, কিন্তু ভালো করে ভাবলে মনে হয়, আসলে তেমন কিছুই বদলায়নি। আমরা এখনও সেই পথেই এগিয়ে চলেছি যেটাকে আমরা নিজেদের পথ বলে বেছে নিয়েছি, আমাদের পাশে এখনও একে অপর আছি, আর তুমি এখনও আমার কাছে সবচেয়ে গুরুত্বপূর্ণ সেই পার্টনার।\nতাই, যদিও বাবা এইমাত্র একটা কেক পাঠিয়েছেন এবং জানতে চেয়েছেন আজ রাতে তিনি আমার জন্য যে ভোজসভার আয়োজন করেছেন সেখানে আমি যোগ দিতে চাই কি না, আজ রাতের জন্য আমার অন্য কিছু পরিকল্পনা আছে।\nলন্ডিনিয়ামে একটা নতুন সিনেমা মুক্তি পেয়েছে, অস্বাভাবিক রকম জনপ্রিয়। তবে একাডেমি এবং অ্যাসোসিয়েশন যৌথভাবে নিশ্চিত করেছে যে এতে কোনো আধ্যাত্মিক প্রতিক্রিয়া নেই।\nতার মানে এটা সত্যিই একটা অসাধারণ 'সাধারণ' সৃষ্টি।\nআমার কাছে ঠিক দুটো টিকিট আছে। তুমি ধরে নিতে পারো যে আমি ব্যতিক্রমী কিছু করিনি বা ম্যাডাম সোরেইলকে বিরক্ত করিনি, কারণ এর টিকিট পাওয়া সত্যিই অত্যন্ত কঠিন ছিল।\nতাহলে, পার্টনার, তুমি কি এই সময়টুকু আমাকে দেবে? হয়তো, আমরা সেইসব অস্বাভাবিক পরিস্থিতি থেকে যেগুলো প্রতিদিন সামলাই, কিছুক্ষণের জন্য বেরিয়ে এসে, একে অপরের সঙ্গে একটা 'সাধারণ' সন্ধ্যা কাটাতে পারি।\nএরপর প্রতিটা আগামীকাল, যখন আমরা জেগে উঠব, পৃথিবীতে যাই ঘটুক না কেন, আমি তোমার সাথে মিলে তার মোকাবেলা করব।\n\nরামোনা"
  },
  Mail_124772_Sender = {
    Text = "রামোনা"
  },
  Mail_124773_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমার এবং সেই 'আমার' মধ্যকার বিশেষ সংযোগ, এবং আমার ও তোমার মধ্যকার বন্ধনের কল্যাণে, সবসময় তোমার পাশে না থাকলেও, গত এক বছরে তোমার গতিবিধি সম্পর্কে আমি কিছুটা অবগত।\nতুমি অন্য একটি জগতে সক্রিয় ছিলে, এবং মনে হচ্ছে সেখানেও তুমি 'আশা' নামক পরিবর্তন নিয়ে এসেছ। দিনের পর দিন কালো জলাশয়ের মধ্য থেকে উপরে তাকিয়ে থাকলেও, আলোর মতো এই শক্তি আমাকেও উষ্ণতা দিয়েছে।\nআমি আগের কাজগুলো আবার শুরু করেছি, তবে আগের মতো নয়—এখন আমি আর নিরর্থক সংগ্রামের মানসিকতা নিয়ে সেই অবধারিত বিলুপ্তির মুখোমুখি হচ্ছি না। তুমি আমাকে নতুন কিছু শিখিয়েছ—নির্ধারিত সমাপ্তির আগে, প্রতিটি সত্তা টিকে থাকার জন্য সর্বশক্তি দিয়ে লড়াই করার এই প্রক্রিয়াটিই হলো সভ্যতা, আত্মা ও ইচ্ছাশক্তির অর্থবহ হওয়ার কারণ।\nআমার জগতের জন্য এই সময়টুকু যতই ক্ষণস্থায়ী হোক না কেন, আমি চেষ্টা চালিয়ে যাব। শুধুমাত্র সেই পরিচিত মুখগুলোকে আরেকবার দেখতে পাওয়া এবং তাদের সাথে কয়েকটি কথা বলার জন্য হলেও, এই চেষ্টা অর্থহীন নয়।\nতুমি যতদিন না থামবে, আমি এই পথে হাঁটতে থাকব। অনুগ্রহ করে আমাকে স্বেচ্ছাচারী হতে দাও—একে তোমার পাশাপাশি চলার একটি উপায় হিসেবে দেখতে দাও। তাহলে হয়তো তুমি তোমার নিরন্তর যাত্রাপথে মাঝে মাঝে মনে করবে যে, সবসময় এমন একজন 'আমি' আছে, যে তোমার মতোই সর্বশক্তি দিয়ে একই কাজ করে যাচ্ছে।\n\n「রামোনা」"
  },
  Mail_124773_Sender = {
    Text = "「রামোনা」"
  },
  Mail_124774_Desc = {
    Text = "লক্ষ্যবস্তুকে হত্যা করা সহজ, কিন্তু পরবর্তী পরিচ্ছন্নতার কাজটাই ঝামেলার।\nএ বছর গত বছরের রীতি অনুসরণ করে তোমার হয়ে আরেকজনকে হত্যা করার পরিকল্পনা ছিল।\nতবে আমি লক্ষ্য করেছি যে আমার দেওয়া আগের উপহারটি তুমি এখনও ব্যবহার করোনি। গভীরভাবে ভেবে দেখার পর, কারণটা এটাই কিনা জানি না, তবে আমি আমার নিজের ত্রুটি খুঁজে পেয়েছি।\nতুমি নিশ্চিন্ত থাকতে পারো, যদিও আগের নিয়োগকর্তাদের জন্য আমি শুধুমাত্র শত্রু হত্যার সেবাই দিতাম, কিন্তু নানা ধরনের ঝামেলা এড়াতে প্রমাণ ধ্বংসের ব্যাপারেও আমার যথেষ্ট অভিজ্ঞতা আছে। তুমি যাকে হত্যা করতে চাও সে যদি সেইসব জটিল নিয়ম ও শৃঙ্খলার সুরক্ষায়ও থাকে, তোমার কোনো মানসিক চাপ নেওয়ার দরকার নেই, আমি সবকিছু সামলে নেব।\nআমি প্রতিশ্রুতি দিচ্ছি, কেউই তোমার কাছে কিছু খুঁজে পাবে না।\nব্যক্তি ঠিক করার পর, আমাকে নামটা জানিয়ে দিও, আমি যেখানেই থাকি না কেন, সঙ্গে সঙ্গে গিয়ে তোমার হয়ে তাঁকে সমাধান করব।\nতোমার উৎসব শুভ হোক, আর আশা করি আমার জন্মের এই দিনে তুমিও আনন্দ অনুভব করবে, গোপনরক্ষক।\n\n\nশিলো"
  },
  Mail_124774_Name = {
    Text = "যারা প্রায়ই মানুষ মারে তারা জানে\n……"
  },
  Mail_124774_Sender = {
    Text = "হেলট"
  },
  Mail_124775_Desc = {
    Text = "ঠিক আছে, স্পষ্টতই তোমরা এই আচরণ বন্ধ করার কোনো ইচ্ছা রাখো না, এবং আমি যতদূর জানি, আমিও এই 「উপহার দেওয়ার」 রীতিতে অভ্যস্ত হয়ে গেছি।\nকিন্তু একদিন তুমি এই সদয়তার জন্য অনুতাপ করবে, আমাকে বিশ্বাস করো।\nএখন ভাবলে, সেটা সম্ভবত আমার সবচেয়ে বড় অনুশোচনার বিষয়ও বটে। ধুর, আমি কখনো ভাবিনি যে মানুষ হত্যার জন্য আমি অনুতাপ করব।\nআমার চেয়ে ভালো কেউ জানে না, তথাকথিত ক্ষমাপ্রার্থনা কতটা মূল্যহীন। তবে সেই দিন আসার আগে, আমি কিছুটা ক্ষতিপূরণ করার চেষ্টা করব, শুধুমাত্র কারণ আমি এটা করতে চাই।\nভবিষ্যতে যখন তুমি সেই ঘটনার জন্য আমাকে ঘৃণা করবে, তখন এ নিয়ে কোনো মানসিক বোঝা অনুভব করার দরকার নেই।\nআমি তোমাদের সমস্ত ক্রোধ সম্পূর্ণভাবে মেনে নেব।\n\nH"
  },
  Mail_124775_Name = {
    Text = "তুমি এর জন্য অনুতপ্ত হবে..."
  },
  Mail_124775_Sender = {
    Text = "হেলট: ক্যাটেনা"
  },
  Mail_124776_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআবারও সেই জন্মদিন এসে গেল। নিয়ম অনুযায়ী এটি জীবন পাওয়ার উদযাপনের দিন, তাই প্রতিবার এই দিনটি এলে আমার মনে কিছু অদ্ভুত অনুভূতি জেগে ওঠে।\nআমার জন্ম যেন মৃত্যুকে তাড়া করার জন্যই হয়েছিল। মৃত্যু নামক বিষয় থেকে বিচ্ছিন্ন হওয়ার পর, জীবন... বা বলা যায় চেতনা যে এখনও টিকে আছে এই মুহূর্তটি, আমার কাছে আসলে কী অর্থ বহন করে?\nজীবদ্দশায়, যন্ত্রণা ও অপরাধবোধের টানাপোড়েন আমার জীবনের সাথে এতটাই অবিচ্ছেদ্যভাবে জড়িয়ে ছিল যে, মনে হয় মৃত্যু আসার পরেই জীবন প্রথমবারের মতো সত্যিকার অর্থে আমার নিজের হয়েছে।\nগত বছর, এই বছর, এবং হয়তো আগামী প্রতিটি বছর। আমি প্রায় অন্তহীন দীর্ঘ সময় পেয়েছি অনুভব করার জন্য, প্রতিটি দিন আগের দিনের মতো, আবার আগের দিন থেকে আলাদাও। যখন জীবন আর যন্ত্রণা ও উদ্দেশ্যের বন্ধনে আবদ্ধ নয়, তখন এর শেষ পরিণতি কেমন হবে, নাকি তথাকথিত সেই শেষ আর কখনো আসবেই না?\nএই প্রশ্নটি এতটাই বিশাল যে, আমি কিছুটা বুঝে উঠতে পারছি না।\nকিন্তু এই অপরিচিত ভাবনাগুলো লিখে রাখার তাগিদ এতটাই বাস্তব যে, আমার মনে হয় উত্তরটা যেন স্পষ্টই প্রকাশিত।\nঅন্তত আমার কাছে, এই বাস্তব ও মূল্যবান মুহূর্তগুলোই সব। আমার চিন্তা যতই বিক্ষিপ্ত হোক, আমি যতই শেকড় খুঁজে পেতে কষ্ট পাই, আমি স্পষ্টভাবে জানি, সেগুলো কোথায় ভেসে যেতে পারে, কোথায় গৃহীত হতে পারে, এবং আমিও সমান আগ্রহে সেগুলো আপনার কাছে প্রকাশ করতে চাই।\nহয়তো আগামী বছর আজকের দিনে, আমি আরও কিছু নিজস্ব অর্থ খুঁজে পাব, কিন্তু এই মুহূর্তে, আমি স্বার্থপরভাবে এই ছোট্ট নির্ভরতাটুকু ধরে রাখতে চাই, যা শুধু আপনি আর আমি জানি।\nহ্যাঁ, গোপনীয়তার রক্ষক, আপনি এবং মিসাগের সবাই, আমার হৃদয়ের সেই গোপন শেকড় যা কেউ জানে না।\nআপনাকে ধন্যবাদ, চিরকালের মতোই, কামনা করি আপনি চিরকাল আনন্দে থাকুন, চিরকাল শান্তিতে থাকুন।\n\nনিনফিয়া"
  },
  Mail_124776_Name = {
