  },
  Mail_124777_Desc = {
    Text = "আমি সম্প্রতি এক নতুন বিশ্রামের পদ্ধতি আবিষ্কার করেছি——দৈব রাজ্যে দুপুরের বিশ্রাম।\nসাধারণ সংক্ষিপ্ত ও তাড়াহুড়োর দুপুরের বিশ্রামের থেকে ভিন্ন, দৈব রাজ্যে দুপুরের বিশ্রামের সময় আমি দীর্ঘক্ষণ বসে থাকা নীলপাথরের সিংহাসন ছেড়ে উঠি, কব্জি-শুঁড়গুলো দিয়ে শব্দ প্রতিরোধকারী একটি গোলক তৈরি করি, তারপর বিশেষভাবে প্রস্তুত সমুদ্রের জলে পুরো স্থানটি ভরে দিই।\nএই সমুদ্রের জল শুধু আমার পছন্দের সুগন্ধই ছড়াতে পারে না, আমার দেখতে চাওয়া দৃশ্যে রূপান্তরিত হতে পারে, এমনকি সব দিক থেকে উপযুক্ত শক্তিতে আমার শরীরকে ধরে রাখতে পারে।\nতাই, আমি যে ভঙ্গিমাতেই থাকি না কেন, সর্বোচ্চ মানের পালকের বিছানায় শুয়ে থাকার মতো উষ্ণ আবেষ্টনের অনুভূতি উপভোগ করতে পারি।\nসেই সময়, আমি প্রিয় সুগন্ধে মন শিথিল করতে পারি, বিশ্ব থেকে বিচ্ছিন্ন নিস্তব্ধতা উপভোগ করতে পারি, এবং আমার সবচেয়ে প্রিয় বালিশে মাথা রেখে শান্তিতে ঘুমিয়ে পড়তে পারি।\nআমার সবচেয়ে প্রিয় প্রজা হিসেবে, আমি মনে করি জন্মদিনের দিনটিই তোমার সাথে এই আরামদায়ক অভিজ্ঞতা ভাগ করে নেওয়ার সবচেয়ে উপযুক্ত সময়। তুমি আগ্রহী হলে, গতবার তোমাকে বলা সেই গোপন জায়গায় এসো। তোমার নিরাপত্তা নিয়ে চিন্তা করো না, আমি তোমার জন্য আলাদা একটি স্থান তৈরি করব, যাতে আমার উপচে পড়া স্বপ্নের প্রভাব থেকে তুমি মুক্ত থাকো।\nতোমার সবচেয়ে আরামদায়ক বালিশটি আনতে ভুলো না।\n\nতুলু"
  },
  Mail_124777_Name = {
    Text = "দুপুরের বিরতি..."
  },
  Mail_124777_Sender = {
    Text = "তুলু"
  },
  Mail_124778_Desc = {
    Text = "আমার পথপ্রদর্শক:\n\nআমি এবং ক্যাস্টর মিসাগের জীবনে মানিয়ে নিয়েছি। চার্চের রক্তাক্ত ষড়যন্ত্র থেকে পালিয়ে আসার পর, আমি অনুভব করছি যে আমি আমার আগের নিজেকে ফিরে পাচ্ছি।\nযদিও এখনও দৈনন্দিন কথাবার্তা ও আচরণে অনিবার্যভাবে 「সন্ত পুত্র」-এর কিছু ছায়া মিশে থাকে, তবে আমি বিশ্বাস করি অচিরেই সেই অহংকার ও বিচ্ছিন্নতা সম্পূর্ণরূপে ধুয়ে ফেলতে পারব, শুধু দেবতার প্রতি বিনয় এবং নিজের পথে চলার দৃঢ় সংকল্পটুকু রেখে দেব।\nকিছুক্ষণ আগে আমি একটি অপ্রত্যাশিত উপহার পেয়েছি — একটি সুন্দরভাবে বাঁধানো বই, যেটি এমন এক প্রবাসীর গল্প বলে যে নিজের জন্মভূমিতে ফিরে এসে তার শৈশব খুঁজে পায়। এর সাথে একটি চিরকুটও ছিল, যাতে লেখা ছিল 「তুমি যত তাড়াতাড়ি সম্ভব তোমার আদি সত্তাকে ফিরে পাও, সেই কামনা করি।」\nএই কথাটি চোখে পড়তেই, অতীতের সেই সব স্মৃতি মনে ভেসে উঠল — মিসাগের সবার যত্ন, পথপ্রদর্শক তোমার দিকনির্দেশনা, আর দাদার সেই... উষ্ণ আলিঙ্গন।\nতাই এবারের জন্মদিনে, আমি মিসাগের সবাইকে আমন্ত্রণ জানাতে চাই আমার ও দাদার জন্মদিনের ভোজে যোগ দিতে। সবার সাহায্য ছাড়া, আমাদের পক্ষে সেই আদি সময়গুলো ফিরে পাওয়া কখনোই সম্ভব হতো না।\nআমি সম্প্রতি জমানো সঞ্চয় দিয়ে একটি রেস্তোরাঁ পুরোটা বুক করেছি। সেখানকার প্রধান শেফ বিশ্বের বিভিন্ন দেশের রান্নায় পারদর্শী, আমি বিশ্বাস করি প্রত্যেকেই সেখানে নিজের সবচেয়ে পরিচিত স্বাদ উপভোগ করতে পারবেন।\n\nপলিউক্স"
  },
