  },
  Mail_124779_Desc = {
    Text = "আমি শহরতলির সেই ভূগর্ভস্থ যুদ্ধক্ষেত্রের আমন্ত্রণ গ্রহণ করার সিদ্ধান্ত নিয়েছি, জীবন-মরণ নির্বিশেষে একটা লড়াইয়ে নামব।\nযদিও ট্রাউট ক্লাবে দিনগুলো ভালোই কাটছিল, কিন্তু এটা খুবই একঘেয়ে, প্রতিদিন হয় মাছ মারো নয়তো মাছ মারো, হয়তো আমি সত্যিই ট্রাউটকে পুরোপুরি জয় করেছি, কিন্তু ট্রাউট জয় করাকে কি আদৌ জয় বলা যায়!\nআমার শরীরে যোদ্ধার রক্ত টগবগ করে ফুটছে, তারা সবসময় রক্ত টালমাটাল করা একটা লড়াইয়ের জন্য তৃষ্ণার্ত ছিল, আর এখন, সুযোগ এসেছে।\nআমার সাথে যোগাযোগ করা সেই টাকমাথা লোকটা বলেছে আমার জন্য তিনটা নাতাই দৈত্যাকার অজগর, দুটো ভূতমুখী ভালুক, চারটা সেরিনা বন কুমির আর একগাদা অদ্ভুত প্রাণী জোগাড় করেছে যাদের নাম আমার মনে নেই, সারারাত মনভরে লড়াই করার জন্য যথেষ্ট।\nআমি বিশেষভাবে তাদের দিয়ে আজকের দিনে লড়াইটা রাখিয়েছি, যাতে জন্মদিনেই তোমাকে দেখাতে পারি——আমি, ইউউহাশি, শেষ রোমান যোদ্ধা, পৃথিবীর সমস্ত হিংস্র পশুকে জয় করার মহাদৃশ্য!\nআজ মাঠ ভরে যাবে আর ট্রাউটের ছাঁটাই টুকরো দিয়ে নয়, বরং রক্ত আর বিচিত্র পশু-শিকারি পাখিদের দেহাবশেষে!\n\nইউউহাশি"
  },
  Mail_124779_Name = {
    Text = "পশুকে জয় করো"
  },
  Mail_124779_Sender = {
    Text = "উভহাশ"
  },
  Mail_124780_Desc = {
    Text = "「সিলভার কী নাইট」：\n\nগোপনরক্ষক! এইমাত্র আমি যখন 「ফ্যান্টম」 মডিফাই করছিলাম, তখন মস হঠাৎ আমাকে একটা বিশা——ল ব্যাগ ভর্তি যন্ত্রাংশ পাঠিয়ে দিল, বলল এটা আমার জন্মদিনের উপহার, তখনই মনে পড়ল আজ আমার জন্মদিন!\nতাই তাড়াতাড়ি তোমাকে একটা চিঠি লিখলাম, সত্যিই তো, আমি আবারও আজকের কথা ভুলে গেলাম কীভাবে, যদিও আমি আগেই লিখে রেখেছিলাম……কতগুলো নোট লিখেছিলাম সেটা?\nযাই হোক, এসব গুরুত্বপূর্ণ না, গুরুত্বপূর্ণ হলো, আমার মনে পড়ে গেছে আগে বলেছিলাম জন্মদিনে কী করব——আমি 「ফ্যান্টম」-এ চড়ে তোমাকে আর মসকে নিয়ে পুরো লন্ডিনিয়াম একশো বার ঘুরব!\nযদিও মস যন্ত্রপাতি সম্পর্কে কিছুই বোঝে না, কিন্তু তার সেই ব্যাগে এত বেশি যন্ত্রাংশ ছিল যে আমি সব দরকারি যন্ত্রাংশ জোগাড় করে ফেলতে পেরেছি। এখন মডিফাই করার পর 「ফ্যান্টম」 হয়ে গেছে সুপার এনহ্যান্সড প্রোটোটাইপ ভার্সন (সাময়িকভাবে)!\nআমি এই অ্যাডভেঞ্চারের একটা নাম দিয়েছি, নর্দিলা ও গোপনরক্ষক ও মস ও 「ফ্যান্টম」-এর অ্যাডভেঞ্চার, কেমন, সোজাসাপ্টা আর মনে রাখা সহজ তাই না? এভাবে আমি নিশ্চিতভাবে এই অ্যাডভেঞ্চার ভুলব না।\nহেহে, সত্যিই উত্তেজনাকর, গোপনরক্ষক একটু অপেক্ষা করো, 「ফ্যান্টম নাইট」 নর্দিলা আর 「ভর্টেক্স নাইট」 মস এখনই আসছে!\n「ফ্যান্টম」 অ্যাডভেঞ্চার দল, যাত্রা শুরু!\n\nপুরো গতিতে ছুটে আসছে এমন নর্দিলা"
  },
  Mail_124780_Name = {
    Text = "「ফ্যান্টম」 আক্রমণ!"
  },
  Mail_124780_Sender = {
    Text = "নটিলা"
  },
  Mail_124793_Desc = {
    Text = "শ্রদ্ধেয় মহান <Del:আদুরে> গোপনরক্ষক {Male=先生, Female=小姐}：\n\nআহেম আহেম, অনেকদিন যোগাযোগ হয়নি, আমাদের প্রিয় গোপনরক্ষক {Male=先生, Female=小姐} কি আমাকে মনে করেছে~\nএখন তুমি কিন্তু মিসাগার্ডের বিখ্যাত ব্যক্তি! সব ছাত্রছাত্রী তোমার বীরত্বগাথা পড়ছে, তোমার সাথে সামান্যতম সম্পর্ক আছে এমন যেকোনো জিনিস কালোবাজারে আকাশছোঁয়া দামে বিক্রি হচ্ছে!\nতবে এটা স্বাভাবিকই, কারণ তুমি তো 「জীবন্ত কিংবদন্তি」, মিসাগার্ডের একমাত্র গোপনরক্ষক!\nএই এক বছরে মিসাগার্ডেও অনেক মজার ঘটনা ঘটেছে——ওরিটা কয়েকটা জিঞ্জারব্রেডের সাথে বন্ধুত্ব করেছে, প্রফেসর ডোর তার ব্রেইন ট্যাংকের নতুন ডিজাইন করতে গিয়ে সতেরোটা ল্যাব উড়িয়ে দিয়েছে, কাস্টরকে আগ্রিপা ঠকিয়ে তার পরীক্ষায় সাহায্য করতে নিয়ে গেছে, কিন্তু সেটা ছিল সাধারণ জ্ঞানের পরীক্ষা, আর শেষ ফলাফল আগ্রিপা নিজে দিলে যা হতো তার চেয়েও খারাপ হয়েছে!\nওহ হ্যাঁ, আর সেই জঘন্য ছোট ইঁদুরটা, আমার মূল্যবান ফিল্ম চুরি করে নিয়ে গেছে, সেটা কিন্তু অনেক কষ্টে তোলা 「24」 ম্যাডামের বিড়াল রূপের ছবি ছিল!\nএছাড়াও আরও অনেক কিছু আছে, আমি সেগুলো গুছিয়ে স্কুল পত্রিকার নববর্ষ বিশেষ সংখ্যা হিসেবে তোমাকে পাঠিয়ে দিলাম।\nকী? তুমি জানতে চাও আমি কীভাবে তোমার সাথে যোগাযোগ করলাম? হেহে, এটা গোপন, আমি কিন্তু বলব না যে আমি অনেক একচেটিয়া গোপন তথ্যের বিনিময়ে দেখতেই ভয়ংকর এক ম্যাডামের কাছ থেকে এটা জোগাড় করেছি!\nনতুন বছরে চলো একসাথে চেষ্টা করি, শুভ নববর্ষ, %player%!\n\nহান্না পিসলি"
  },
  Mail_124793_Name = {
    Text = "নববর্ষ বিশেষ!"
  },
  Mail_124793_Sender = {
    Text = "হান্না পিজলি"
  },
  Mail_124794_Desc = {
    Text = "বিবর্ণ দূত:\n\nরজত তুষারের মৌসুম আসন্ন, অনুগ্রহ করে আমাকে এখানে প্রথমেই আপনাকে আমার আন্তরিকতম শুভেচ্ছা জানাতে দিন।\n\nগতবার আমি যখন লিলিয়ান দরিদ্রাশ্রমে শিশুদের দেখতে গিয়েছিলাম, কিছু শিশু আমাকে চুপিচুপি জিজ্ঞেস করেছিল 「শীতযাত্রার দূত কি সত্যিই আছে?」।\nআমি কৌতূহলী ছিলাম কেন এই শিশুদের মনে এমন ধারণা জন্মেছে, কারণ আমার যদি ঠিক মনে থাকে, গত বছর প্রতিটি শিশুই 「শীতযাত্রার দূত」-এর কাছ থেকে উপহার পেয়েছিল।\nতখন শিশুরা আমাকে বলল——「আমি দেখেছি সেই সুদর্শন লোকটা উপহারগুলো ডায়ানা অধ্যক্ষার কাছে দিয়ে গেছে, তাকে দেখতে মোটেও শীতযাত্রার দূতের মতো লাগে না!」।\nমনে হয় মহামান্য লর্ড যখন দরিদ্রাশ্রমে উপহার পাঠাচ্ছিলেন, তখন অসাবধানতাবশত শিশুদের চোখে পড়ে গেছে, আর তাই পরবর্তীতে এই ছোট্ট সন্দেহগুলো তৈরি হয়েছে।\n\nতাই এবছর রজত তুষারের রাতে, আমি দুই সেট অত্যন্ত ঐতিহ্যবাহী শীতযাত্রার দূতের পোশাক প্রস্তুত করেছি, এবং আমি চাই বিবর্ণ দূত আপনি আমার সাথে শীতযাত্রার দূত সেজে এই শিশুদের উপহার দিতে যান।\nআমি নিশ্চিত কোনো না কোনো শিশু রাতে চুপিচুপি চোখ খুলে আমাদের লাল পোশাক আর লাল টুপির রূপটি মনে গেঁথে নেবে, আর তারপর শীতযাত্রা উৎসবে উল্লাসের সাথে সবাইকে জানাবে——「আমি শীতযাত্রার দূতকে দেখেছি!」।\nসেই সাথে আমি বিশেষভাবে আপনার জন্যও একটি উপহার প্রস্তুত করেছি, আশা করি আপনার পছন্দ হবে।\nশীতযাত্রা উৎসবের শুভেচ্ছা। \n\nসালভাদোর"
  },
