  Mail_124991_Desc = {
    Text = "প্রিয় রক্ষক,\n「Manifold Healing: Rerun「 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট ইভেন্ট মুদ্রা 「Memory Puzzle「 আমরা প্রতি একক 40টি Rose Scrips বিনিময় হারে প্রত্যাহার করব। অনুগ্রহ করে আপনার পুরস্কারগুলি পরীক্ষা করতে ভুলবেন না।"
