  },
  Mail_126934_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআবারও সেই বিশেষ দিনটি এসে গেছে। হা, চিন্তা করো না, এবার আমি তোমার উপর কোনো মানসিক প্রভাব খাটাব না। আমি শুধু আমার সবচেয়ে বিশেষ রোগীকে কোথাও একটু ঘুরে আসার জন্য আমন্ত্রণ জানাতে চাই।\nসেখানে ঘন সবুজ বনানী আছে, স্বচ্ছ নদীর জল আছে, প্রকৃতির সুবাসে ভরপুর — যা তোমাকে ইস্পাত অরণ্যের ক্লান্তি ভুলিয়ে দেবে। সেখানে নরম গালিচা থাকবে, উষ্ণ অগ্নিকুণ্ড থাকবে, উজ্জ্বল আলো থাকবে — যা শহরের দ্রুতগতির চাপ থেকে তোমাকে মুক্তি দেবে।\nআমরা সেখানে হাঁটতে পারি, বই পড়তে পারি, গল্প করতে পারি — তুমি যা কিছুই বলতে চাও, আমি আনন্দের সাথে শুনব।\nআহ, শুধু এমন দৃশ্যের কল্পনাতেই আমার হৃদয় আন্দোলিত হচ্ছে...\nআমি জানি, এই মুহূর্তে তুমি নিশ্চয়ই একটু অস্বস্তি বোধ করছ। সর্বোপরি, আমি নিশ্চয়তা দিতে পারি না যে তোমার সেই মিষ্টি যন্ত্রণাময় স্মৃতিগুলো উপভোগ করা থেকে নিজেকে বিরত রাখব। তবুও তুমি আসবে, তাই না?\nশুধু এই কারণে নয় যে আজ আমার জন্মদিন, বরং এই কারণেও যে তোমার আমাকে প্রয়োজন, তোমার মনের কথা আমাকে বলা প্রয়োজন, আমার শোনা তোমার প্রয়োজন।\nভালো বাচ্চা, আমি বুঝি, এবং আমিও তোমার জন্য অপেক্ষা করব। এসো, ব্যস্ত দৈনন্দিন জীবন আর ভারী দায়িত্বের কথা ভুলে যাও, এই প্রশান্তির মুহূর্তটি উপভোগ করো।\n\nক্লেমেন্টাইন"
  },
  Mail_126934_Name = {
    Text = "এক মুহূর্তের শান্তি"
  },
  Mail_126934_Sender = {
    Text = "ক্লেমেন্টাইন"
  },
  Mail_126935_Desc = {
    Text = "আবারও একটি বিরক্তিকর দিন।\nআমি অনেক কিছু চেষ্টা করেছি—ফিলিস্তিনি ঐতিহ্যবাহী ভোজসভা, লন্ডিনিয়ামের সেই দলগুলোর সাথে ছেলেমানুষি খেলা—কিন্তু কোনোটিই দৈত্যরাজের জন্মদিনের উপহার হিসেবে যোগ্য নয়।\nফিলিস্তিনিরা যুদ্ধ ও হত্যায় আনন্দ খোঁজে। এক সময় এই দিনে আমি শিবিরে সবচেয়ে শক্তিশালী যোদ্ধাদের সাথে মিলিত হতাম, লড়াই করতাম, শক্তি ও রক্ত দিয়ে এই মহান দিনটিকে স্মরণ করতাম।\nশান্তি। একঘেয়ে শান্তি। আমি বুঝি তোমাদের মতো মানুষেরা শান্তির জন্য আকাঙ্ক্ষা করে, কারণ সবার মধ্যে যোদ্ধার উচ্চাকাঙ্ক্ষা থাকে না। তবে, মনে করো না যে এই মিথ্যা শান্তি মহান ফিলিস্তিনের প্রভুকে প্রভাবিত করতে পারবে।\nএক সময় যা আমার ছিল—ভূখণ্ড, সম্পদ, ক্ষমতা, ফিলিস্তিনের অবিনশ্বর গৌরব… যেদিন আমি সেগুলো ফিরে নেব, সেদিন আমি তোমাকে আমন্ত্রণ জানাব, গোপন রক্ষক। আমি তোমাকে আমার পাশে সবচেয়ে সম্মানিত অতিথির আসনে বসাব, আর তুমি দেখবে মহান দৈত্যরাজ তাঁর গৌরব ফিরে পাচ্ছেন।\nমূলত এই বিরক্তিকর দিনটি সরাসরি শেষ করার কথা ভাবছিলাম, কিন্তু এইমাত্র শুনলাম যে ছত্রভঙ্গ হওয়া সেই দলগুলো একটি জোট গঠন করেছে এবং আজকের রাতের ভোজে দৈত্যরাজকে ঘিরে ধরার পরিকল্পনা করছে।\nফিলিস্তিনিদের যুদ্ধের তুলনায় এটি নিছক শিশুসুলভ খেলা। তবে এই একঘেয়ে শান্তির দিনগুলোতে এমন একটি বিনোদনের ব্যবস্থা থাকলে, তা আমাকে কিছুটা সন্তুষ্ট করে।\nএসো, ফিলিস্তিনের প্রভুর যুদ্ধের বীরত্ব আরেকবার প্রত্যক্ষ করো। আমার পাশে দাঁড়াও, অথবা আমার বিপরীতে—যেভাবেই হোক চলবে।\nতবে দ্রুত এসো। বেশি দেরি হলে, শুধু লাশ গোনার কাজ বাকি থাকবে।\n\nগোলিয়াথ"
  },
  Mail_126935_Name = {
