  Mail_126937_Desc = {
    Text = "হা, আজকে কী হচ্ছে? আমি যেখানেই যাচ্ছি, সবাই ইচ্ছাকৃতভাবে আমাকে এড়িয়ে চলছে? এমনকি আমি মুখ খোলার আগেই, তারা হাত নেড়ে বলছে যে তাদের এখানে অস্বস্তি, ওখানে ব্যথা, ফলে আমি দ্বন্দ্বযুদ্ধের প্রস্তাব দেওয়ারই সুযোগ পাচ্ছি না।\nকষ্ট করে 「জন্মদিন」-এর এই দিনটায় কোনো কারণ ছাড়াই অন্যদের সাথে লড়াই করা যায়, কিন্তু এভাবে হলে তো সাধারণ দিনের সাথে কোনো পার্থক্যই থাকে না?\nচিশ, গত বছর ওদের এত খারাপভাবে মারা উচিত হয়নি। তবে এটাও অনিবার্য ছিল, কারণ এই গ্রহের জন্মের আগে থেকেই আমি নিরন্তর আমার তলোয়ার কৌশল শাণিত করে চলেছি, সাধারণ মানুষ সহ্য করতে না পারাটাই স্বাভাবিক।\nতবে, তুমি তাদের থেকে আলাদা, তুমি তো একজন স্টেলারন হান্টার!\nতাই তুমি বুঝতেই পারছ আমি কী বলতে চাইছি, তাই না? গত বছরের সেই জায়গায়, চলো মনের সুখে একটা লড়াই করি। এবার, কেউ আমাদের লড়াইয়ে বাধা দেবে না।\n\nলুওতান"
  },
