  },
  Mail_126938_Desc = {
    Text = "সবচেয়ে সবচেয়ে সবচেয়ে প্রিয় মালিক:\n\nআপনি কি শুনেছেন? আজ মেয়রের প্রাসাদে একটি অত্যন্ত জাঁকজমকপূর্ণ নৃত্যানুষ্ঠান অনুষ্ঠিত হবে, এবং সকল ভদ্রমহোদয় ও ভদ্রমহিলা এই অনুষ্ঠানে যোগ দিতে পারাকে সম্মানের বিষয় মনে করেন।\nঅবশ্যই, একজন পরিচারিকা হিসেবে, কারেনের এতে যোগ দেওয়ার যোগ্যতা নেই। কিন্তু আপনি, মিসাগার্ড রহস্যরক্ষক, আমার প্রিয়, সবচেয়ে প্রিয় মালিক, আপনি পৃথিবীর সমস্ত সুন্দর জিনিসের যোগ্য, এবং অবশ্যই এই নৃত্যানুষ্ঠানেরও যোগ্য।\nতাই কারেন ইতিমধ্যেই আপনার হয়ে আমন্ত্রণ গ্রহণ করেছে, এমনকি যত্ন সহকারে আপনার জন্য ঘোড়ার গাড়িও ডেকেছে, সবকিছু ঠিকঠাক করে রেখেছে, তখন আপনাকে শুধু কারেনের সাথে মেয়রের বাড়িতে যেতে হবে~\nকারেন তার সবচেয়ে সুন্দর পোশাক পরবে, সবচেয়ে ঝলমলে গয়না পরবে, যাতে সবাই সর্বগুণসম্পন্ন পরিচারিকার ক্ষমতা দেখতে পায়, আপনার মুখ উজ্জ্বল করবে, আপনার গৌরব বাড়াবে!\nআহ, আপনি যখন এই চিঠিটি পড়ছেন, আমি সম্ভবত ইতিমধ্যেই আপনার দরজার বাইরে অপেক্ষা করছি, সেই ঘোড়ার গাড়ি, নতুন পোশাক ও গয়না নিয়ে আসা ভৃত্যরাও ইতিমধ্যে প্রস্তুত, একমাত্র ছোট্ট সমস্যা হলো, এই সেবাগুলোর বিল এখনও পরিশোধ করা হয়নি……\nকিন্তু আমার সবচেয়ে দয়ালু ও মিষ্টি মালিক এই ছোটখাটো বিষয়ে কখনোই বিরক্ত হবেন না, তাই না? মেয়র এখনও আমাদের জন্য অপেক্ষা করছেন~\n\nআপনার সবচেয়ে আদুরে, সবচেয়ে উজ্জ্বল পরিচারিকা\nকারেন"
  },
  Mail_126938_Name = {
    Text = "মহা নৃত্যোৎসব"
  },
  Mail_126938_Sender = {
    Text = "কারেন"
  },
  Mail_126940_Desc = {
    Text = "গোপনরক্ষক, গোপনরক্ষক! কয়েকদিন আগে, জেনকিন বলেছিল যে সে ওরিটার বাড়ির মতো একটা জায়গা খুঁজে পেয়েছে, মনে হয় নামটা জল... উম, ওরিটা ভুলে গেছে।\nযাই হোক, জেনকিন বলেছে সেখানে ডলফিন, ছোট মাছ, অ্যাকুরিয়াম আর অনেক অনেক জেলিফিশ আছে, আর বলেছে তারা সবাই ওরিটার বন্ধু হতে রাজি!\nওরিটা বন্ধুদের ভালোবাসে, ওরিটা অনেক অনেক বন্ধু চায়, তাই ওরিটা জন্মদিনে তার সবচেয়ে প্রিয় বন্ধু, মানে গোপনরক্ষককে একসাথে যেতে আমন্ত্রণ জানাতে চায়।\nতাড়াতাড়ি জিনিসপত্র গুছিয়ে আমার সাথে রওনা হও, ওরিটা আর অপেক্ষা করতে পারছে না।\n\nঅনেক অনেক নতুন বন্ধু তৈরি করতে চাওয়া ওরিটা"
  },
  Mail_126940_Name = {
    Text = "অ্যাকোয়ারিয়ামে নতুন বন্ধু!"
  },
  Mail_126940_Sender = {
    Text = "অরিটা"
  },
  Mail_126941_Desc = {
    Text = "গোপনীয়তার রক্ষক:  \n\nআজ ভোরবেলা সমুদ্রতীরে আমার সাথে হাঁটার জন্য আপনাকে ধন্যবাদ। সেই আছড়ে পড়া ঢেউ, উজ্জ্বল তারাভরা আকাশ — সবকিছু আমাকে প্রশান্তি দিয়েছিল, আর মনে করিয়ে দিয়েছিল... অনেক অনেক আগের কথা।\nসেই সময়, নাবিকদের আমার সাথে কথা বলা নিষিদ্ধ ছিল, তাই বেশিরভাগ সময় আমি শুধু ক্রমাগত পরিবর্তনশীল সমুদ্রপৃষ্ঠ আর আকাশে চক্কর দেওয়া সামুদ্রিক পাখিদের দিকে তাকিয়ে থাকতাম। নাবিকেরা সেই উড়ন্ত পাখিদের দেখে অজান্তেই আমার কাছে মনোকামনা করত।\nকখনো তারা পাখি হয়ে উড়ে যেতে চাইত, নিজের জন্মভূমিতে, প্রিয়জনের কাছে ফিরে যেতে; কখনো তারা চাইত যাত্রা তাড়াতাড়ি শেষ হোক, জাহাজের মালামাল বিনিময়ে প্রচুর সম্পদ আসুক; কখনো তারা রোমান্টিক প্রেমের জন্য প্রার্থনা করত, অথবা কিংবদন্তির সমুদ্রদানবী মৎস্যকন্যার সাক্ষাৎ কামনা করত...\nকিন্তু যত বিচিত্র ইচ্ছাই হোক না কেন, গভীর রাতে সব একই হয়ে যেত — শান্তিপূর্ণ ঘুমের আকাঙ্ক্ষায় রূপান্তরিত হতো। তখন আমি তাদের প্রার্থনায় সাড়া দিতাম, সমুদ্রের বাতাসকে শান্ত করতাম, সমুদ্রের জলকে কোমল করে তুলতাম।\nতাই, গোপনীয়তার রক্ষক, যদি আপনারও ঘুম না আসে, দয়া করে ভোরবেলা একা সমুদ্রতীরে ঘুরে বেড়াবেন না, বরং আমাকে খুঁজে আসুন।\nআমি আপনার চাপ ভাগ করে নিতে চাই, একজন কাজের মানুষ হতে চাই, আর আপনার শান্তিপূর্ণ ঘুমের রক্ষা করা — এটাই এখন আমার পক্ষে করা সম্ভব।\nএটাই... এই বিশেষ দিনে আমার করা 「মনোকামনা」।\n\nহিলেসেস্ট"
  },
  Mail_126941_Name = {
    Text = "তোমার নিদ্রা হোক শান্ত"
  },
  Mail_126941_Sender = {
    Text = "সেলেস্ট"
  },
  Mail_126942_Desc = {
    Text = "ভাগ্যের মহান আশীর্বাদে, মিসাগার্দ বিশ্ববিদ্যালয়ের গোপনীয়তার রক্ষক, জ্ঞানী ও দয়ালু প্রভু:\n\nশুভেচ্ছা!\nএই চিঠি লেখার সময় আমি অনেক দ্বিধায় ছিলাম, কিন্তু সততা একজন নাইটের অন্যতম গুণ। আপনার নাইট হিসেবে, আমাকে আপনার প্রতি সম্পূর্ণ আনুগত্য নিবেদন করতে হবে, কোনো কিছু গোপন না রেখে, তাই আমাকে আপনার কাছে সত্য কথা বলতেই হবে——\nজন্মদিনের এই দিনে, প্রভু, আমি আপনাকে অনুরোধ করছি আমার ঘরে এসে আমাকে ঘুমানোর আগে গল্প পড়ে শোনাতে।\nদয়া করে আমাকে অনুমতি দিন... আপনার পাশে হেলান দিয়ে, আপনার বলা সেই স্বপ্নময় ও সুন্দর গল্পগুলোর মধ্যে ঘুমিয়ে পড়তে।\nআসলে, এটা আমার শৈশবের একটি ইচ্ছা ছিল। কিন্তু নাইটের প্রশিক্ষণে এক মুহূর্তের অলসতারও জায়গা নেই, আর আমি গল্প শোনার বয়সও অনেক আগেই পেরিয়ে এসেছি, তাই আমি সবসময় এটা মনের গভীরে চাপা রেখেছিলাম, কখনো মুখে বলিনি। কিন্তু আপনি... প্রভু, আপনি আলাদা, আমি আপনার কাছে কিছু গোপন রাখতে চাই না...\nযদি আপনি এটা অনুচিত মনে করেন, তাহলে দয়া করে আমাকে জানাবেন। এরপর থেকে আমি আর এমন অতিরিক্ত অনুরোধ করব না, এবং দ্বিগুণ কঠোর প্রশিক্ষণে মনোযোগ দেব।\nআপনার উত্তরের অপেক্ষায়।\n\nওজিয়ের"
  },
  Mail_126942_Name = {
    Text = "এক নাইটের অনুরোধ"
  },
  Mail_126942_Sender = {
    Text = "ওজিয়ার"
  },
  Mail_126943_Desc = {
    Text = "ছোট্ট কয়লাবল:\n\nআজ, মস, জন্মদিন!\nবন্ধু বলেছে, জন্মদিন, চিঠি লেখ, ছোট্ট কয়লাবলকে, ছোট্ট কয়লাবল, আসবে, খেলতে!\nমস, পারে না, চিঠি লিখতে। কিন্তু, বন্ধু, পারে!\nবন্ধু, শেখায়, মসকে। মস, খুশি!\nআসলে, মস, ভুলে গেছে, জন্মদিন।\nকিন্তু, মস, চায়, ছোট্ট কয়লাবলের সাথে খেলতে!\nতাই, মস ঠিক করেছে, আজই, জন্মদিন!\nছোট্ট কয়লাবল, ঝিনুক, জমানো, সোনালি, সাদা, সব আছে~\nছোট্ট কয়লাবলকে দেখলে, খুশি~ বন্ধু, রান্না করে, মজার~\nছোট্ট কয়লাবল, পুরোনো জায়গায়~\nবন্ধুকে দিয়ে, বানিয়েছে, বড় ভোজ! একসাথে খাব!\nমস, তোমার জন্য অপেক্ষা করছে~\n\nমস"
  },
  Mail_126943_Name = {
    Text = "জন্মদিন! এসো খেলা করি!"
  },
  Mail_126943_Sender = {
    Text = "ভর্টিচে"
  },
  Mail_126944_Desc = {
    Text = "গোপনীয়তা রক্ষাকারী: \n\nকিছুদিন আগে, আপনি বলেছিলেন যে আপনি উল্কাবৃষ্টির কাছে মনোকামনা করতে চান, তাই আমি বিশেষভাবে এই সমুদ্রযাত্রার ব্যবস্থা করেছি। আমার আমন্ত্রণ গ্রহণ করার জন্য আপনাকে ধন্যবাদ, আমি প্রতিশ্রুতি অনুযায়ী সময়মতো সমুদ্রতীরে আপনার আগমনের অপেক্ষায় থাকব।\nআপনি নিশ্চিন্ত থাকুন, এটি একটি স্বল্পমেয়াদী যাত্রা, এবং আমি ইতিমধ্যে আশেপাশের সমুদ্র এলাকা পুঙ্খানুপুঙ্খভাবে পরীক্ষা করেছি। আমি গ্যারান্টি দিচ্ছি যে আপনাকে নিরাপদে উল্কাবৃষ্টি পতনের স্থানে নিয়ে যাব এবং উল্কাপিণ্ড সংগ্রহে আপনাকে সহায়তা করব।\nএভাবে, আপনি নিজের হাতে উল্কা স্পর্শ করে মনোকামনা করতে পারবেন, এবং এত কাছের দূরত্বে, উল্কা অবশ্যই আপনার হৃদয়ের কামনা শুনতে পাবে এবং আপনার ইচ্ছা পূরণ করবে! আপনার মনোকামনা পূরণের পথপ্রদর্শক হতে পারা আমার জীবনের সবচেয়ে বিশেষ কাজগুলোর মধ্যে একটি হবে, আমি অত্যন্ত সম্মানিত বোধ করছি।\nআবারও আপনাকে ধন্যবাদ, আপনিই আমাকে এই বিশেষ দিনে একটি নতুন 「পথপ্রদর্শনের দায়িত্ব」 খুঁজে পেতে সাহায্য করেছেন। অনুগ্রহ করে অবশ্যই সময়মতো আসবেন, আমি সবসময় আপনার আগমনের অপেক্ষায় থাকব।\n\nক্লেপোর্শান্তে"
  },
  Mail_126944_Name = {
    Text = "নাগালের ভেতর এক প্রার্থনা"
  },
  Mail_126944_Sender = {
    Text = "করপোস্যান্ট"
  },
  Mail_129637_Desc = {
    Text = "শুভেচ্ছান্তে:\n\nঘণ্টাঘরের পেছনের ফুলবাগান কতবার পার হয়েছি তা মনে নেই, তবে একবার আমি সেখানকার গোলাপ বাগানটির দিকে হঠাৎ নজর দিয়েছিলাম।\nএরপর আমি বহুবার এই পথ মাড়িয়েছি — কালো পুকুরের অস্থির আলোড়নের মুহূর্তে, মৃত্যু ও মুখোমুখি দাঁড়ানোর মুহূর্তে, সময়ের স্রোত উল্টে যাওয়ার মুহূর্তে — তারা সর্বদা দৃঢ়ভাবে, নীরবে সেখানে দাঁড়িয়ে ছিল, চিরকালের মতো।\nএই দৃশ্যটি আমার নয় এমন স্মৃতির মধ্যে জাগিয়ে তুলেছে সেই গোলাপের তোড়া, যা রামোনা একদা তোমাকে উপহার দিতে চেয়েছিল, এবং এতে আমি কিছুটা স্বস্তিও অনুভব করেছি।\nযদিও তুমি আর আমি মাত্রার ব্যবধানে বিচ্ছিন্ন, তবু আমি সর্বদা বিশ্বাস করি যে, যে কোনো বিপদের মুখোমুখি হলেও, তুমি আর সেই 「রামোনা」 সবসময় শান্ত ও নির্ভীক ভঙ্গিতে সমাধানের পথ খুঁজে নেবে।\nসর্বোপরি, পরিস্থিতি যেভাবেই বদলাক না কেন, গোলাপেরা সর্বদা নিজের মতো করেই ফুটে ওঠে।\n\n「রামোনা」"
  },
  Mail_129637_Name = {
    Text = "গোলাপ উদ্যান..."
  },
  Mail_129637_Sender = {
    Text = "「রামোনা」"
  },
  Mail_129806_Desc = {
    Text = "গোপনরক্ষক：\n\nসমুদ্রনগরীর প্রাসাদে, আলোকমালা জ্বলে উঠেছে। জানি না এই মুহূর্তে আপনি কোথায়, আপনার পাশে কে আছে?\nবছরের শুরু, প্রাচীন রাজ্যের সবচেয়ে গুরুত্বপূর্ণ দিন, মিলন ও নবজন্ম উদযাপনের উৎসব। এই দিনটি আমি বহুবার অতিবাহিত করেছি, কিন্তু কখনো ক্লান্তি অনুভব করিনি। শীতকাল পেরিয়ে গেছে, সবকিছু আবার বেড়ে উঠছে, মানুষ এতটাই আকাঙ্ক্ষা করে — এই মাটির মতোই সমস্ত গ্লানি গতকালে ফেলে রেখে, একটি নতুন শুরুকে স্বাগত জানাতে।\nসেই পুরনো ক্ষত আর বাসনা, সহজে ত্যাগ করা যায় না। পুরনোকে বিদায়, নতুনকে স্বাগত — কী সুন্দর শুভকামনা……হয়তো যন্ত্রণা আবার জেগে উঠবে, বাসনা কখনো মিটবে না, কিন্তু আজ রাতে, অন্তত আজ রাতে, মানুষ পানপাত্র তুলে উদযাপন করবে, একটি নতুন পৃথিবী, নতুন নিজেকে অভিনন্দন জানাবে।\nতাই, পুরনো বছর আর নতুন বছরের সন্ধিক্ষণে, মানুষ আতশবাজি দিয়ে স্বাগত জানায়।\nসব মনোরম জিনিসের মধ্যে, আতশবাজি আমার সবচেয়ে প্রিয়। সবাই তার দিকে তাকায়, দেখে তা জ্বলছে, আকাশে উঠছে, প্রস্ফুটিত হচ্ছে, যেন দেবতার দিকে তাকানোর মতো, সেই ক্ষণস্থায়ী, অতুলনীয় মহিমার দিকে।\nআপনি কি কখনো লক্ষ্য করেছেন? আতশবাজির দিকে তাকানোর সময়, প্রতিটি মানুষের হৃদয় নির্মল হয়ে যায়। তারা ঘৃণা ভুলে যায়, দুঃখকষ্ট ভুলে যায়, সমস্ত কলুষতা ভুলে যায়। সকল হৃদয় শান্ত হ্রদে পরিণত হয়, ধূলিমুক্ত জলের উপরিভাগে কেবল আতশবাজির সুন্দর প্রতিবিম্ব।\nশ্‌……জিজ্ঞেস করবেন না আতশবাজির পরে কী আসে। নবজন্ম হয়তো বিলাসিতা, কিন্তু, তাই বলে তার প্রস্ফুটনকে অবহেলা করবেন না।\nসমস্ত অসুন্দর জিনিসের মধ্যে, আতশবাজি সবচেয়ে বিশুদ্ধ। আজ রাতে, আমার নিজের অংশটুকুও আপনাকে উপহার দিতে চাই।\nমাথা তুলুন, চোখ বন্ধ করবেন না। দেখুন সেই উজ্জ্বল তারাগুলো উঠছে, আতশবাজি প্রস্ফুটিত হওয়ার সময়, একটি নতুন নিজেকে স্বাগত জানান, গোপনরক্ষক।\n\n「সেনসেন」"
  },
