    Text = "প্রিয় রক্ষক:\n「কল অফ দ্য মস্কস্ট্রোমেন」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট 「কনচ ওয়ান」, 「কনচ টু」 এবং 「কনচ থ্রি」 প্রতিটি আইটেমের বিনিময়ে 「রোজ স্ক্রিপ」 × 40 হারে রূপান্তরিত হবে। অনুগ্রহ করে আপনার পুরস্কারগুলি পরীক্ষা করতে ভুলবেন না।"
