  Mail_131767_Desc = {
    Text = "আমার@2！@3হলেন@2সর্বোচ্চ@3বিশৃঙ্খলা@4ও ধ্বংস@2！উচ্চস্বরে@4……！\n\nআরে রে রে! দেখো তুমি কী করে ফেলেছ!!! তুমি সর্বোচ্চ দেবতার নিষিদ্ধ বিষয় স্পর্শ করে ফেলেছ! এখন হয়ে গেল, তাঁর ফিসফিস তোমার জগতে প্রতিধ্বনিত হচ্ছে, কালো বিপর্যয় তোমার যোগাযোগ যন্ত্র থেকে ছড়িয়ে পড়বে, তোমার চারপাশের সবকিছু গ্রাস করবে……\nবেচারা, তোমার বেপরোয়া আচরণ সত্যিই আমাকে বিপদে ফেলেছে। তবে এত হতাশ হওয়ার দরকার নেই, দুর্ভাগ্যের মধ্যে সৌভাগ্য যে তুমি আমার দেখা পেয়েছ — মহান ধর্মসম্প্রদায়ের পরী, দেবতার মনোনীত ব্যক্তি, সর্বোচ্চ দেবতার প্রতিনিধি, মহান ধর্মসম্প্রদায়ের বৈধ উত্তরাধিকারী, দুঃখকষ্টের ত্রাণকর্তা, দেবরাজের অন্তরঙ্গ বন্ধু! আমি হলাম দয়া ও ভালোবাসার দেবতার ইচ্ছা, এই জগতের দুঃখকষ্ট সহ্য করতে পারি না, আমি আমার সর্বোচ্চ শক্তি দিয়ে প্রতিটি বোকা ছোট্ট দুষ্টুকে উদ্ধার করব।\nওহ, এই পরী তোমার ব্যঙ্গাত্মক দৃষ্টি দেখতে পাচ্ছে। কোনো সমস্যা নেই, দয়ালু দেবতা জগতবাসীকে ভালোবাসেন, মানুষের মূর্খতায় কখনো বিরক্ত হন না। ত্রাণকর্তার প্রতি অবিশ্বাস, প্রতিটি ভক্তের পথে অবশ্যম্ভাবী। এই সাক্ষাৎ উপহার হলো দেবতার প্রতিনিধির পক্ষ থেকে তোমার জন্য পুরস্কার।\nএখন, আলোকিত পথ তোমার সামনে নির্দেশিত হয়েছে: তোমার আন্তরিকতা নিয়ে, @3 নগরের @2 মহাগির্জায় যাও, দয়ার দেবতার প্রতি তোমার আনুগত্য নিবেদন করো, তাহলে তুমি স্বপ্নের শক্তি লাভ করবে, এই দুঃস্বপ্নের অভিশাপ থেকে মুক্তি পাবে। অবশ্যই, তোমার সম্পদও একসাথে নিবেদন করতে হবে। ভুল বুঝো না, দয়ার দেবতা কখনো পার্থিব প্রতিদানের পরোয়া করেন না, কিন্তু তাঁর ভক্তদেরও কাজ করতে টাকা লাগে। এসব তুচ্ছ জিনিসে কৃপণতা করো না, প্রিয় ভক্ত, যত দাম তত কাম।\nদয়ার দেবতার নাম উচ্চস্বরে জপ করো, অলৌকিক ঘটনা অবতীর্ণ হওয়ার মুহূর্তের অপেক্ষায় থাকো!\n\nমহান ধর্মসম্প্রদায়ের পরী, দেবতার মনোনীত ব্যক্তি"
  },
