  Mail_132458_Desc = {
    Text = "প্রিয় রক্ষক:\n        「মরিমেন্স」-এর প্রতি আপনার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে রক্ষকদের আরও উন্নত গেমিং অভিজ্ঞতা দিতে, আমরা আপনাকে আন্তরিকভাবে নিম্নলিখিত অভিজ্ঞতা-সমীক্ষা পূরণ করার আমন্ত্রণ জানাচ্ছি। কৃতজ্ঞতার নিদর্শন হিসেবে, আমরা পুরস্কার হিসেবে সিলভার × 200 প্রস্তুত করেছি, যা সমীক্ষা সম্পন্ন করার পর আপনি সংগ্রহ করতে পারবেন। সমীক্ষা 17 অগাস্ট সকাল 9:00-এ বন্ধ হবে। অনুগ্রহ করে সময়মতো তা পূরণ করুন।\n        <SurveyLink:[Click here to fill out]>\n        আমরা প্রতিটি রক্ষকের মতামত মনোযোগ দিয়ে বিবেচনা করব, আর আপনার মতামতই নিশ্চিতভাবে মিথাগ বিশ্ববিদ্যালয়কে আরও উন্নত করে তুলবে!\n        —রৌপ্য চাবি তোমার পথ আলোকিত করুক।"
  },
