  Mail_133704_Desc = {
    Text = "সম্মানিত কিপার:\n{s1} ভার্সন শীঘ্রই শেষ হতে চলেছে, অনুগ্রহ করে সকল কিপার অবশিষ্ট 「ফ্যান্টম কোর」 সময়মতো ব্যবহার করুন। এই সেমিস্টারের কোর্স শেষ হওয়ার পর কিপারদের অবশিষ্ট 「ফ্যান্টম কোর」 প্রতি 1টির বিনিময়ে 「পিওর কোর」× 1 এই অনুপাতে রূপান্তর করা হবে।"
