  Mail_134024_Desc = {
    Text = "সম্মানিত গোপনীয়তার রক্ষক:\n「দৈনিক প্রশিক্ষণ」 সরিয়ে দেওয়া হয়েছে। আপনার অবশিষ্ট「এজেন্ট ক্রেডেনশিয়াল」প্রতিটি「রোজ গোল্ড ভাউচার」× 10000 হারে রূপান্তর করা হয়েছে। অনুগ্রহ করে গ্রহণ করুন।"
  },
  Mail_134024_Name = {
    Text = "প্রক্সি শংসাপত্র পুনরুদ্ধার"
