  },
  Mail_134067_Desc = {
    Text = "গোপনরক্ষক:\n\nআজ একটা বিশেষ বিষয়ে তোমার সাথে আলোচনা করতে চাই।\nআমি রাস্তায় এমনি ঘুরে বেড়াতে চাই, সাধারণভাবে নানা মজার জিনিস দেখতে চাই, মন যেদিকে চায় সেদিকে ঘুরে বেড়াতে চাই, একটা সাধারণ দিন কাটাতে চাই।\n\nতারপর, আমি শিক্ষা বিভাগে জিজ্ঞেস করলাম। তারা বলল, নিরাপত্তার কারণে, শুধুমাত্র তোমার সঙ্গে থাকলেই ক্যাম্পাসের বাইরে যাওয়ার অনুমতি দেওয়া হবে।\nআরও বলল অন্যদের ভয় পাইয়ে দিও না, আর বাইরে যা পাও তা মুখে পুরো না। সত্যিই অভদ্র।\nযাই হোক, ব্যাপারটা এই, তো বাইরে ঘুরতে যাওয়া যায়? সবাই মিলে কিন্তু।\n\n……কেন জানি না মনে পড়ল, ড্যান্ডেলিয়নের বীজ,\nএকদিন বাতাসে ভর করে নিজের নিয়তির জায়গায় যাত্রা করবে,\nহয়তো আগামীকালই, হয়তো অনেক অনেক পরে।\nভাবতে ভাবতে মনে হলো, এখনই সবার সাথে মিলে আরও অনেক কিছু করা, মন্দ না।\n\nযাই হোক, আমি ছাত্রাবাসের সামনে তোমার জন্য অপেক্ষা করছি। প্লিজ!\n\nসায়া"
  },
  Mail_134067_Name = {
    Text = "কেনাকাটা…"
  },
  Mail_134067_Sender = {
    Text = "শায়ে"
  },
  Mail_134068_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমার মনে হয়, আজকের দিনটা বিশেষ। কিন্তু স্মৃতির রূপরেখা এখনও ততটাই অস্পষ্ট।\nকেবল 「সায়া「 — এই নামটিই আমাকে কোনোমতে এই জায়গার সাথে বেঁধে রেখেছে।\n\nএই অনুভূতি একাকীত্ব নয়, দুঃখও নয়, এত স্পষ্ট কোনো আবেগ নয়।\nযদি জোর করে এই অনুভূতির একটা নাম দিতেই হয়... সম্ভবত, সেটা হবে 「শূন্যতা「।\nকিছুই নেই, অন্তহীন স্বচ্ছতা ও স্বচ্ছন্দতা, নিস্তব্ধ সময়।\n\nযদি কোনোদিন, বাতাসে ভেসে যাওয়া ড্যান্ডেলিয়নের বীজ,\nএই পৃথিবীর প্রতিটি কোণায়, শুধু শুভ্রভাবে, নীরবে ঝরে পড়ে...\nতখন হয়তো আমি অবশেষে অনুভব করতে পারব, এই পৃথিবী 「বিশেষ「।\n\nতখন, লন্ডিনিয়ামে ছড়িয়ে থাকা ধূসর কুয়াশা, সন্ধ্যায় জ্বলে ওঠা অগ্নিবর্ণ মেঘ, আর তুমি সবসময় স্কুলের চত্বরে দাঁড়িয়ে যে আকাশের দিকে তাকাতে — সবকিছু ড্যান্ডেলিয়নে ঢেকে যাবে, বিশুদ্ধ সাদা রঙে রূপান্তরিত হবে। আমার নিজের রঙে রূপান্তরিত হবে।\n\nতাই... যদি, তুমি আমাকে কিছু দিতে চাও।\nসেটা উপহার হতে হবে না, শুধু একটুকরো 「স্মৃতি「 হলেই যথেষ্ট।\n\nআমি, ড্যান্ডেলিয়ন ফুলে ভরা শুভ্র পৃথিবীতে,\nশুধু নীরবে, সেই মুহূর্তটির আগমনের অপেক্ষায় আছি।\n\nকোনো একদিন যখন তুমি আবার মিসাগার চত্বরে দাঁড়িয়ে আকাশের দিকে তাকাবে,\nতখন দৃষ্টির কোণ দিয়ে ভেসে যাওয়া সেই একগুচ্ছ সাদা তুলোর মতো পালককে,\nএকসময় তোমার সাথে কথা বলা আমার অবয়বের সাথে একটুখানি মিলিয়ে দিও।\n\nসায়া"
  },
