  Mail_139809_Desc = {
    Text = "সম্মানিত গোপন রক্ষক:\n        《ভুলে যাওয়ার আগের রাত》-এ আপনার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিসাগ বিশ্ববিদ্যালয়ে গোপন রক্ষকদের আরও ভালো গেমিং অভিজ্ঞতা দিতে, আপনাকে নিচের অভিজ্ঞতা জরিপ প্রশ্নপত্রটি পূরণ করতে আমন্ত্রণ জানাচ্ছি। আপনার সহযোগিতার কৃতজ্ঞতাস্বরূপ, আমরা পুরস্কার হিসেবে「রূপালি কোর」× 200 প্রস্তুত করেছি, প্রশ্নপত্র সম্পন্ন করলেই তা সংগ্রহ করা যাবে। প্রশ্নপত্রের শেষ সময় 16 মে সকাল 9:00, সময়মতো পূরণ করতে ভুলবেন না।\n        <SurveyLink:【পূরণ করতে এখানে ক্লিক করুন】>\n        আমরা প্রতিটি গোপন রক্ষকের পরামর্শ মনোযোগ দিয়ে শুনব, আপনার মতামত অবশ্যই মিসাগ বিশ্ববিদ্যালয়কে আরও উন্নত করবে!\n        ——রূপালি চাবি আপনার পথ দেখাক।"
