  Mail_141470_Desc = {
    Text = "সম্মানিত রক্ষক：\n「প্রতিবিম্ব বন্দী·রিপ্রিন্ট」 কার্যক্রম সমাপ্ত হয়েছে। রক্ষকের অবশিষ্ট 「সাধারণ জ্ঞানের গ্রন্থ」、「গণিতের গ্রন্থ」、「সাহিত্যের গ্রন্থ」 প্রতিটির বিনিময়ে 「সোনালি গোলাপ」× 40 হারে রূপান্তরিত করা হয়েছে। রক্ষক নোট রাখুন এবং গ্রহণ করুন।"
