  Mail_141507_Desc = {
    Text = "গোপনরক্ষক：\n\nজন্মদিন—তোমার কাছে এটি হয়তো একটি গুরুত্বপূর্ণ দিন?\nআমার কাছে, ভাগ্যের জালে প্রতিটি দিনের ভার সমান। অন্যান্য গল্পই এই দিনটিকে বিশেষ অর্থ দান করেছে।\nএই দিনেই আমার জন্ম হয়েছিল, এই দিনেই আমি ভবিষ্যদ্বাণী উপলব্ধি করেছিলাম, এই দিনেই আমি ভাগ্য বুনবার চরকা পেয়েছিলাম, এই দিনেই আমি সেই জটিল ভাগ্যের সুতোগুলো দেখেছিলাম—আর সুতোর শেষ প্রান্তে লুকিয়ে থাকা দুঃস্বপ্নও।\nভাগ্যের বুনকারের কাছে এই দিনটি নিতান্তই সাধারণ। মঞ্চের অভিনেতার কাছে এই দিনটি উদযাপনযোগ্য। আর আমার সকল পরিচয়ের মধ্যে, যেটি আমাকে সবচেয়ে বেশি আনন্দ দেয়, সেটি হলো অভিনেতা হিসেবে আমার নিজের সত্তা।\nগোপনরক্ষক, আজ ভাগ্য-নাট্যশালার সমস্ত আলো নিভে গেছে, কেবল একটি মঞ্চই আলোয় উজ্জ্বল। তুমি একবার বলেছিলে, আমি যে ভাগ্যের মধ্য দিয়ে গেছি তার আরও বেশি দেখতে চাও। আর এখন, এই মঞ্চে যা মঞ্চস্থ হতে চলেছে, তা আমার নিজেরই একটি গল্প।\nকোন অংশটি মঞ্চস্থ হবে তা আমি জানি না। আমি আমার স্মৃতিগুলো মঞ্চে তুলে দিয়েছি, আর সে সেই তীব্র মুহূর্তগুলোর মধ্য থেকে বেছে নেবে—যেটি তুমি সবচেয়ে বেশি দেখতে চাও—আজ রাতের মঞ্চে তা উপস্থাপন করবে।\nসেই গল্প হয়তো আমাকে যন্ত্রণা দেবে, হয়তো আমাকে বিব্রত করবে, কিন্তু এসব কি আদৌ গুরুত্বপূর্ণ? আমার মনে হয়, মাঝে মাঝে চরকাকে নিজে থেকে বুনতে দিয়ে, একজন নিখাদ দর্শক হওয়া—এটি সত্যিই আনন্দদায়ক।\nএই অনুষ্ঠানের একমাত্র প্রবেশপত্র এখন তোমার হাতে। এই চিঠি নিয়ে এসো, গোপনরক্ষক। আজ রাতে, এমন একটি গল্প যা আর কেউ জানে না, তোমার আগমনের অপেক্ষায় রয়েছে।\n\nআরাকনে"
  },
