  },
  Mail_142101_Desc = {
    Text = "অনেকদিন পর, %player%：\n\nতুমি যখন এই চিঠি পাবে, আমি তখন সম্ভবত ইয়াগ্রোর আকাশের উপর দিয়ে যাচ্ছি। প্রতি বছর এই মাসে, আমার শিকার যাত্রা সবসময় আরও দূরে চলে যায়।\nশত্রুর আর্তনাদ আর চিৎকারের চেয়ে জন্মদিনের সুর হিসেবে আর কিছুই মানানসই নয়। তাছাড়া আমি যথেষ্ট খাঁচা প্রস্তুত করেছি — যতক্ষণ কোনো বোকা সেই মিথ্যা দেবতাদের পূজা করার সাহস দেখাবে, যারা শুধু যন্ত্রণা ছাড়া কোনো মুক্তি দিতে পারে না, পৃথিবীর যেকোনো প্রান্তে হোক না কেন, আমি তাদের নিজেদের ভুল বুঝিয়ে দেব।\nমাঝে মাঝে, যখন দুঃস্বপ্নের বাহন মেঘ ভেদ করে যায় এবং চাঁদ দেখা যায়, তখন সত্যিই কিছু হাস্যকর চিন্তা আমার মনে ঝলকে ওঠে।\nযেমন এই সময়গুলো কখন হঠাৎ, অপ্রতিরোধ্যভাবে থেমে যেতে বাধ্য হবে — ঠিক যেমন জীবন একসময় কোনো পূর্বসংকেত ছাড়াই ধসে পড়েছিল।\nতবে এরপরই আমি নিজেই নিজের কথায় হেসে ফেলি। যেদিন আমি এই পথে পা দিয়েছিলাম, সেদিন থেকেই আমি এমন এক যাত্রায় আছি যেখানে ফেরার পথ নেই। আমি নিশ্চিত তুমি আমার কথার মানে বুঝতে পারছ, ছোট বন্ধু। এই পৃথিবীতে তোমার আর আমার চেয়ে একই পরিস্থিতিতে আর কেউ নেই।\nআমরা দুজনেই এমন কিছু বেছে নিয়েছি যেখানে আসলে কোনো বিকল্প ছিল না। সুখবর হলো, আমরা দুজনেই আমাদের নিজের পছন্দ উপভোগ করি।\nনতুন বছরে, যতক্ষণ তুমি আমার দেওয়া শিকারের বাঁশিটি বাজাবে, আমি তখনই তোমার পাশে হাজির হব।\nঅবশ্যই, যদি কোনো অঘটন না ঘটে, তাহলে আপাতত আমাকে এই যাত্রাটা মনোযোগ দিয়ে উপভোগ করতে দাও। আগামী মাসে, আমি তোমার জন্য স্মারক এবং কিছু নতুন অভিজ্ঞতার গল্প নিয়ে আসব।\nতোমার সব কিছু ভালো যাক, তুমি সুখী থাকো।\n\nতোমার প্রিয় 「মামা」"
  },
