  Mail_146401_Desc = {
    Text = "পঞ্জিকা একটি বিরক্তিকর আবিষ্কার। সব দিনই একরকম, আজকের দিনটিও তার ব্যতিক্রম নয়।\nতোমাদের পঞ্জিকা অনুযায়ী, আজ আমার জন্মের দিন। জন্ম শব্দটি আমার জন্য সঠিক নয়। আমি কেওস থেকে ছিঁড়ে বের করা একটি ধ্বংসাবশেষ, অসংখ্য যুদ্ধে শাণিত একটি তরবারির ফলা। আমাকে গড়েছে কোনো মাতৃগর্ভ নয়, বরং প্রতিটি প্রতিদ্বন্দ্বী যারা কখনো আমার মুখোমুখি হয়েছে। আর তুমি, তাদের মধ্যে সবচেয়ে গুরুত্বপূর্ণ একজন।\nতোমরা এই দিনটিকে অনেক গুরুত্ব দাও। ভোজ, উপহার, শুভেচ্ছাবাণী—— আমার এসবের প্রয়োজন নেই।\nআমার শুধু একটি যুদ্ধ চাই।\nএই সময়ের মধ্যে, তুমি অনেক অবিশ্বাস্য কাজ করেছ। কিন্তু আমি জানি, তুমি যা দেখিয়েছ তা তোমার সীমার ধারেকাছেও নয়।\nআজ সন্ধ্যায়, প্রশিক্ষণ মাঠে। তোমার অস্ত্র নিয়ে এসো, আমি সেখানে অপেক্ষা করব। জয়-পরাজয়ের চিন্তা করো না, ক্ষয়ক্ষতির পরোয়া করো না। তরবারির ফলা কোনো কিছু ধরে না রেখে যে মুহূর্তে সংঘর্ষ করে, সেটাই আমার একমাত্র প্রত্যাশিত উপহার। আমাকে দেখাও, @4-এর একটি টুকরো আসলে কতটুকু করতে পারে।\nআমার মনে হয়, তুমি আমাকে অবাক করবে, আমার「প্রতিদ্বন্দ্বী」।"
  },
