  Mail_146873_Desc = {
    Text = "সম্মানিত গোপনরক্ষক:\n「অস্থায়ী টেক্সট」ইভেন্ট শেষ হয়েছে। গোপনরক্ষকের অবশিষ্ট「অস্থায়ী টেক্সট」,「অস্থায়ী টেক্সট」,「অস্থায়ী টেক্সট」প্রতিটি「রোজ গোল্ড ভাউচার」× 40 অনুপাতে রূপান্তর করা হয়েছে। অনুগ্রহ করে গোপনরক্ষক গ্রহণ করতে ভুলবেন না।"
