  Mail_147798_Desc = {
    Text = "সম্মানিত রক্ষক：\n        Ⅴ2.6.0 আপডেটে, আমরা বিস্মৃতি অধ্যায় অভিযান H7-6-এর লুকানো পুরস্কার অনুপস্থিতির সমস্যাটি সমাধান করেছি। যেহেতু আপনি সমাধানের আগেই H7-6 ক্লিয়ার করেছিলেন, তাই আমরা সরাসরি আপনাকে অনুপস্থিত লুকানো পুরস্কার পুনরায় প্রেরণ করছি। অনুগ্রহ করে গ্রহণ করুন।"
