    Text = "সম্মানিত রক্ষক：\n        Ⅴ1.4.3.5 সংস্করণ আপডেটে, আমরা「স্বপ্নদৃশ্য：অপবিত্রকরণ」-এ「নতুন রাজা」স্তরটি যুক্ত করেছিলাম। কিছু রক্ষক সময়মতো এই আপডেটের বিষয়বস্তু জানতে না পারায়, ভুলবশত মনে করেছিলেন যে「স্বপ্নদৃশ্য：অপবিত্রকরণ」সম্পূর্ণরূপে ক্লিয়ার হয়ে গেছে।\n        এই কারণে, এই Ⅴ2.6.2 সংস্করণ আপডেটে, আমরা আপডেটের আগে「নতুন রাজা」-এর পরবর্তী স্তরগুলো ক্লিয়ার করা রক্ষকদের জন্য「নতুন রাজা」স্তরের ক্লিয়ার অগ্রগতি পূরণ করেছি এবং সংশ্লিষ্ট প্রথম ক্লিয়ার পুরস্কারও একসাথে পাঠানো হয়েছে, অনুগ্রহ করে গ্রহণ করুন।"
  },
  Mail_148514_Name = {
    Text = "「অপবিত্রকরণ」অগ্রগতি পূরণ"
