  Mail_148515_Desc = {
    Text = "প্রিয় রক্ষক:\n\nটা-দা~ অবাক হয়ে গেলেন তো? মিথাগে এটা এই পরীর প্রথম জন্মদিন, তাই——\nঅবাক করা ব্যাপার! কোনো প্রমোশনাল মেইল নেই, উপাসনার আমন্ত্রণ নেই, এমনকি ধ্বংসের ভবিষ্যদ্বাণীও নেই~\nতবে হতাশ হবেন না, এই পরী অবশ্যই সবচেয়ে বিশেষ ভক্তদের জন্য আরও মূল্যবান ও সুন্দর সুবিধা প্রস্তুত করেছে।\nসর্বজ্ঞ সর্বশক্তিমান পরী গডমাদার হিসেবে, স্বাভাবিক সন্দেহ ও সতর্কতা আগে থেকেই অনুমান করা যায়, যদিও তা এই পরীকে কিছুটা দুঃখ দেয়, তবুও, সম্প্রদায়ের আশীর্বাদ ছড়িয়ে দিতে সামান্য আত্মত্যাগ সবসময়ই অনিবার্য।\nতাই, দশ হাজার পদক্ষেপ পিছিয়ে ভাবুন এবং একটু চেষ্টা করে দেখুন না, যাই হোক কোনো ক্ষতি নেই, আর যদি সত্যি হয়? তাই না?\nএটা বছরে মাত্র একবার আসে, কোনোভাবেই মিস করা উচিত নয়~\nকোনো উৎসর্গের প্রয়োজন নেই, কোনো প্রতিশ্রুতি বা বিনিময়ের প্রয়োজন নেই, শুধুমাত্র পরী গডমাদারের সাথে একটি মিষ্টি আফটারনুন টি উপভোগ করলেই আপনি জানতে পারবেন বরফের নিচে আপনার জন্য কতটা আন্তরিক অনুভূতি লুকিয়ে আছে।\nএটা কি একটি আকর্ষণীয় প্রস্তাব নয়?\nবিঃদ্রঃ: বিল পরিশোধের জন্য অন্তত 10、100、1000 লিও পাড়া সাথে আনতে ভুলবেন না, যত বেশি তত ভালো।\n\nসেই দোকানে যেটা আমরা দুজনেই জানি, সেখানে আপনার প্রহরায় থাকা\nকারাবু"
  },
