  Mail_149949_Desc = {
    Text = "এই চিঠি ইতিমধ্যে দুই জগতে হাজার বার আবর্তিত হয়েছে, কখনো মুছবে না!\n\nসপ্তম মাসের মাঝামাঝি, নরকের দরজা খোলে, অশুভ বায়ু বয়, ভূতেরা ফিরে আসে।\nআমি পানলং প্রাচীন রাজ্যের হু শহরের ■■■, একটি তুচ্ছ কাগজের পত্রই বটে!\nমধ্য-শরতের আদেশ মেনে, আত্মা-আহ্বানের তাবিজ হাতে নিয়ে, আজ রাতে এখানে অভিশাপ নামিয়ে আনছি। যে এই অক্ষর দেখবে, তার আত্মা তালিকায় উঠবে, নাম খাতায় লেখা হবে। যদি মধ্যরাতের আগে পঞ্চাশজন জীবিত মানুষের কাছে না পাঠাও, তাহলে——\nনথি সংরক্ষণের এক মুহূর্ত আগে ধ্বংস হয়ে যাবে……\nবাবল টি-তে সবসময় তিনটি পার্ল কম থাকবে……\nসিলভার যোগাযোগ যন্ত্রের চার্জ চিরকাল ১%-এ আটকে থাকবে, চার্জ করলেও বাড়বে না……\n\nশান্তভাবে মেনে চললে, অভিশাপ নিজেই কাটবে, তাবিজ নিজেই পুড়বে, অশুভ আত্মা তোমাকে ছাড়বে, আলোও চিরকাল জ্বলবে।\nফরওয়ার্ড করো!! এখনই!!!"
  },
  Mail_149949_Name = {
    Text = "[মধ্য-শরতের সতর্কবার্তা】 যে সাহস করে এই চিঠি মুছবে, তার উপর নেমে আসবে……"
