  Mail_149985_Desc = {
    Text = "প্রভু:\n\nহঠাৎ চিঠি লিখছি, আশা করি আপনি বিব্রত বোধ করবেন না। কিন্তু কিছু মনের কথা আছে, যা শুধু আপনাকেই বলতে পারি।\nগতকাল রাতে, অনেকদিন পর একটি স্বপ্ন দেখলাম। স্বপ্নে আমি পুরনো বাড়িতে ফিরে গিয়েছিলাম। সবকিছু এত পরিচিত মনে হচ্ছিল — বাবার কোমল ও উদার হাতের স্পর্শ, ঝাড়ু দেওয়ার সময় পরিচারিকার গুনগুন করা গ্রামীণ সুর, আর সেই সাদা খাটো ঘোড়াটা যেটা ছিল আমার নিজের...... আমি ভেবেছিলাম এসব স্মৃতির কাদায় হারিয়ে গেছে, কিন্তু স্বপ্নে আবার দেখে মনে হলো সেই উষ্ণতা এখনো একইরকম।\nঘুম থেকে উঠে জানালার বাইরে দেখলাম মিথাগের শিক্ষক-শিক্ষার্থীরা গল্প করতে করতে হেঁটে যাচ্ছে, এত শান্ত ও সুন্দর দৃশ্য — মুহূর্তের জন্য মনে হলো এই দৃশ্যটা স্বপ্নের থেকে আলাদা কিছু নয়। একই সাথে লক্ষ্য করলাম, আমার উপর যে অদৃশ্য বস্তুটি আছে, সেটি আজ সকাল থেকে খুব শান্ত। তাহলে কি সত্যিই জন্মদিনে ভাগ্যের কিছু ঘটে?\nযদি সত্যিই তাই হয়, তাহলে হয়তো আজকের দিনে আমিও একটু লোভী হতে পারি......\nআমি জানি মানুষ সাধারণত জন্মদিনে ইচ্ছা করে, সারা বছরের প্রত্যাশা হিসেবে। আমি আর কারো কাছ থেকে জন্মদিনের শুভেচ্ছা পাওয়ার স্বপ্ন দেখার সাহস করি না, কিন্তু সত্যিই একটি সুযোগ পেতে চাই।\nযেমন আপনি আমার উপর বিশ্বাস রেখেছেন, আমিও আপনার কাছে কিছু ধরে রাখো না, তাই অনুমতি দিন আমার ইচ্ছাটি আপনাকে জানাই:\nপরের বার যদি প্রভুর কোনো কাজের পরিকল্পনা থাকে, তাহলে আমাকে প্রহরী হিসেবে নিযুক্ত করুন, আপনার সাথে যেতে দিন।\nযাই হোক, আমি চাই আপনার সবচেয়ে বেশি সাহায্যের প্রয়োজনের মুহূর্তে, সবসময় সবার আগে আপনার সামনে দাঁড়াতে পারি, আপনার সবচেয়ে মজবুত শিল্ড হয়ে উঠতে পারি।\nএটাই এই বছরের জন্য আমার মনের ইচ্ছা।\n\nওজিয়ার"
  },
