    Text = "প্রিয় গোপনীয়তার রক্ষক:\nসিস্টেম শনাক্ত করেছে যে বর্তমান অ্যাকাউন্ট থেকে একটি রিফান্ড করা হয়েছে। নির্মাণ দল {s1} তারিখে আপনার রিফান্ড অর্ডারের সাথে সম্পর্কিত ভার্চুয়াল মুদ্রার অংশ কেটে নিয়েছে। যদি সংশ্লিষ্ট মুদ্রা কাটার পরে ঋণাত্মক হয়ে যায়, তাহলে স্বাভাবিকভাবে ব্যবহার করতে হলে তা ধনাত্মক সংখ্যায় পুনরুদ্ধার করতে হবে।\nকোনো প্রশ্ন থাকলে অনুগ্রহ করে গ্রাহক সেবায় যোগাযোগ করুন।"
