  Mail_18034_Desc = {
    Text = "হ্যালো, রক্ষক, ফ্যান্টাসমাল ডাইভ থেকে আপনার কিছু সঞ্চিত পয়েন্ট পুরস্কার এখনো অব্যবহৃত রয়েছে। এই পুরস্কারগুলো এখন আপনাকে মেইল সংযুক্তি হিসেবে পাঠানো হচ্ছে।"
  },
  Mail_18034_Name = {
    Text = "মায়াবী অবগাহনের অদাবিকৃত ক্রমপুঞ্জিত পুরস্কার"
  },
  Mail_18034_Sender = {
    Text = "মিথাগ বিশ্ববিদ্যালয় কমিটি"
  },
  Mail_18035_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nসামনের পথ দীর্ঘ এবং কণ্টকাকীর্ণ, এই কঠিন সময়ে আমাদের একে অপরের সাথে সহযোগিতা করে এগিয়ে যাওয়া আরও বেশি প্রয়োজন।\nচিঠির সাথে আজকের বিশেষ অনুমোদিত স্পিরিট কফি পেপটাইড সরবরাহ সংযুক্ত করা হলো, দয়া করে গ্রহণ করুন।\nরৌপ্য চাবি আপনার পথ প্রদর্শন করুক।\nঅতিরিক্ত: আপনার বিশেষ অনুমোদিত সরবরাহ আর {s1} দিন বাকি আছে, অনুগ্রহ করে তদন্তের সময় যথাযথভাবে পরিকল্পনা করুন।\n\nমিসাগার্ড স্কুল কমিটি রসদ বিভাগ"
  },
  Mail_18035_Name = {
    Text = "খাপের মধ্যে সরবরাহ বিতরণ"
  },
  Mail_18035_Sender = {
    Text = "মিথাগ বিশ্ববিদ্যালয় কমিটি"
  },
  Mail_20231_Desc = {
    Text = "প্রিয় সিক্রেটকিপার, ফেজ চেসের নতুন সিজন শুরু হয়েছে, আপনার র‍্যাঙ্ক {s1} থেকে {s2}-এ রিসেট করা হয়েছে। নতুন সিজনের র‍্যাঙ্ক পুরস্কার রিসেট করা হয়েছে, র‍্যাঙ্ক উন্নত করে আরও সম্মান ও পুরস্কার অর্জন করুন!{s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "ট্র্যাফেজ সিজন মেইল"
  },
  Mail_20231_Sender = {
    Text = "মিথাগ বিশ্ববিদ্যালয় কমিটি"
  },
  Mail_21453_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nহঠাৎ বিরক্ত করার জন্য ক্ষমা চাইছি, আশা করি আপনি ভালো আছেন?\nআপনার ব্যস্ততার মাঝে বিরক্ত করার জন্য দুঃখিত। জেনকিন এবং অন্যরা আমার জন্য একটি ছোট জন্মদিনের অনুষ্ঠানের আয়োজন করেছে। আমি অনেকক্ষণ ভেবেছি, তারপরও সিদ্ধান্ত নিলাম যে এই আমন্ত্রণপত্রটি আমি নিজেই আপনাকে পাঠাব।\nকর্মশালায় আশ্রিত বেশিরভাগ এতিম তাদের জন্মতারিখ মনে রাখতে পারে না, তাই মিস সারা আমাদের এতিমখানায় আসার দিনটিকেই আমাদের জন্মদিন হিসেবে নির্ধারণ করেছেন। শুধু আমিই আলাদা — মিস সারা বলেছেন, আমাকে এক ভয়ংকর ঠান্ডা শীতের রাতে দরিদ্রাশ্রমের দরজায় ফেলে রাখা হয়েছিল। তিনি চেয়েছিলেন আমার জীবন যেন আর কখনো এত শীতল ও বিবর্ণ না হয়, তাই তিনি একটি উষ্ণ দিনকে আমার জন্মদিন হিসেবে বেছে নিয়েছেন। তাই, এটি আমার এমন একটি দিন — যেদিন আমি যত্ন ও ভালোবাসায় ঘেরা। এই দিনটি আমার কাছে অত্যন্ত গুরুত্বপূর্ণ, এবং আমি চাই গোপনরক্ষকও আমার সাথে এই দিনটি কাটান — এটি আমার একটি ছোট্ট ইচ্ছা। অবশ্যই, যদি এটি পূরণ না হয় তাহলেও কোনো সমস্যা নেই, কারণ গোপনরক্ষকের অনেক কাজ সামলাতে হয়, এটা অ্যাগনেস জানে।\nযদি এই আমন্ত্রণ আপনার কোনো অসুবিধা করে থাকে, তাহলে অবশ্যই আমাকে জানাবেন এবং আমার আন্তরিক ক্ষমা গ্রহণ করবেন। কিন্তু যদি, হয়তো, আপনি সত্যিই একটু সময় বের করতে পারেন, তাহলে তাদের এই হৈচৈতে যোগ দিতে আপনাকে সাদর স্বাগত জানাই। হয়তো... এটা সত্যিই অনেক মজার হতে পারে, কারণ জেনকিনই তো সব আয়োজন করেছে!\n\nঅ্যাগনেস"
  },
  Mail_21453_Name = {
    Text = "বিরক্ত করার জন্য দুঃখিত..."
  },
  Mail_21453_Sender = {
    Text = "আইগিস"
  },
  Mail_21454_Desc = {
    Text = "এই:\nআমি কখনোই বুঝতে পারিনি, জন্মদিনে উদযাপন করার মতো কী আছে? সবাই এত হইচই করার কী আছে?\nগত বছর আজকের দিনে, একজন ছাত্রী আমার জন্মদিনের তারিখ জানতে এসেছিল। হাসিই পায়, আমার জন্মের সময় এই গ্রহে সময়ের ধারণাই ছিল না, জন্মদিন তো দূরের কথা। কিন্তু সে এত পীড়াপীড়ি করল যে উপায় না পেয়ে আমি বললাম 「দিন ও রাত যখন সমান হয়ে মিলিত হয়」, শেষ পর্যন্ত সে কীভাবে বুঝেছে কে জানে।\nএই চিঠি লেখার কারণ হলো তোমাকে মনে করিয়ে দেওয়া, আজ রাত ১২টার পর আমার ঘরের দরজার সামনের ফুলগুলো সরিয়ে রাখতে ভুলো না, গন্ধে দম বন্ধ হয়ে যাচ্ছে!\n\nলোতান"
  },
  Mail_21454_Name = {
    Text = "ওই ফুলগুলো..."
  },
  Mail_21454_Sender = {
    Text = "লোতান"
  },
  Mail_21455_Desc = {
    Text = "এরিকা আজ একটা বড় প্যাকেট কফি পাঠিয়েছে, বলেছে এটা আমার জন্মদিনের উপহার, আর বলেছে এর মধ্যে তোমার এই বছরের পুরো বরাদ্দ আছে।<Del:কিন্তু তুমি কি স্বেচ্ছায় দিয়েছ? যদি না>\n যদি এটা ডোর বা অন্য কেউ তোমার সাথে করা কোনো দুষ্টুমি হয়, তাহলে যদিও খুব কষ্ট হবে, আমি এটা... তোমাকে ফেরত দিতে পারি। কারণ ওটা তো কফি! আমি দুই কাপ কম খেলেই ঘুমে ঢুলতে থাকি, পুরো এক বছর না খেলে? তুমি বোধহয় তুরুর মতো ঘুমিয়ে পড়বে। এমন না যে সে খারাপ, শুধু, কালো জিনিস রাতের বেলা দেখা দেয়... যাই হোক, যদি তোমার দরকার হয়, যেকোনো সময় কফি ফেরত নিতে পারো, অবশ্য যদি তুমি কফিটা এখানে রেখে দাও, <Del:আমিও তা তাহলে>আমার মনে হয় আমি খুবই খুশি হব। তাহলে আমি অবশেষে সেই পরীক্ষাটা করতে পারব যেটা আমি করতে চেয়েছিলাম: ক্যাফেইন নিষ্কাশন করে ত্বকের মাধ্যমে শোষণযোগ্য ঘনীভূত ওষুধে পরিণত করা, শরীরে লাগিয়ে রাখলে সবসময় জেগে থাকা যাবে, সবসময় সবসময়...\n\n\nএই পরীক্ষাটা করতে খুবই আগ্রহী ভিনকেল"
  },
  Mail_21455_Name = {
    Text = "কফি..."
  },
  Mail_21455_Sender = {
    Text = "উইঙ্কল"
  },
  Mail_21456_Desc = {
    Text = "জন্মদিন?\nসত্যি বলতে, আমার জন্মদিন কোনো শুভ দিন নয়। শত শত নিরপরাধ প্রাণ এই দিনে ঝরে গেছে, শুধু আমাকে 「জন্ম」 দেওয়ার জন্য, যাতে আমি আরও বেশি মানুষকে হত্যা করতে পারি।\nতাই, এই দিনটা উদযাপন করার মতো কিছু নেই। তবে আমি বুঝি তোমরা মানুষেরা 「আনুষ্ঠানিকতা」 নিয়ে বেশ সচেতন প্রাণী। ঘটনাক্রমে আমার হাতে কিছু টাকা আছে — চিন্তা করো না, এটা ট্রাউট ক্লাবে ঘাম ঝরিয়ে কষ্ট করে উপার্জন করা টাকা, কোনো অবৈধ আয় নয়।\nএই টাকাটা নিয়ে নাও, নিজের জন্য একটা উপহার কিনো, আমার জন্মদিন উদযাপন হিসেবে ধরে নিও।\n\nইউউহাশি"
  },
  Mail_21456_Name = {
    Text = "জন্মদিন..."
  },
  Mail_21456_Sender = {
    Text = "উভহাশ"
  },
  Mail_21457_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nমিসাগার্ড অঞ্চলে কি জন্মদিন উদযাপনের কোনো প্রথা আছে?\nআমার স্মৃতিতে থাকা সেই মাতৃভূমিতে... প্রতি বছর রাজার জন্মদিন উদযাপনে এক জাঁকজমকপূর্ণ অনুষ্ঠান আয়োজন করা হতো।\nকালক্রমে, 「জন্মদিন」-এর এই বিশেষ তাৎপর্য সকলের জন্যই প্রযোজ্য হয়ে উঠেছিল।\nসুদূর অতীতে, প্রতিটি জন্মদিনে সহকর্মী ও প্রিয়জনেরা হাজার মাইল পথ পাড়ি দিয়ে আমার কাছে আসতেন।\nপ্রিয় মানুষদের দ্বারা ঘিরে থাকার সেই অনুভূতি... সূর্যের আলিঙ্গনের মতো সেই উষ্ণতা... সম্ভবত এই কারণেই আমি অতীতকে ছেড়ে দিতে পারি না।\nআহ... বিষয়ান্তরে চলে গেলাম, আমি কি আপনার কাজে ব্যাঘাত ঘটাচ্ছি?\nআমি অতীতে প্রায়ই ব্যবহৃত কিছু চা-নাস্তা প্রস্তুত করেছি, আপনার সাথে ভাগ করে নিতে চাই।\nযদি আপনি সম্মান করেন, তাহলে অনুগ্রহ করে রাতের খাবারের পর আমার কাছে আসুন।\n\nফারোস"
  },
  Mail_21457_Name = {
    Text = "অনির্বাণ আলো..."
  },
  Mail_21457_Sender = {
    Text = "ফারোস"
  },
  Mail_21458_Desc = {
    Text = "আজ সত্যিই একটি স্মরণীয় দিন: এই দিনে, মহান গোলিয়াথের প্রভু, দৈত্যদের রাজা পৃথিবীতে আবির্ভূত হয়েছিলেন; এই দিনে, সমুদ্র কেঁপে উঠেছিল, তারারা ম্লান হয়ে গিয়েছিল।\nশুনেছি ক্যাম্পাসে বিলাসিতা করা নিষিদ্ধ, তাহলে আমার জন্মদিনের ভোজ আগের মানের দশ ভাগের এক ভাগে আয়োজন করো—দশটি দুধের শূকর রোস্ট, একশো শিকে ঝলসানো অক্টোপাস এবং গোলিয়াথের লোকগান বাজাতে পারে এমন একটি ব্যান্ড, আর হ্যাঁ, নর্তকীও এক ডজন দিও……\nকী, এসব কিছুই অনুমতি নেই?\nতাহলে শুধু নর্তকী দাও……এক ডজন লাগবে না, চার-পাঁচজন হলেই চলবে।\nকী, এটাও অনুমতি নেই?!\nএত নিম্নমানের আয়োজন আমার মর্যাদার সাথে মানায় না। এখন আমি ঘোষণা করছি, ভোজের পরিকল্পনা বাতিল!\n\nগোলিয়াথ"
  },
  Mail_21458_Name = {
    Text = "নৈশভোজের আয়োজন..."
  },
  Mail_21458_Sender = {
    Text = "গোলিয়াথ"
  },
  Mail_21459_Desc = {
    Text = "গোপনরক্ষক——\n\nআজ সিলভিয়া ম্যাডামের কাছে স্মৃতি প্রশিক্ষণ করার সময়, উনি আমার জন্মদিনের কথা জিজ্ঞেস করলেন। তুমিও তো আমাকে চেনো, এইমাত্র রেখে দেওয়া রেঞ্চের কথাও ঘুরে দাঁড়াতেই ভুলে যাই, জন্মদিন মনে থাকবে কীভাবে! আরও ভয়ংকর ব্যাপার হলো, এটা এমন একটা জিনিস যা শুধু আমিই জানতাম, আমি! এই জন্মদিনটা আর রইল না।\n\nতবে ফাদার সালভাদো বলেছেন নির্দিষ্ট তারিখটা গুরুত্বপূর্ণ নয়, গুরুত্বপূর্ণ হলো আমি প্রতিটা দিন উদযাপন করি কিনা সেটা, তাই আমি ঠিক করে ফেললাম, আজকেই আমার জন্মদিন! আমি ইতিমধ্যে একজনের সাথে (কে সেটা ভুলে গেছি, তুমি তো নও, তাই না গোপনরক্ষক?) কথা পাকা করে ফেলেছি ক্যান্টিনের সামনে পার্টি করার জন্য, তুমি অবশ্যই আসবে কিন্তু!\n\n\n\nএই জন্মদিনের তারিখ একদম একশোভাগ মনে রাখবে এমন নোতিলা\n\n\n\nচিঠির সাথে পাঠানো একটি নোট:\n\nমেয়েটা চিঠি লিখেই ঝড়ের বেগে চলে গেল, চিঠি আর তোমাকে দেওয়ার জন্য বলা কিছু উপহার টেবিলের উপরেই ফেলে রেখে গেছে।\nসব কিছু খামের মধ্যে ভরে দিলাম, আজ রাতে পার্টিতে তোমার সাথে দেখা হবে বলে অপেক্ষায় আছি। চিন্তা করো না, আমি ওকে আজ রাতে আসার কথা মনে করিয়ে দেব।\n\n——সিলভিয়া"
  },
  Mail_21459_Name = {
    Text = "আমার বেছে নেওয়া জন্মদিন!"
  },
  Mail_21459_Sender = {
    Text = "নটিলা"
  },
  Mail_21460_Desc = {
    Text = "ছোট্ট বন্ধু: \n\nমৌলিক সারসাগরে কোনো তারা, সূর্য বা চাঁদ নেই, ঋতুর পরিবর্তনও নেই, তাই আমার জন্মদিন 【অজ্ঞাত】 হিসেবে নথিভুক্ত হওয়া উচিত।\nতবে আজকের দিনটি সত্যিই একটি গুরুত্বপূর্ণ দিন, কারণ এই রূপটি এমন একজন মানুষের কাছ থেকে উত্তরাধিকারসূত্রে পাওয়া যার একটি 「ইচ্ছা」 ছিল। সে উৎসব-আনন্দ পছন্দ করত, তাই এই ছোট্ট দোকানটি খুলেছিল, কিন্তু সর্বত্র তদন্তে ব্যস্ত থাকায় তার জন্মদিনে প্রায়ই শুধু আমিই তার সঙ্গী ছিলাম। তার জীবদ্দশার ইচ্ছা পূরণ করতে, চিন্তামুক্তি দোকান আজ একটি মোমবাতি-আলোকিত নৈশভোজের আয়োজন করবে, এবং সকল বিশ্বস্ত গ্রাহকদের আন্তরিকভাবে আমন্ত্রণ জানানো হচ্ছে।\nঅবশ্যই, চিন্তামুক্তি দোকান সকল আগন্তুকদের জন্য একটি ছোট্ট ছাড়ও প্রদান করবে, তাই ছোট্ট বন্ধু, এই সুযোগ মিস করো না।\n\nড্যাফোডেল"
  },
  Mail_21460_Name = {
    Text = "পার্থিব কামনা..."
