  Mail_21461_Desc = {
    Text = "সেই সময় যখন আমাকে পরিবার থেকে ছিনিয়ে নেওয়া হয়েছিল, পালক মা… আর্কনের স্ত্রী আমার জন্মতারিখ লেখা মৃৎফলকটি চূর্ণবিচূর্ণ করে ফেলেছিলেন, আমার তিলোসবাসী হিসেবে অতীতকে চূর্ণবিচূর্ণ করে দিয়েছিলেন। আমার আসল জন্মদিন, স্বাভাবিকভাবেই আর জানার উপায় নেই।\nলাই থেকে বিদায় নেওয়ার পর, আমিও অনেক ভেবেছি… যে রাতে আমি খাঁচা থেকে পালিয়ে প্রতিশোধের পথে পা বাড়িয়েছিলাম, সেই রাতকে যদি আমার 'জন্মদিন' হিসেবে ধরি, তোমার কী মনে হয়?\nযদিও এখন আর এক বছর বেশি বয়স হওয়া উদযাপনের প্রয়োজন নেই, তবে সময়ের পরিবর্তনের একটি স্মারক হিসেবে, মন্দ হয় না বলেই মনে হয়।"
  },
  Mail_21461_Name = {
    Text = "আবির্ভাবের দিন"
  },
  Mail_21461_Sender = {
    Text = "হেলট"
  },
  Mail_21462_Desc = {
    Text = "পরীক্ষা, পরীক্ষা।\nসম্মানিত গোপনীয়তার রক্ষক, আপনাকে শুভেচ্ছা। আপনি যদি এই চিঠিটি পেয়ে থাকেন, তাহলে এর অর্থ হলো আপনার মতামত এরিকার কাছে অত্যন্ত গুরুত্বপূর্ণ এবং আপনাকে স্বয়ংক্রিয় পুতুল এরিকার ভাষা মডিউল কার্যকারিতার বার্ষিক পরীক্ষা ও রক্ষণাবেক্ষণ পরিকল্পনায় অংশগ্রহণের জন্য নির্বাচিত করা হয়েছে। এই মূল্যায়নটি সংক্ষিপ্ত উত্তরের প্রশ্নের আকারে পরিচালিত হবে, যেখানে আপনাকে স্বয়ংক্রিয় পুতুল এরিকার সর্বশেষ ইনস্টল করা EA-L-1033 নম্বর ভাষা মডিউলের কার্যকারিতা মূল্যায়ন করতে হবে। এটি আপনার বেশি সময় নেবে না, তাই অনুগ্রহ করে উদ্বিগ্ন বা আতঙ্কিত হবেন না।\nসংক্ষিপ্ত উত্তরের প্রশ্ন：\nআপনি কি এই চিঠির মূল বিষয়বস্তু বুঝতে পেরেছেন？\n\nঅনুগ্রহ করে আপনার উত্তর সরাসরি সংক্ষিপ্ত উত্তরের প্রশ্নের নিচের ফাঁকা জায়গায় লিখুন এবং চিঠিটি আবার খামে ভরে রাখুন।\nআপনার অংশগ্রহণের জন্য ধন্যবাদ।\n\nএরিকা"
  },
  Mail_21462_Name = {
    Text = "পরীক্ষা চলছে, পরীক্ষা চলছে..."
