  Mail_21463_Desc = {
    Text = "গোপনীয়তার রক্ষক：\n\nতুমি এই স্কুলে বিরল জাগ্রত মানুষদের একজন, তোমার দৃষ্টি এই অসম্পূর্ণ দেহ ভেদ করে প্রকৃত আমাকে দেখতে পায়।\nতোমার মতো কেউ নিশ্চয়ই সেই বাচ্চাদের বোঝাতে পারবে: আমি কোনো মৎস্যকন্যা নই, এই দেহ শেষপর্যন্ত সাগর পেরিয়ে পর্বত ডিঙিয়ে পরিপূর্ণ রূপ ধারণ করবে।\n……যাক, তোমাকে আর বিব্রত করব না। কিন্তু অন্তত আজকের দিনটায়, ওদের আমার লেজ নিয়ে খেলতে দিও না।\nআজকের দিনটা বিশেষ বলা যায়। যদি তোমার সময় থাকে, কিছু কথা আছে যা আমি নিজের মুখে তোমাকে বলতে চাই।\n\nকেকেস"
  },
  Mail_21463_Name = {
    Text = "নিখুঁত দেহ..."
