  },
  Mail_21464_Desc = {
    Text = "গোপনীয়তার রক্ষক：\n\nপার্থিব অর্থে আমার জন্মদিন হলো সেই দিন যেদিন বাবা আমাকে দত্তক নিয়েছিলেন।\nআগে তিনি এই দিনটিকে অত্যন্ত গুরুত্ব দিতেন, প্রতি বছর জমকালো নাচের আয়োজন করতেন——কোমরবন্ধ পরে নাচা তিন হাজার বার তলোয়ার চালানোর চেয়েও ক্লান্তিকর।\nকিন্তু এটা বাবা হিসেবে তাঁর হৃদয়ের ভালোবাসা, আমি এই দুর্লভ স্নেহকে বৃথা যেতে দিতে চাই না।\nতবে এ বছর, তিনি অবশেষে আমাকে নিজের জন্মদিনের পরিকল্পনা নিজে করতে রাজি হয়েছেন। হয়তো বাবার চোখে আমি আর চোখের সামনে রেখে দেখভাল করার মতো ছোট শিশু নেই।\nআচ্ছা, তুমি কি আমার সাথে ঘণ্টাঘরের চূড়ায় যাবে? একটু গল্প করব, একটু হাওয়া খাব।\nশুনেছি, আজ রাতে পূর্ণিমা হবে।\n\nরামোনা"
  },
  Mail_21464_Name = {
