  Mail_21465_Desc = {
    Text = "প্রিয়, সবচেয়ে প্রিয় মালিক:\nহ্যাঁ ঠিকই ধরেছেন, আজ কারেনের @1তম জন্মদিন(একজন মহিলার বয়স গোপন রাখতে হয়)!\nএই উপলক্ষে কারেন একটি অতুলনীয় জমকালো পার্টির আয়োজন করেছে, আর যাদের আমন্ত্রণ জানানো সম্ভব সবাইকে আমন্ত্রণ জানিয়েছে~! যদিও শেষ পর্যন্ত শুধু অরিটা, অগিয়ের আর লিলি আসতে রাজি হয়েছে……\nতবে কোনো সমস্যা নেই, যেখানে মানুষ আছে সেখানে পার্টি আছে, আর যেখানে পার্টি আছে সেখানে কারেন আছে! কারেন এর জন্য যত্ন করে তৈরি করেছে 「উন্নত সংস্করণ」 টোড স্টু, রসুন-গন্ধী পিট স্লাগ এবং কারি বাদুড়ের স্যুপ, মালিককে অবশ্যই এসে চেখে দেখতে হবে~\n\nচুপিচুপি একটা কথা জিজ্ঞেস করি, মালিক নিশ্চয়ই কারেনের জন্য উপহার তৈরি রেখেছেন তো? মনে রাখবেন ঝকঝকে চকচকে হতে হবে কিন্তু!\n\nআপনার চিরকালের বিনীত দাসী\nকারেন"
  },
