  Mail_21466_Desc = {
    Text = "প্রিয় <Del:গোপনরক্ষক> ওয়েস্ট সাইডের বন্ধু:\nএটা একটা <Del:আমন্ত্রন পত্র আমন্ত্রণ পএত্র আমন্ত্রণ পত্র আমন্ত্রণ> মোটকথা, তোমাকে বিনামূল্যে কেক খেতে আসার জন্য আমন্ত্রণ জানাচ্ছি, আর সেই সাথে আমার জন্মদিনও উদযাপন করব! আসলে এটা তোমাকে ধন্যবাদ জানানোর জন্যও, কারণ তুমি আগে আমার দিদিকে খুঁজে পেতে সাহায্য করেছিলে, আর আমাকে এখানে নিয়ে এসেছিলে, আমাকে আর ব্রাউনকে নিরাপদে থাকার একটা জায়গা দিয়েছিলে।\n(উপরের কথাগুলো অ্যাগনেস আমাকে লিখতে বলেছে, বড্ড আবেগঘন! আমাদের বন্ধুত্বে এসবের দরকার নেই, তাই না, গোপনরক্ষক?)\nযাই হোক, আজ রাতে তোমার ছাত্রাবাসের পেছনের উঠোনে, আমি, ব্রাউন আর অ্যাগনেস মিলে নিজেদের হাতে কিছু দারুণ জিনিস তৈরি করেছি, তোমার সাথে ভাগ করে খাওয়ার জন্য অপেক্ষা করছি! অবশ্য বেশিরভাগটাই অ্যাগনেস বানিয়েছে, ওর রান্না খুবই সুস্বাদু, রান্নাঘরের মাসিরাও বলেন ওর প্রতিভা আছে। তুমি যদি না আসো, গ্যারান্টি দিচ্ছি তুমি আফসোস করবে।\n\nতোমার পুরনো বন্ধু জেনকিন ও ব্রাউন"
  },
  Mail_21466_Name = {
