  Mail_21467_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nমানুষ যখন দেবতাদের রাজ্যে বাস করত, তখন থেকেই আমরা নৃত্যের মাধ্যমে আমাদের আবেগ প্রকাশ করতে শুরু করেছিলাম——উল্লাসের ঘূর্ণন, শোকের পদক্ষেপ……কেউ কেউ বলে নৃত্যের ইতিহাস মানবজাতির ইতিহাসের মতোই সুদীর্ঘ, এটি আমাদের গৌরবের সাক্ষী হয়েছে, আবার আমাদের হতাশারও সাক্ষী হয়েছে।\n\nআমি একবার বলেছিলাম যে আমি আর কখনো নাচব না, কিন্তু……আমি তো নৃত্যের জন্যই জন্মেছি। তাই, শুধু আজকের জন্য, তুমি কি আমার সাথে নাচতে চাও? আমার সাথে নিমগ্ন হও, শরীরের গভীরতম ছন্দ অনুভব করো।\n\nআমি নৃত্যকক্ষে তোমার জন্য অপেক্ষা করব।\n\n\n\nলিজ"
  },
  Mail_21467_Name = {
    Text = "এসো একসাথে নৃত্য করি"
