  Mail_21467_Sender = {Text = "লিজ"},
  Mail_21468_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nআমি জাগ্রত সত্তা হওয়ার আগে, আমার জন্মদিনগুলোতে সহযোদ্ধাদের সাথে সামরিক শিবিরের বাইরে থেকে মদ এনে, রসদ রাখার তাঁবুতে লুকিয়ে রেশনের কালো রুটি দিয়ে গোপনে উদযাপন করতাম, তারপর ঊর্ধ্বতন কর্মকর্তা আবিষ্কার করার আগেই বোতলগুলো বাইরের ঝোপে ছুড়ে ফেলতাম।\n\nকিন্তু মিসাগার্দ কোনো সেনাবাহিনী নয়, এখানে আমরা মনের আনন্দে উদযাপন করতে পারি। আপনি কি আমার সাথে এক বোতল উৎকৃষ্ট মদ ভাগ করে আমার জন্মদিন উদযাপন করতে রাজি হবেন?\nযদি রাজি হন, তাহলে আজ রাতে চাঁদ যখন ঘণ্টাঘরের উপর দিয়ে যাবে, তখন আবাসনের ছাদে চলে আসুন। আপনি কি কখনো লক্ষ্য করেছেন, সেখান থেকে সমগ্র মিসাগার্দের সেরা দৃশ্য দেখা যায়?\n\n\n\nএলভা"
  },
  Mail_21468_Name = {
    Text = "উৎকৃষ্ট সুধা..."
