  },
  Mail_21469_Desc = {
    Text = "সমুদ্র সৈকত সমুদ্র সৈকত সমুদ্র সৈকত সমুদ্র সৈকত!\nএ? চিঠির শুরুতে প্রাপকের নাম লিখতে হয়——কী ঝামেলা! গোপনীয়তার রক্ষক তো ফ্রিজে যে স্টিকি নোট লাগায় তাতে প্রাপকের নাম লেখে না!\nআজ ওরিটার... এ... কততম জন্মদিন? যাই হোক, আজ ওরিটার জন্মদিন!\nএগুলো ওরিটার গুপ্তধন! সব তোমাকে দিলাম! ওরিটাকে সমুদ্র সৈকতে নিয়ে যাও, প্লিজ প্লিজ প্লিজ!\nএটাকে, এটাকে ওরিটার জন্মদিনের উপহার হিসেবে ধরে নাও, ঠিক আছে না~\n\nওরিটা"
  },
  Mail_21469_Name = {
    Text = "সৈকত!"
