  Mail_21469_Sender = {
    Text = "অরিটা"
  },
  Mail_21470_Desc = {
    Text = "মহানুভব：\n\nঅতীতে দিদির সাথে প্রান্তর গ্রহে থাকাকালীন, আমরা সবসময় জড়িয়ে ধরে একই গাছের শক্তি শুষে নিতাম, আমাদের জন্মের স্মৃতি হিসেবে।\nসেই দিনগুলো যদিও তিক্ত ছিল, কিন্তু এখন মনে পড়লে আনন্দ ও উষ্ণতা অনুভব না করে পারি না।\nআজ আবার আমাদের জন্মের স্মরণ দিবস, যদি সম্ভব হয়, আমি কি একটি গানের বিনিময়ে একটি ডাল পেতে পারি?\nএকটি মিষ্টি ডাল, যা আমার ও দিদির অতীতের প্রতিনিধিত্ব করতে পারে, আমার ও আপনার ভবিষ্যতের প্রতিনিধিত্ব করতে পারে……\n\nটিংকচার"
  },
  Mail_21470_Name = {
    Text = "জন্মদিনের গান"
  },
  Mail_21470_Sender = {
    Text = "টিঙ্কট"
  },
  Mail_21471_Desc = {
    Text = "ভাগ্যের মহান আশীর্বাদে, মিসাগ বিশ্ববিদ্যালয়ের গোপনীয়তার রক্ষক, জ্ঞানী ও দয়ালু প্রভু:\nশুভেচ্ছা!\nকিছুদিন আগে, আমি দেখলাম মালবাহী গাড়ি বিশ্ববিদ্যালয়ের আস্তাবলে যাতায়াত করছে, এবং জানতে পারলাম যে একটি ওয়ার্মব্লাড ঘোড়া আনা হয়েছে। গত বার প্রভুর সাথে তদন্ত কার্য পরিচালনার সময় আপনি বলেছিলেন যে আপনার কখনো ঘোড়ায় চড়ার অভিজ্ঞতা হয়নি, সেকথা মনে পড়ল। ওয়ার্মব্লাড বাছুর ঘোটকী সবচেয়ে শান্ত স্বভাবের হয়, নতুন শিক্ষার্থীদের ঘোড়ার পিঠে অভ্যস্ত করার জন্য এর চেয়ে উপযুক্ত আর কিছু নেই।\nঘোড়ায় চড়ে ভোর ও সন্ধ্যার পিছু ছোটা — আমার স্মৃতিতে এটাই সবচেয়ে প্রশান্তিময় মুহূর্ত। যদি প্রভু আস্থা রাখেন এবং আমার সাথে একসঙ্গে চড়তে রাজি হন, তবে আমি এই প্রশান্তি আপনার সাথে ভাগ করে নিতে চাই।\n\nওজিয়ের"
  },
  Mail_21471_Name = {
