  Mail_21472_Desc = {
    Text = "পুরাতন রাজ্যের পঞ্জিকা লন্ডিনিয়ামে আজকাল যা প্রচলিত তার থেকে সম্পূর্ণ ভিন্ন।\nআমার জন্ম হয়েছিল দ্বিতীয় গ্রীষ্মমাসের পঞ্চম পূর্ণতারা দিবসে, আজকের দিনে উদযাপনের জন্য বেছে নেওয়া হয়েছে গবেষণাগারের প্রধানের গণনার ফলাফল অনুসারে।\nপুরাতন রাজ্য টিকে থাকাকালীন, প্রধান পুরোহিত সবকিছুর আয়োজন করতেন। বিশাল আচার-অনুষ্ঠানের পর সমগ্র জাতি উদযাপনে মেতে উঠত, সাত দিনব্যাপী ছুটি শুরু হতো।\nযদিও এটা আমার চাওয়া নয়, তবে আনন্দের বিস্তার রোধ করার কোনো কারণও আমার নেই।\nআজ মিসাগের সরকারি ছুটির দিন নয়, এবং গোপনরক্ষকের দায়িত্ব নিশ্চিত করে যে তোমার নিয়মিত বিশ্রামের দিন থাকবে না।\nতবে, আমার জন্মদিনের শুভেচ্ছা জানানোর অজুহাতে ছুটির আবেদন করলে, প্রশাসন বিভাগও সম্ভবত আপত্তি করার সাহস পাবে না।\nএকটি অবসরপূর্ণ দুপুর কাটাও।\n\nতুরু"
  },
  Mail_21472_Name = {
    Text = "জন্মদিন..."
