  Mail_21473_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nঅরিটা বলেছে, জন্মদিনে সবাই ইচ্ছা পূরণের প্রার্থনা করে।\nআর আমি এমন একজন যে কখনো প্রার্থনা করে না।\nকারণ আমার ভাবনাগুলো সবসময় বাস্তব হয়ে যায়। এটা ভাগ্য নয়, বরং এটা অনেকটা... নিয়তির নির্দেশনার মতো?\nযেমন গত মাসে সেলেস্তের সাথে সমুদ্রে গিয়ে, আমি আবারও 'ঘটনাক্রমে' একটি সুন্দর জীবাশ্ম কুড়িয়ে পেলাম।\nস্থানীয় অধিবাসীরা একে 'সামুদ্রিক লিলি' বলে ডাকে। এর বাহুগুলো বায়ুকলের মতো স্রোতের দিকে মেলে ধরা, অলসভাবে গ্রীষ্মের বিকেলের রোদ উপভোগ করছে।\nভঙ্গুর, সুন্দর। এটা দেখার সাথে সাথে, মনের মধ্যে স্বাভাবিকভাবেই তোমার ছবি ভেসে উঠল।\nএবারও আমি কোনো প্রার্থনা করিনি——\nতোমার নিশ্চয়ই পছন্দ হবে, তাই না?\n\nশান"
