    Text = "গোপনীয়তার রক্ষক：\n\nঅতীতে এলটনের সাথে সমুদ্রযাত্রার সময়, তিনি প্রতি বছর এই দিনে একটি ভোজ প্রস্তুত করতেন এবং আমাকে 'ইচ্ছা প্রকাশ' করতে বলতেন।\nএখানে আসার আগে, আমি বুঝতাম না 'ইচ্ছা' কী। এখন, আমি জানি না আমার কী 'ইচ্ছা' থাকতে পারে……\nহয়তো, 'ইচ্ছা' খুঁজে পাওয়াটাও একটি 'ইচ্ছা' হতে পারে?\n\nহিলেসেস্ট"
