  Mail_21476_Desc = {
    Text = "গোপনরক্ষক:\n\nঅরেটা আমাকে বলেছে যে, তুমি নাকি জন্মদিনে করা সব ইচ্ছা পূরণ করো, তাই কি?\nসত্যি হওয়ার কথা না, তাই না? সবার ইচ্ছা পূরণ করা তোমার জন্য অনেক কষ্টকর হবে।\nতবে, যদি ইচ্ছা করার সুযোগ থাকে তাহলে……আমি চাই টিংকট আরও বড় মঞ্চ পাক।\nএটা কি পূরণ করা খুব কঠিন হবে? উম……তা-তাহলে বদলে দিই, 「আগামী এক বছরে আমার খাবার টেবিলে যেন আর সেলেরি না আসে」, এটা কি হবে?\n\nফেইন্ট"
  },
  Mail_21476_Name = {
    Text = "প্রার্থনা..."
  },
  Mail_21476_Sender = {
    Text = "ম্লান"
  },
  Mail_21477_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nতোমাকে একটা গোপন কথা বলি: এই জন্মদিনটা আসলে নকল। আমার আসল জন্ম তারিখ... সেটা বাতাসে হারিয়ে যাক।\nঅসুস্থ হওয়ার পর, দাদা সবসময় জন্মদিনের দিন বাটলারকে চুপচাপ আমার জন্য একটা ছোট কেক তৈরি করতে বলতেন।\nকোনো জন্মদিনের গান নেই, কোনো শুভেচ্ছাও নেই, যেন জন্মদিন পালন করা একটা লজ্জার বিষয়।\nএখন সবকিছু বদলে গেছে, আমি রোদে হাঁটতে পারি, জোরে গান গাইতে পারি, আর জন্মদিনও পালন করতে পারি।\nএগুলো শুধু ছোট ছোট আনন্দ, তবুও আমাকে সেই দিনগুলোর কথা মনে করিয়ে দেয়।\nধন্যবাদ, গোপনীয়তার রক্ষক।\n\n(অবশ্যই, যদি তুমি আর সবাই আমার সাথে আরেকটু রূঢ় হতে... আরও বেশি রূঢ় হতে... তাহলে আরও নিখুঁত হতো।)\n\nরেয়া"
  },
  Mail_21477_Name = {
    Text = "একটি রহস্য..."
  },
  Mail_21477_Sender = {Text = "লি"},
  Mail_21478_Desc = {
    Text = "আমার ছোট্ট·বন্দী:\n\nআমি অনেক·অনেক·অনেক দিন ধরে চাবুক ঘোরাইনি——\nএই বিরক্তিকর স্কুলে আটকে পড়ে, স্কুল ইউনিফর্মে বন্দী হয়ে, পান্ডিয়ার মন চুলকাচ্ছে, যেন দুষ্টু বিড়ালছানা নখ দিয়ে আঁচড়াচ্ছে। কিন্তু কেউ আমাকে বোঝে না, উপরন্তু সেই কর্মচারীরা সর্বতোভাবে আমাকে 「মজা করা」 থেকে আটকাচ্ছে——এটা সত্যিই অন্যায়!\nআহা, আজ কিন্তু একটা বিশেষ দিন, আমার চাবুককে আবার কোমল ত্বকে স্পর্শ করানোর জন্য খুবই উপযুক্ত, যন্ত্রণার সুমধুর আর্তনাদ শোনার জন্য……যদি আজ তোমার সময় থাকে, তাহলে, আমার সাথে একটু গল্প করতে আসবে না~?\n\nপান্ডিয়া"
  },
  Mail_21478_Name = {
    Text = "চাবুকের শব্দ…"
  },
  Mail_21478_Sender = {
    Text = "প্যান্ডিয়া"
  },
  Mail_21479_Desc = {
    Text = "<Big:জাদু মাস্টার ক্যাসিয়ার বার্ষিকী বিশেষ পরিবেশনা, শুধুমাত্র আজকের জন্য!>\n\nবছরের পর বছর ধরে দর্শকদের সমর্থন ও উৎসাহের প্রতি কৃতজ্ঞতা জানাতে, এবং অতীতে আপনাদের দেওয়া সমস্ত আনন্দের প্রতিদান হিসেবে, জাদু মাস্টার ক্যাসিয়া আজ রাত ঠিক ৮টায় মিসাগার্ড বিশ্ববিদ্যালয়ের প্রাঙ্গণে (ফিলিপসের মূর্তির পাশে) একটি বিশেষ বার্ষিকী পরিবেশনা করার সিদ্ধান্ত নিয়েছেন! আজ রাতে, আপনি দেখতে পাবেন আগের চেয়ে আরও জমকালো মঞ্চ, আরও রোমাঞ্চকর পরিবেশনা, এবং — সবচেয়ে গুরুত্বপূর্ণ — আরও অলৌকিক, আপনার নিজের চোখকে অবিশ্বাস করতে বাধ্য করা জাঁকজমকপূর্ণ জাদু! এমনকি মিসাগার্ডের মস্তিষ্ক স্বয়ং উপস্থিত থাকলেও, এই কল্পনাতীত জাদুর কাছে মাথা নত করতে বাধ্য হবেন — এটি মাস্টার ক্যাসিয়ার প্রতিশ্রুতি!\n\nএই বিরল সুযোগ শুধুমাত্র আজ রাতে, এবং সম্পূর্ণ বিনামূল্যে! মাস্টার ক্যাসিয়া আপনার জন্য অপেক্ষা করছেন!\n\n<Small:পুনশ্চ: পরিবেশনার সময় বা পরে মানসিক অবসাদ, মেজাজ খারাপ ইত্যাদি লক্ষণ দেখা দিলে মাস্টার ক্যাসিয়া কোনো দায়িত্ব নেবেন না।>\n<Small:পুনশ্চ ২: মিসাগার্ডের মস্তিষ্ক সম্পর্কিত যেকোনো প্রচারণা সেই সময়ের প্রকৃত পরিস্থিতির উপর নির্ভরশীল, মাস্টার ক্যাসিয়া অনুষ্ঠান ও অনুষ্ঠানের প্রভাব সম্পর্কে সমস্ত ব্যাখ্যার অধিকার সংরক্ষণ করেন।>"
  },
  Mail_21479_Name = {
    Text = "মাস্টার ম্যাজিশিয়ান ক্যাসিয়ার বার্ষিকী শো!"
  },
  Mail_21479_Sender = {
    Text = "ক্যাসিয়া"
  },
  Mail_21480_Desc = {
    Text = "এই, আজ কিন্তু আমার জন্মদিন, উপহার কোথায়?\nকী, তুমি প্রস্তুত করতে ভুলে গেছ……? হুঁ, আমি জানতামই এমনটা হবে।\nনাও, এই ক্যালেন্ডারটা রাখো, এতে স্পষ্টভাবে লেখা আছে আমার জন্মদিন, আমার স্মরণ দিবস, মিসাগে আসার প্রথম দিনের বার্ষিকী, আর আনন্দ উৎসব, কৃষি দেবতার উৎসব……এর তারিখ, এই উৎসবগুলো আমাদের একসাথে পালন করতে হবে, যাই হোক পরের বার ভুলো না কিন্তু!\n\nযদি আবারও ভুলে যাও তাহলে……আমি তোমাকে কিছু করতে পারব বলেও মনে হয় না, হুঁ।\nযাই হোক ভুলে যাওয়া চলবে না।\n\nআগ্রিপা"
  },
  Mail_21480_Name = {
    Text = "এই যে..."
  },
  Mail_21480_Sender = {
    Text = "অ্যাগ্রিপা"
  },
  Mail_21481_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমি এই চিঠি লিখতে চাইনি, কিন্তু এরিকার সিস্টেমে কোনো সমস্যা হচ্ছে বলে মনে হচ্ছে। আমি এই চিঠি লেখা শেষ করার আগেই তার অ্যালার্ম অবিরাম বেজে চলেছে।\nজন্মদিন আমার কাছে একটি অর্থহীন তারিখ। পরীক্ষা-নিরীক্ষার সাফল্যের হার অন্য দিনের চেয়ে বেশি হয় না, আর আমার নর্থস সূচকও এই তারিখের কারণে কোনো পরিবর্তন হয় না। কিন্তু রামোনা জোর করে এই দিনটিকে আমার 「বিশ্রামের দিন」 বানিয়ে দিয়েছে এবং আজ আমার ল্যাবে প্রবেশের অনুমতি সীমিত করে দিয়েছে।\nআমার যাওয়ার কোথাও নেই, তাই আজ আমি তোমার আগের সব প্রতিবেদনের একটি পূর্ণাঙ্গ পর্যালোচনা করব।\nরাতের খাবারের পর আর্কাইভ রুমে একবার এসো। মনে রেখো, আর্কাইভ রুমে কোনো কেক আনার চেষ্টা কোরো না — কাগজের নথিপত্র অত্যন্ত ভঙ্গুর।\n\nডোর"
  },
  Mail_21481_Name = {
    Text = "নৈশভোজের পর..."
  },
  Mail_21481_Sender = {Text = "ডল"},
  Mail_22435_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\nপ্রথমদিকে ভোরের আলো ফোটার সময় ক্যাম্পাসে কবিতা পড়ার কারণ ছিল এই সময়ে পথচারী কম থাকে, তাই কবিতার জগতে নিজেকে আরও গভীরভাবে ডুবিয়ে দেওয়া যায়। পরে, আমি ধীরে ধীরে ভোরের অস্পষ্ট আলো, স্বচ্ছ শিশিরবিন্দু এবং পাখিদের মধুর কূজনকেও ভালোবাসতে শুরু করেছি।\nআমি কল্পনাও করিনি যে অনেক শিক্ষক ও শিক্ষার্থী নীরবে আমাকে লক্ষ্য করছিলেন এবং গোপনে একটি কবিতা সমঝদার সংঘ গঠন করেছিলেন। আজ আমার জন্মদিন, এবং ঠিক এই সময়েই সংঘের নার্সিসাস ফুলের কুঁড়ি ফুটতে চলেছে। এই উপলক্ষে, তারা ক্যাম্পাসে একসাথে প্রকৃতি উপভোগ করতে করতে কবিতা পাঠের একটি কবিতা আস্বাদন অনুষ্ঠান আয়োজন করতে চাইছেন।\nএই সুন্দর মুহূর্তে, আশা করি আপনিও এসে আমাদের সাথে উপভোগ করবেন।\n\nনিংফিয়া"
  },
