  Mail_23897_Desc = {
    Text = "প্রিয় রক্ষক, \n      V1.0.21 আপডেটে আমরা কঠিন মাত্রার 「তদন্ত」, স্বাভাবিক ও কঠিন মাত্রার 「Psyche Deepdive」 যুদ্ধ স্তরসমূহ, এবং 「আবর্তন ব্যবধান」 I‑IV‑এর প্রতিটি স্তরের প্রথম‑ক্লিয়ার পুরস্কার সমন্বয় করেছি। বিস্তারিত পরিবর্তনসমূহ 「V1.0.21 অনলাইন রক্ষণাবেক্ষণ বিজ্ঞপ্তি」‑তে পাওয়া যাবে।\n       আপনার পূর্ববর্তী তদন্ত ও চ্যালেঞ্জ অগ্রগতির ভিত্তিতে, এই সমন্বয় অনুযায়ী আপনাকে পূর্বে অগ্রহণকৃত পুরস্কারগুলো প্রদান করা হবে। অনুগ্রহ করে সংযুক্তি দেখুন।"
  },
