  Mail_24200_Desc = {
    Text = "প্রিয় রক্ষক, \n       V1.0.24 আপডেটে আমরা 「অভিযান তদন্ত」‑এর 5ম অধ্যায় পুনরায় উন্মুক্ত করেছি, যা সাময়িকভাবে V1.0.16‑এ বন্ধ ছিল। ন্যায়সংগততা নিশ্চিত করতে, পুরস্কারের পরিবর্তন এবং প্রতিটি রক্ষকের তদন্ত রেকর্ডের ভিত্তিতে আমরা ক্ষতিপূরণ প্রদান করব। আপনার রেকর্ড অনুযায়ী, এইবার আপনার জন্য কোনো ক্ষতিপূরণ প্রয়োজন নেই।"
  },
