  Mail_24202_Desc = {
    Text = "প্রিয় রক্ষক,\nমরিমেন্স-এর প্রতি আপনার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে রক্ষকদের জন্য আরও উন্নত গেমিং অভিজ্ঞতা দিতে, আমরা আপনাকে নিম্নলিখিত অভিজ্ঞতা জরিপটি পূরণ করার আমন্ত্রণ জানাচ্ছি। কৃতজ্ঞতার নিদর্শন হিসেবে, আমরা পুরস্কার হিসেবে [Silver*200] প্রস্তুত করেছি, যা আপনি জরিপ সম্পন্ন করার পর গ্রহণ করতে পারবেন।\n<SurveyLink:[Click here to fill it out]>\nআমরা প্রতিটি রক্ষকের প্রস্তাবকে গুরুত্ব সহকারে বিবেচনা করব, আর আপনার প্রতিক্রিয়া নিঃসন্দেহে মিথাগ বিশ্ববিদ্যালয়কে ক্রমশ আরও উন্নত করে তুলবে!\n—রৌপ্য চাবি যেন আপনার পথ নির্দেশ করে।"
