  Mail_24280_Desc = {
    Text = "হ্যালো, রক্ষক, \nগতকালের ফ্যান্টাসমাল ডাইভ তদন্তে আপনি 「{s1} র‍্যাঙ্ক」 অর্জন করেছেন, আপনার অবস্থান {s2}, তদন্তের শিরোনাম ছিল 「{s3}」। নিচে আপনার র‍্যাঙ্কিং পুরস্কার দেওয়া হলো; অনুগ্রহ করে সংগ্রহ করতে ভুলবেন না।"
