  Mail_24280_Name = {
    Text = "মায়াবী অবগাহন দৈনিক র‍্যাঙ্কিং পুরস্কার"
  },
  Mail_24280_Sender = {
    Text = "মিথাগ বিশ্ববিদ্যালয় কমিটি"
  },
  Mail_24877_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমার প্রতিটি জন্মদিন ছিল এক জাঁকজমকপূর্ণ সালোঁ, বিশিষ্ট অতিথিতে পরিপূর্ণ, সকলেই আনন্দে মেতে উঠত।\nকিন্তু এবার, আমার একটু ভিন্ন ভাবনা আছে—\nএত দিন আয়োজকের আসনে বসে থেকে, মাঝে মাঝে অতিথি হওয়ার স্বাদ নিতে ইচ্ছে করে।\nআরেকটি মার্জিত সালোঁ হবে, নাকি একটি সাধারণ ঘরোয়া রাতের খাবার—সবকিছু তোমার সিদ্ধান্ত, কেমন?\nতবে, যদি আরেকটি সালোঁ আয়োজন করতে চাও, তাহলে সেসব বিখ্যাত আভিজাত্যদের আমন্ত্রণ কোরো না।\nএমন একটি বিশেষ দিনে, আমি মিথ্যা হাসির মুখোশ পরে থাকতে চাই না।\n\n<Del:রেড লেডি> সোরেল"
  },
  Mail_24877_Name = {
    Text = "এখন সবই… তোমার হাতে…"
  },
  Mail_24877_Sender = {
    Text = "সোরেল"
  },
  Mail_24878_Desc = {
    Text = "মালিক: \n\nআজ লিলির জন্মদিন, আগ্রিপ্পা বলেছে 「জমিয়ে উৎসব করতে」 হবে।\nআগে মা লিলির জন্মদিনে এরকম করতেন না, মা আমাকে চোখা টুপি পরিয়ে দিতেন, একসাথে হাততালি দিয়ে মোমবাতি নেভাতেন।\nলিলি জানে না, কীভাবে করলে সঠিক হবে, দয়া করে মালিক নির্দেশ দিন। \n\nলিলি"
  },
  Mail_24878_Name = {
    Text = "ব্যাকুল…"
