  Mail_24878_Sender = {
    Text = "লিলি"
  },
  Mail_25147_Desc = {
    Text = "প্রিয় রক্ষক, \n       V1.1.0 আপডেটে মায়াবী অবগাহনের সাপ্তাহিক পয়েন্ট পুরস্কার নতুন 「সাপ্তাহিক ট্রায়াল」 দ্বারা প্রতিস্থাপিত হয়েছে। ন্যায়সংগততা নিশ্চিত করতে, আমরা তাদেরকে অগ্রহণকৃত সাপ্তাহিক পয়েন্ট পুরস্কার প্রদান করব, যারা 「মায়াবী অবগাহন」 আনলক করেছিলেন কিন্তু সব সাপ্তাহিক পয়েন্ট পুরস্কার গ্রহণ করেননি এবং 15 জানুয়ারি ভোর 5টার আগে লগইন করেছেন। অনুগ্রহ করে যাচাই করুন।"
  },
