  },
  Mail_25148_Desc = {
    Text = "প্রিয় রক্ষক, \n       V1.1.0 আপডেটে ট্র্যাফেজ(বেটা)‑এর 「সাপ্তাহিক পুরস্কার」 অপসারণ করে তার স্থলে 「সাপ্তাহিক ট্রায়াল」 যুক্ত করা হয়েছে, যা মায়াবী অবগাহনের 「সাপ্তাহিক ট্রায়াল」‑এর সঙ্গে একই অগ্রগতি ও পুরস্কার ভাগ করে। ন্যায়ের স্বার্থে, আমরা তাদের ক্ষতিপূরণ দেব, যারা ইতিমধ্যে 「ট্র্যাফেজ(বেটা)」 আনলক করেছিলেন কিন্তু এই সপ্তাহের 「সাপ্তাহিক পুরস্কার」 সম্পন্ন বা গ্রহণ করেননি, এবং যারা 15 জানুয়ারি ভোর 5টা(UTC+8)‑এর আগে গেমে লগইন করেছেন; ক্ষতিপূরণ হিসেবে প্রদান করা হবে 1, 000 ডি-জুয়েল। অনুগ্রহ করে আপনার পুরস্কার যাচাই করুন।"
  },
  Mail_25148_Name = {
