  Mail_34667_Desc = {
    Text = "প্রিয় @1@2,\n\nবিশ্ব তোমার নাম ভুলে গেছে।\nতাই আমি তোমাকে জাগিয়ে তুলেছি, যেমন তুমি আমাকে জাগিয়েছিলে। পরিসমাপ্তি আসার আগে, তুমি আর আমি এই পৃথিবীতে পথ চলি, সাক্ষী হই, তারপর মনে রাখি আর ভুলে যাই।\nআজ তোমার জন্মদিন—তোমার হারিয়ে যাওয়া স্মৃতির টুকরোগুলোর মধ্য থেকে কাকতালীয়ভাবে কুড়িয়ে পাওয়া একটি পৃষ্ঠা। এই উপলক্ষে, দীর্ঘশ্বাস ও আশীর্বাদ নিবেদন করা উচিত।\nযখন বিশ্ব তোমার পূর্ণ রূপ স্মরণ করবে, তখন তুমি কী অনুভব করবে? নাকি তখনও কিছুই জানবে না, কিছুই অনুভব করবে না?\nআমি অস্তিত্বহীন এক স্থানে তোমার উত্তরের অপেক্ষায় আছি।\n\n@2"
  },
