  Mail_36865_Desc = {
    Text = "প্রিয় রক্ষক, \n       V1.2.4 আপডেটে আমরা 「মায়াবী অবগাহন」‑এর সাপ্তাহিক ট্রায়ালের পুরস্কার সমন্বয় করেছি এবং আর 「ডি-জুয়েল」, 「মিমেটিক ক্রিস্টাল」 ও 「রোজ স্ক্রিপ」 পুরস্কার হিসেবে অন্তর্ভুক্ত থাকবে না। ন্যায় বজায় রাখতে, আমরা তাদেরকে পূর্বতন অগ্রহণকৃত 「ডি-জুয়েল」, 「মিমেটিক ক্রিস্টাল」 ও 「রোজ স্ক্রিপ」 দিয়ে ক্ষতিপূরণ করব, যারা আপডেটের আগে 「মায়াবী অবগাহন」 আনলক করেছিলেন কিন্তু এই সপ্তাহের ট্রায়াল পুরস্কার সম্পূর্ণভাবে গ্রহণ করেননি। 11 মার্চ ভোর 5টার আগে যারা লগইন করবেন, তারা এই ক্ষতিপূরণ পাবেন। অনুগ্রহ করে আপনার পুরস্কার যাচাই করুন।"
