  Mail_36866_Desc = {
    Text = "প্রিয় কিপার,\n       V1.2.4 আপডেটে, নরমাল মোডে 「Psyche Deepdive「 পর্যায় 「Blood and Sand,「 「Twisted Core,「 এবং 「The Knight's Wish「 সম্পন্ন করলে নতুন পসি আনলক হবে: 「Roaring Blood and Sand,「 「Ephemeral Eternity,「 এবং 「The Final Vow「। যেসব কিপার আপডেটের আগে নরমাল মোডে এই অধ্যায়গুলো সম্পন্ন করেছেন, তাদের আমরা সংশ্লিষ্ট পসি ক্ষতিপূরণ হিসেবে প্রদান করব। অনুগ্রহ করে আপনার পুরস্কার পরীক্ষা করুন।"
