    Text = "প্রিয় কিপার,\n       V1.2.4 আপডেটে, 「Arcane Dominion「 থেকে প্রাপ্ত অনন্য স্কিল আপগ্রেড উপকরণ ও Mimetic Crystal-এর পরিমাণ বৃদ্ধি করা হয়েছে। ন্যায্যতার স্বার্থে, যেসব কিপার আপডেটের আগে এই সপ্তাহের 「Arcane Dominion「 পুরস্কার গ্রহণ করেছেন, তাদের প্রাপ্ত পুরস্কারের সুপারিশকৃত লেভেলের ভিত্তিতে বাড়তি ড্রপের সমমূল্যের Mimetic Crystal ক্ষতিপূরণ হিসেবে প্রদান করা হবে। অনুগ্রহ করে আপনার পুরস্কার পরীক্ষা করুন।"
