  Mail_39548_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nঅনন্ত জীবনের কাছে জন্মদিন উদযাপন করাটা তেমন প্রয়োজনীয় বলে মনে হয় না। অসীম সময়ের স্রোতের তুলনায়, তোমরা মানুষেরা যাকে অবিস্মরণীয় বা দুর্দান্ত স্মৃতি বলো, সেগুলো কিছুটা... তুচ্ছ মনে হয়।\nতবুও তোমরা এই সব 「তুচ্ছ」 বিষয়গুলো স্মরণ করতে অসংখ্য উৎসব ও অনুষ্ঠান উদ্ভাবন করেছ — অবশ্যই, এটাও মানুষের প্রতি আমার আগ্রহের অন্যতম কারণ। তোমরা সত্যিই যথেষ্ট মনোমুগ্ধকর।\nতবে, তোমার সাথে আমার সাক্ষাৎকে এই 「তুচ্ছ」 মুহূর্তগুলোর মধ্যে গণ্য করা যায় না, কারণ তুমি তাদের থেকে আলাদা... আর এই 「আলাদা」 ভবিষ্যতে কী ধরনের ঝড় তুলবে, সেটা নিয়ে আমিও অত্যন্ত উৎসুক।\nযাই হোক, আমার বাক্যবাহুল্যের জন্য ক্ষমা করো... যেহেতু আজ আমার জন্মদিন, তাই আমি 「জন্মদিনের বিশেষ অধিকার」 প্রয়োগ করার অনুমতি চাইছি।\nতোমাকে কী করতে হবে, শুশ... তাড়াহুড়ো করো না, রহস্যের উত্তর আমার শোবার ঘরে রয়েছে, আজ রাত মধ্যরাতে একা এসো।\n\nওয়ান্ডা"
  },
  Mail_39548_Name = {
    Text = "জন্মদিনের তারকার বিশেষ সুবিধা..."
