  Mail_39548_Sender = {
    Text = "ওয়ান্ডা"
  },
  Mail_39549_Desc = {
    Text = "আজ মার্ফি-সামার জন্মদিন——জন্মদিন মানেই তো ভোজ আর উৎসব হওয়া উচিত!\nরসদ ব্যবস্থাপনা বিভাগের লোকজন বেশ ভালোই করেছে, তবে তারা আসলে অভিনয়ে একদমই পারদর্শী না, তার উপর আবার লুকোচুরি করছে——এই মহিমাময়ী আমি অনেক আগেই দেখে ফেলেছি যে তারা জাগরণ শাখার গুদামে কেকের সাজসজ্জা রাখছে। উম্ম……তুমি তো ওই কর্মচারীদের শাস্তি দেবে না, তাই না? তা-তারা সত্যিই খুব ভালো করেছে, শুধু চমকটা ঠিকমতো লুকাতে পারেনি……\nএখানেই লেখা শেষ করছি, মনে হচ্ছে কেউ আমাকে বাইরে ডাকছে——তারা যদি বোকার মতো রঙিন কাগজ দিয়ে এই মহিমাময়ী আমাকে ভরিয়ে দেয়, তাহলে খবর আছে।\nযাই হোক, কেক কাটার সময়, তুমি থাকবে তো?\n\nমার্ফি"
  },
