  Mail_44837_Desc = {
    Text = "শ্রদ্ধেয় ফ্যাকাশে দূত:\n\nকয়েকটি শিশু আজ ফুলের তোড়া আর মিষ্টি নিয়ে এসেছে, তখনই আমার মনে পড়ল যে, মহাপ্লাবন বর্ষপঞ্জির শতাধিক বছর আগে আজকের এই দিনে আমি পিতা-ঈশ্বরের কৃপায় জীবন লাভ করে এই পৃথিবীতে এসেছিলাম। সে কত যুগ আগের কথা! শৈশবের স্মৃতি অনেক আগেই ঝাপসা হয়ে গেছে, শুধু হোন্দোসা গির্জার ধূপের গন্ধটুকু এখনও আমার মনে ঘুরে বেড়ায়, কিছুতেই মুছে যায় না। আজ গির্জাটি টিকে থাকলেও, ধূপের মিশ্রণ আর সেদিনের মতো নেই।\n\nক্ষমা করবেন, অতীত নিয়ে আক্ষেপ করা আমার এই চিঠির উদ্দেশ্য নয়। শিশুদের আনা মিষ্টি দিয়ে আমি একটি চায়ের আসর সাজিয়েছি, আশা করি আপনি এসে আমার সাথে ভাগ করে নেবেন — আমার জন্মদিন উদযাপনের জন্য নয়, বরং জীবনের প্রতিটি দিনকে উদযাপন করতে, আশার প্রতিটি দিনকে উদযাপন করতে।\n\nআপনার জন্মদিন কবে? এক কাপ চায়ের পর অবশ্যই আমাকে জানাবেন।\n\n\n\nসালভাদোর"
