    Text = "প্রিয় কিপার,\n  V1.3.0 আপডেটে, আমরা \"Phantasmal Dive\" এবং \"Traphase (beta)\"-তে দ্বিগুণ কিপার EXP প্রদানকারী \"Premium Topics\" সুবিধাটি অপসারণ করেছি। দুঃখপ্রকাশস্বরূপ, বর্তমান \"Premium Topics\" ক্রয়কারী সকলকে এই মেয়াদের Curriculum শেষ হওয়া পর্যন্ত প্রতিদিন 240 কিপার EXP ক্ষতিপূরণ হিসেবে প্রদান করা হবে। অনুগ্রহ করে আপনার পুরস্কার পরীক্ষা করুন।"
