  Mail_48005_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nহঠাৎ বিরক্ত করার জন্য ক্ষমা চাইছি, আশা করি আমার বাজে হাতের লেখা আপনার ভালো মেজাজ নষ্ট করবে না। আসলে আমি লেখালেখিতে খুব একটা পারদর্শী নই……\nএই চিঠি লেখার কারণ হলো, মনে হচ্ছে আমার জন্মদিন এসে গেছে। এই উপলক্ষে আমি কিছু ছোট বিস্কুট তৈরি করেছি, আশা করি আপনিও একটু চেখে দেখবেন।\nসত্যি বলতে, আমি নিশ্চিত নই এই তারিখটা সঠিক কিনা। ক্ষয়রোগে আক্রান্ত হওয়ার পর, আমার অস্তিত্বের চিহ্ন একটু একটু করে মুছে যাচ্ছে। মিস ডোর আমাকে একবার জিজ্ঞেস করেছিলেন, সজ্ঞানে নিজেকে সবার কাছে ভুলে যেতে দেখা—সেটা কেমন অনুভূতি?\nএটা বর্ণনা করা কঠিন……যেন ঘুটঘুটে অন্ধকারে দাঁড়িয়ে আছি, একটা আলোকিত নদীর ধারে, মানুষেরা সবাই নদীর ওপারে একে অপরের সাথে কথা বলছে, নিজেদের কাজে ব্যস্ত, আমার সামনে দিয়ে তাড়াহুড়ো করে চলে যাচ্ছে। আমি শুধু তাদের দেখতে পারি, কিন্তু একটুও আওয়াজ করতে পারি না।\nএটা খুব একাকী একটা অনুভূতি। সৌভাগ্যবশত, সেই মানুষদের মধ্যে আপনি নেই।\nঅন্তত আপনি এখনও আমার গল্প মনে রেখেছেন, তাই না?\n\nপ.ব., বারোটি ছোট বিস্কুট চিঠির সাথে পাঠানো হলো।\n\nমেসন"
  },
