    Text = "প্রিয় রক্ষক, \n「বহুস্তরীয় নিরাময়」 ইভেন্টটি শেষ হয়েছে। আমরা অবশিষ্ট ইভেন্ট মুদ্রা 「মেমরি পাজল」 কে 「অহং বিশ্লেষণ」-এর সীমাহীন বিনিময় হারের ভিত্তিতে উদ্ধার করব। অনুগ্রহ করে আপনার পুরস্কারগুলো পরীক্ষা করে নিন।"
