  Mail_48914_Desc = {
    Text = "প্রিয় রক্ষক, \n 「মরিমেন্স」-কে সমর্থন করার জন্য আপনাকে ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে আপনার অভিজ্ঞতা আরও সমৃদ্ধ করতে, আমরা আপনাকে নিম্নলিখিত জরিপটি সম্পন্ন করার আমন্ত্রণ জানাচ্ছি। কৃতজ্ঞতার নিদর্শন হিসেবে, জরিপ সম্পন্ন করার পর আমরা পুরস্কার হিসেবে [Silver*200] প্রদান করব। জমা দেওয়ার শেষ সময় 28 অক্টোবর সকাল 9:00। অনুগ্রহ করে নির্ধারিত সময়ের মধ্যে সম্পন্ন করুন।\n   <SurveyLink:[Click here to fill out]>\n   আমরা প্রতিটি রক্ষকের প্রতিক্রিয়াকে মূল্য দিই। আপনার মতামত মিথাগ বিশ্ববিদ্যালয়কে উন্নত করতে সহায়তা করবে!\n   —রৌপ্য চাবি যেন আপনার পথ প্রদর্শন করে।"
  },
