  Mail_50344_Desc = {
    Text = "ছোট্ট চারাগাছ:\n\nবাতাস তোমার সুবাস বয়ে এনেছে, প্রথম যখন তোমাকে চিনেছিলাম তখনকার চেয়ে এখন আরও মিষ্টি লাগছে।\nতুমি আমার ভালোবাসায় বেড়ে উঠেছ, আমার ভালোবাসায় পরিপক্ব হয়েছ……ঠিক যেমন মৌমাছি আর মধুর সম্পর্ক।\nআজ একটি বিশেষ দিন, আমার সাথে একবার দেখা করতে আসবে?\nআমি তোমার কথামতো অনেকদিন ধরে বাধ্য হয়ে অপেক্ষা করেছি……এবার আমাকে কিছু পুরস্কার দেওয়ার সময় হয়েছে, তাই না?\n\nতাইয়ীসি"
