  Mail_53149_Desc = {
    Text = "আমি অনেক আগেই সিদ্ধান্ত নিয়েছি, আমার বাকি জীবনের প্রতিটি দিন সেই একজনের উদ্দেশ্যে উৎসর্গ করব……এটাকে আমার মূর্খতাপূর্ণ কর্মের প্রায়শ্চিত্ত হিসেবেই ধরুন।\nএই তুচ্ছ সত্তার 「জন্মদিন」, উল্লেখের যোগ্য নয়, মুখে আনারও মতো নয়।\nআজকের দিনটি অতীতের বা ভবিষ্যতের যেকোনো দিন থেকে আলাদা কিছু নয়, আমি যথারীতি প্রার্থনাগৃহে যাব।\nতবে, আপনি যদি চান যে আমি আজ প্রার্থনাগৃহ ছেড়ে মিসাসগের অতিথি হিসেবে আসি, তাহলে আমি অবশ্যই প্রভুর ইচ্ছার বিরুদ্ধে যাব না।\nযদি আপনি আমার প্রার্থনা প্রত্যক্ষ করতে চান, যেকোনো সময় আপনাকে স্বাগত……সবিনয়ে, আন্তরিকভাবে স্বাগত।\n\nমিরিয়াম"
