  Mail_54803_Desc = {
    Text = "প্রিয় রক্ষক,\n       V1.5.1 আপডেটে, আমরা 「Growth Record「-এ রক্ষক স্তর 21–80-এর জন্য সিলভার পুরস্কার বৃদ্ধি করেছি এবং 「রিয়েল্ম দক্ষতা「 স্টেজ I~V-তে গোপনরক্ষকের হ্যান্ডবুক সম্পন্ন করার জন্য 1000 অনুসন্ধান ব্যাজের পুরস্কার যুক্ত করেছি। আপডেটের আগে যারা ইতোমধ্যে উপরোক্ত পুরস্কার গ্রহণ করেছেন, সেই সব রক্ষকদের আমরা সমপরিমাণ সিলভার বা অনুসন্ধান ব্যাজ ক্ষতিপূরণ হিসেবে প্রদান করব। অনুগ্রহ করে আপনার পুরস্কারগুলি পরীক্ষা করুন।"
