    Text = "প্রিয় রক্ষক, \n「বসন্ত ঝরে যাওয়ার আগে」 ইভেন্টটি শেষ হয়েছে। আমরা আপনার অবশিষ্ট 「আনন্দের কবিতা」, 「বিষাদের কবিতা」 এবং 「আক্ষেপের কবিতা」 প্রতি 200টির জন্য 「রোজ স্ক্রিপ *5000」 হারে রূপান্তর করব। অনুগ্রহ করে আপনার পুরস্কারগুলো পরীক্ষা করে নিন।"
