  Mail_56101_Desc = {
    Text = "গোপনরক্ষক{Male=জনাব,Female=মিস}：\n\nআজ ভোরবেলা, বসন্তের প্রথম পাখির গানের মাঝে একটি গোলাপ ফুটেছে।\nএটি আসলে একটি কুঁড়ি হয়ে থাকার কথা ছিল, কিন্তু সেন্ট ভ্যালেন্টাইন দিবসে, আমার জন্মের এই দিনে, এটি এমন এক ঋতুতে ফুটে উঠেছে যা তার নয়।\nআমার সিতে-র কথা মনে পড়ে। প্রতি বছর জন্মদিনে সিতে-র রাস্তাগুলো খুব জমজমাট থাকত। আমি ফুল ফোটার শব্দ শুনতাম, মানুষের লজ্জাজনক প্রেমের কথা শুনতাম। কিন্তু অনেকদিন ধরে সেসব স্পর্শ করার সুযোগ পাইনি……আজ পর্যন্ত।\nআপনি কি কাকতালীয়তায় বিশ্বাস করেন, গোপনরক্ষক? আমার মনে হয়, কাকতালীয়তা একটি ভাষা, আর গোলাপ একটি অলংকার। আজ, মিসাগ্র-এর বিস্তৃত বাগানে, এই গোলাপটি প্রস্ফুটিত হয়েছে, তার পাপড়িগুলো অকপটে মেলে ধরেছে, যেন এক মনমাতানো কবিতা।\nতাই, আজ, গোপনরক্ষক……আপনি কি আমার সাথে এই গোলাপের প্রস্ফুটন দেখতে আসবেন?\nআমি এবং ফুল, দুজনেই আপনার আগমনের অপেক্ষায়।\n\nঅরলা"
  },
