  Mail_62392_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমার বাদন একসময় সম্রাটের সিংহাসনের সামনে পরিবেশিত হয়েছে, লক্ষ লক্ষ মানুষ তা শুনে মুগ্ধ হয়েছে। তবে সেসব প্রশংসার বাণী আমার কাছে মূল্যহীন, আমি কেবল সংগীতের পরম শিখরে পৌঁছাতে চাই।\nজাঁকজমকপূর্ণ মঞ্চে অন্যদের জন্য পরিবেশন করার চেয়ে, নির্জন বনে একাকী বাজানো আমাকে অনেক বেশি প্রশান্তি দেয়।\nমূলত আমি চাই না কেউ আমার অনুশীলন শুনুক, সেগুলো কেবল পূর্ণতার পথে আমার খসড়া, কিছু অর্থহীন বর্জ্য মাত্র।\nকিন্তু আপনাকে জানার পর, আপনাকে খুঁজে পাওয়ার পর, আমার প্রতিটি সুরই অর্থবহ হয়ে উঠেছে।\nআপনিই আমাকে সবচেয়ে মহান ও উদাত্ত সুর দান করেছেন, পথভ্রষ্ট আমাকে উদ্ধার করেছেন, যদিও আপনি নিজেও হয়তো তা জানেন না...\nআজ আমার জন্মদিন, আমি এটি প্রায় ভুলেই গিয়েছিলাম, কিন্তু এখন, আমি আমার নবজন্ম এবং যিনি আমাকে এই নবজন্ম দিয়েছেন তাঁকে স্মরণ করতে চাই।\nসম্প্রতি কিছু নতুন সুর রচনা করেছি, আপনাকে একটু শুনে দেখার জন্য আমন্ত্রণ জানাতে চাই। আমার বিলম্বের জন্য ক্ষমা করবেন, আমার পরিচয় এখনও মিসাগের সহকর্মীদের সামনে প্রকাশের উপযুক্ত নয়, তাই দিগন্ত সূর্যাস্তের শেষ আভা গ্রাস করার পরেই কেবল আপনাকে এই আমন্ত্রণপত্র পাঠাতে পারছি।\nআজ রাতে স্কুলের পেছনের বনে, আমি একটি বিশেষ সংগীত সন্ধ্যার আয়োজন করব, যেখানে দর্শক আসন মাত্র একটি।\nআপনার উপস্থিতির প্রত্যাশায়।\n\nহ্যামলিন"
  },
