  Mail_65350_Desc = {
    Text = "প্রিয় রক্ষক, \n「Til the Snow Melts」 ইভেন্টটি সমাপ্ত হয়েছে। আপনার অবশিষ্ট ইভেন্ট মুদ্রা—「Frozen Bud」, 「Silver Frost Bud」 এবং 「Sunlight Bud」—প্রতিটি আইটেমের বিনিময়ে 「Rose Scrip * 40」 হারে পুনরুদ্ধার করা হবে। অনুগ্রহ করে আপনার পুরস্কার অবশ্যই সংগ্রহ করুন।"
