  Mail_65442_Desc = {
    Text = "প্রিয় রক্ষক, \n「সকল জগতের দ্বার」 ইভেন্টটি সমাপ্ত হয়েছে। আপনার অবশিষ্ট ইভেন্ট মুদ্রা 「End Pointer」 আমরা 1:1 বিনিময় হারে 「Rose Scrip *40」 এ রূপান্তর করব। অনুগ্রহ করে আপনার পুরস্কারগুলি পরীক্ষা করতে ভুলবেন না।"
  },
  Mail_65442_Name = {
