  },
  Mail_67147_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\n    মহাবিশ্বের মাত্রাসমূহ আমার কাছে অদ্বিতীয় নয়, চরম দ্বারের ভেতর থেকে অসংখ্য জগৎ ও অসীম অস্তিত্ব উঁকি দেওয়া যায়। সেখানে সকল কল্পনা ও গাণিতিক যুক্তির ঊর্ধ্বে, তাই স্বাভাবিকভাবেই 「জন্মদিন」 এর তারিখ নির্ধারণ করা সম্ভব নয়।\n    তাই, তোমার ও আমার প্রথম সাক্ষাৎকেই সেই মুহূর্ত হিসেবে ধরা যাক। তুমি যে সময়ের ধারাবাহিকতায় রয়েছ, সেই মাপকাঠি অনুসারে আজকেই আমার জন্য বিশেষ অনুষ্ঠান পালন করা উচিত, আমার করা ইচ্ছা পূরণ করার জন্য।\n    তাহলে, রৌপ্য চাবির দ্বার অতিক্রম করে আমার কাছে এসো। আমি তোমাকে শেখাব…চূড়ান্ত উৎস সম্পর্কে কিছু জ্ঞান, যা মহাবিশ্বের নিজস্ব। আজ রাতে, কোটি কোটি উজ্জ্বল জ্যোতিষ্ক তোমার ও আমার জন্য জ্বলজ্বল করবে।\n    আমি চরম দ্বারে তোমার অপেক্ষায়।\n\nতাভি"
  },
  Mail_67147_Name = {
    Text = "সিলভার চৌকাঠ পেরিয়ে যাও..."
  },
  Mail_67147_Sender = {
