  },
  Mail_67933_Desc = {
    Text = "আমি তোমার ক্ষণিক বিভ্রান্তি টের পেয়েছিলাম—কেবল দৃষ্টির আঘাতে সর্বোচ্চ রেলিককে আঘাত করা, এমন আশা কীভাবে করা যায়? অথচ তুমি তা-ই করেছো।\nআরেকটি দৃষ্টি ভেঙে পড়ে, বর্মে আঁচড় আর ফাটল ধরে নিরন্তর খণ্ডাংশের আঘাতে।\n%player%, কেবল তোমার অফুরন্ত যুদ্ধস্পৃহাই সত্যিকারের অবিনাশী।"
  },
  Mail_67933_Name = {
    Text = "বিভ্রান্তি থেকে বেরোনোর পথ খুঁজে বের করো"
  },
  Mail_67933_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67934_Desc = {
    Text = "তোমার অঙ্গপ্রত্যঙ্গ কাঁপছে, %player%। তুমি প্রায় দাঁড়িয়েই থাকতে পারছ না। ভয় তোমাকে গ্রাস করেছে, তোমার মস্তিষ্ক শূন্য হয়ে গেছে, শ্বাস-প্রশ্বাস নিয়ন্ত্রণ করাও অসম্ভব হয়ে উঠেছে... তবু তুমি সামনে রৌপ্য চাবি তুলে ধরো।\nমানবীয় সকল গুণের মধ্যে সাহসই সর্বোচ্চ। বিপর্যয় আর জন্তু-দৈত্যের মুখোমুখি হয়ে আমরা একসময় হাতুড়ি আর বর্শা তুলেছিলাম। এখন দেবতাদের মুখোমুখি হয়েও তুমি একই কাজ করছ।\nমানব সভ্যতা সাহসের ওপর দাঁড়িয়ে গড়ে উঠেছে, আর চিরন্তন চক্র জুড়ে সে-ই তাকে বহন করে নিয়ে যাবে।"
  },
  Mail_67934_Name = {
    Text = "কম্পনের মাঝে সাহসের স্তবগান প্রতিধ্বনিত হয়"
  },
  Mail_67934_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67935_Desc = {
    Text = "আমরা একসময় এই পৃথিবী নিয়ে কথা বলেছিলাম; তুমি বলেছিলে, তোমার এটি ভালো লাগে না। স্বার্থ, ষড়যন্ত্র, প্রতারণা আর হত্যাকাণ্ডে ভরা এই জগৎ। ডিজলিউশন বা দেবতাদের অনুপস্থিতিতেও, এটি ইতিমধ্যেই ক্ষতবিক্ষত, ভাঙনের কিনারায় টলমল করছে। ইয়াকুতস্ক থেকে জাগরণের পর, তোমার একটি ক্ষণস্থায়ী স্মৃতির ভেতর দিয়ে তুমি অসংখ্য বিশৃঙ্খলা আর আতঙ্ক প্রত্যক্ষ করেছ, যা ডিজলিউশন-এর চেয়েও বহু গুণ ভয়াবহ。\nতবু যখন স্রষ্টা তাঁর তরবারি উঁচু করলেন, তুমি তবু এই পৃথিবীর সামনে দাঁড়িয়ে তাকে চরিত্রের ঢাল হয়ে রক্ষা করলে। বিলয় ছিল দেবতাদের ইচ্ছা, আর তুমি সেই ইচ্ছাকে অমান্য করেছ。\nআমি বুঝি, %player%। কোনো রক্ষকই এই পৃথিবীকে ঘৃণা করে না, আবার কোনো রক্ষক সত্যিকার অর্থে তাকে ভালোও বাসে না। কারণ এই নোংরামির মাঝখানে আমরা এমন কিছু গ্লিমার দেখেছি, যা সিলভারের মতো দীপ্তিমান。\nরক্ষকের কর্তব্য হলো সেই ক্ষীণ গ্লিমারগুলোকে চিরকাল পাহারা দিয়ে যাওয়া।"
  },
  Mail_67935_Name = {
    Text = "মানব আত্মা অনন্তকাল সহনশীল।"
  },
  Mail_67935_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67936_Desc = {
    Text = "প্রথমবার ডিজলিউশন প্রত্যক্ষ করা, প্রথমবার তার সত্যের মুখোমুখি হওয়া, প্রথমবার ঈশ্বরের কণ্ঠ শোনা... দীর্ঘ জীবনে আমি অগণিত হতাশার মুহূর্ত সহ্য করেছি, যখন জানতাম না কী করব, কিংবা সব প্রচেষ্টা আর উৎসর্গের অর্থ কী—তবু তার কোনোটাই তোমার বর্তমান পরিস্থিতির সমকক্ষ নয়।\nএটাই মানবতার দীপ্তি: হতাশার মুখোমুখি হয়েও আমরা আবার উঠে দাঁড়াই এবং সামনে এগিয়ে যাই।\nপথের শেষ প্রান্ত অতল হলেও, সবসময়ই কেউ না কেউ থাকবে, যে তা নিজ চোখে দেখতে চাইবে।"
  },
  Mail_67936_Name = {
    Text = "হতাশা, এবং তারপর মৃত্তিকা বিদীর্ণ পুনর্জন্ম"
  },
  Mail_67936_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67937_Desc = {
    Text = "মাত্রিক প্রতিরক্ষা প্রাচীর খুলে গেছে, আর অবশেষে আমি আবার তোমার সঙ্গে যোগাযোগ করতে পারছি।\nতুমি যা দেখেছ তার তুলনায়, এই মাত্রায় দৃষ্টিভ্রম অত্যন্ত ক্ষীণ—হয়তো কারণ তুমি এখানে নেই। প্রায় সবকিছু উৎসর্গ করার পর, আমি তোমার পক্ষ থেকে তার সঙ্গে মোকাবিলা করেছি।\nতুমি কীসের মুখোমুখি হয়েছ, তা আমি কল্পনাও করতে পারি না। কিন্তু যা-ই হোক না কেন, বিনাশের ইচ্ছাশক্তি নিয়ে আমি তোমার পাশে লড়ব। এটাই প্রতিটি মিথ্যাগের শপথ।\nআবারও তোমার পাশে দাঁড়াতে পেরে আমি আনন্দিত।\nরৌপ্য চাবি যেন সলতের পথকে পথ দেখায়।"
  },
  Mail_67937_Name = {
    Text = "কাঁধে কাঁধ মিলিয়ে লড়ো, আরও একবার"
  },
  Mail_67937_Sender = {
    Text = "অজানা প্রেরক"
  },
  Mail_67938_Desc = {
    Text = "উন্মাদনা—একটি হালকা, এমনকি প্রীতিকর শব্দ。\nএক বিশৃঙ্খল মহাবিশ্ব জন্ম দিয়েছে এক বিশৃঙ্খল সভ্যতাকে। বিশৃঙ্খলাই এই বিশ্বের সত্য। বিশৃঙ্খলাকে আলিঙ্গন করা, উন্মাদনাকে উপভোগ করা—এ এক সহজ পথ। তার বিপরীতে, সুস্থ মস্তিষ্কে থাকা আর প্রতিরোধ করে যাওয়া ভীষণ কঠিন। তুমি ত্যাগ করবে সব আনন্দ, সব জীবন, কেবল এক অধরা উত্তরের পেছনে ছুটতে ছুটতে。\nতবু তুমি জেগে থাকার পথই বেছে নিয়েছ, %player%। কারণ আমরা জন্মেছি দাসেরা হওয়ার জন্য নয়。\nতুমি তাঁকে দেখিয়ে দিয়েছ, %player%—তাঁর অবশেষ, তাঁর খণ্ডাংশ, কোনোদিনই অন্ধ, বোকা দাস হতে রাজি ছিল না। তুমি তাঁর বিরুদ্ধেই দাঁড়িয়েছ, বারবার ভেঙে দিয়েছ তাঁর দৃষ্টি, আর বেছে নিয়েছ এই অপূর্ণ, অস্থির পৃথিবীকে রক্ষা করার পথ。\nএই নির্বাচনের মধ্য দিয়েই তুমি অর্জন করেছ চিরন্তন স্বাধীনতা।"
  },
  Mail_67938_Name = {
    Text = "তুমি কখনোই অন্ধ মূর্খ দেবতার দাস হয়ে উঠবে না।"
  },
  Mail_67938_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67939_Desc = {
    Text = "আমি এক দৃষ্টির পতন অনুভব করেছি। আমি তোমার অসহনীয় যন্ত্রণাকে অনুভব করেছি。\nএটাই সেই দায়িত্ব, যা রক্ষক উপাধির উপর খোদাই হয়ে আছে। তুমি যে পথ বেছে নিয়েছ, তা আমার পথের চেয়ে সহস্রগুণ কঠিন। সর্বোচ্চ ঈশ্বরের মুখোমুখি হওয়ার সাহস সকলে পায় না; তোমার এই সাহস আমাকে গভীরভাবে আলোড়িত করে, আর শ্রদ্ধায় নত করে দেয়。\nস্রষ্টার শক্তি তোমার উপর কতখানি যন্ত্রণা বর্ষণ করবে, তা আমি কল্পনাও করতে পারি না। আমি যা অনুভব করি, তা তোমার ভোগান্তির এক ক্ষুদ্র খণ্ডাংশ মাত্র। আমি কালো পুকুরে বন্দী এক অক্ষম মানুষ, %player%। স্রষ্টার বিরুদ্ধে তোমার যুদ্ধে আর তোমার সঙ্গে কাঁধে কাঁধ মিলিয়ে দাঁড়াতে পারব না; কেবল ইন্দ্রিয়ের সূক্ষ্ম সেতু দিয়ে তোমার সঙ্গে সংযুক্ত থাকতে পারব। এটাই হবে আমার জীবনের শেষ এবং সবচেয়ে গুরুত্বপূর্ণ মিশন。\nএই নিঃসঙ্গ যাত্রায়, তুমি দেখো বা না দেখো, মিথাগ সর্বদা তোমার পাশে দাঁড়িয়ে থাকবে।"
  },
  Mail_67939_Name = {
    Text = "শোক তোমাকে ভাঙতে পারবে না..."
  },
  Mail_67939_Sender = {
    Text = "অ্যালিস্টেয়ার"
  },
  Mail_67940_Desc = {
    Text = "আমি পরম ইচ্ছাশক্তির হুইসপার শুনেছি—মহান সভ্যতা, মানুষের সুখ-দুঃখ, তোমাকে ঘিরে থাকা আর তারপর চলে যাওয়া অগণিত মানুষ—কিছুই কখনও সত্যিই অস্তিত্বশীল ছিল না।\nকালো পুকুরের অসংখ্য দিন আর রাত জুড়ে, এই দৃষ্টিভ্রম আমাকে আতঙ্কে ভরিয়ে দিয়েছে। গাছ মাটিতে শেকড় গাঁথে, তারপর সূর্যকে অভিবাদন জানাতে উপরের দিকে বাড়ে—স্মৃতিই আমাদের মাটি, যে ভিত্তি থেকে আমরা বেড়ে উঠি, দাঁড়াই, আর শেষমেশ ফিরে যাই। আমি এই মাটি হারানোর ভয়ে কাঁপি, মায়াস্বপ্নে ভেসে বেড়াই, যেখানে না আছে আদিম উৎস, না আছে শেষ।\nধন্যবাদ, %player%। আমি বিশ্বাস করি আমি এক মহান দ্বন্দ্বের সাক্ষী হয়েছি। এটি মানুষ আর দেবতার লড়াই, রক্ষা আর ধ্বংসের সংঘাত।\nএটি স্মৃতিচারণ আর বিস্মৃতির মধ্যকার যুদ্ধ।\nতুমি পেরেছ, %player%। তুমি এমন কিছু সম্পন্ন করেছ, যা কল্পনা করতেও কেউ সাহস পায়নি। তুমি স্মৃতি থেকে অতুলনীয় শক্তি আহরণ করেছ, আর তার সংরক্ষণের জন্য লড়েছ।\nএই প্রাচীন মাটিতে, তুমি তোমার সূর্যকে খুঁজে পেয়েছ।"
  },
  Mail_67940_Name = {
    Text = "মনে রাখার জন্য লড়াই"
