  Mail_68825_Desc = {
    Text = "প্রিয় রক্ষক, \n「Sovereign's Return」 ইভেন্টটি সমাপ্ত হয়েছে। আপনার অবশিষ্ট ইভেন্ট মুদ্রা—「Weary Thoughts」, 「বিষণ্ণ ভাবনা」 এবং 「Joyful Musings」—প্রতিটি 1:1 বিনিময় হারে 「Rose Scrip*40」 এ রূপান্তরিত হবে, তাই অনুগ্রহ করে আপনার ভাণ্ডার পরীক্ষা করতে ভুলবেন না।"
