  Mail_68826_Desc = {
    Text = "প্রিয় রক্ষক, \n「Carnal Desires: Rerun」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট 「প্রাচুর্যের বীজ」 একে এক বিনিময়ে 「Rose Scrip * 40」 হারে রূপান্তরিত হবে। অনুগ্রহ করে পরীক্ষা করতে ভুলবেন না।"
  },
  Mail_68826_Name = {
    Text = "প্রাচুর্যের বীজ রূপান্তরিত"
