  },
  Mail_68898_Desc = {
    Text = "সবচেয়ে সবচেয়ে সবচেয়ে প্রিয় মালিক:\n\nএকজন সর্বগুণসম্পন্ন পরিচারিকা হিসেবে, কারেন মহানুভবদের অনেক অনেক গুরুত্বপূর্ণ দিন মনে রাখতে পারে— ভোজসভার দিন, জন্মদিন, বার্ষিকী থেকে শুরু করে প্রথমবার পোষা প্রাণী কেনার দিন পর্যন্ত, কখনোই একটুও ভুল হয় না। কিন্তু কারেনের নিজের জন্য, স্মরণীয় বিশেষ দিন বলতে শুধু এই একটি দিনই আছে।\nঅনেক অনেক আগে, কারেন যখন রাজপ্রাসাদে দাসী ছিল, প্রথমবার রাঁধুনির কাছে গিয়ে অভিজাতদের অবশিষ্ট মিষ্টির একটুকরো জন্মদিনের কেক হিসেবে চাইতে গিয়ে বকুনি খেয়েছিলাম। সেই রাঁধুনি কেকটা আমার মুখে ছুড়ে মেরেছিল। তখন আমি ভেবেছিলাম, আহা কেক তো এত সুস্বাদু জিনিস! আমাকে অবশ্যই এমন একজন ভালো মালিক খুঁজে নিতে হবে যিনি আমাকে প্রতি বছর জন্মদিনে কেক খেতে দেবেন।\nএখন আমার আছেন অত্যন্ত অত্যন্ত মার্জিত ও উদার লেডি সোরেল, আর অত্যন্ত অত্যন্ত দয়ালু মালিক আপনি— সেদিনের সেই ইচ্ছা এখন পূরণ হয়ে গেছে! কিন্তু মানুষ তো ক্রমশ লোভী হয়ে যায়... আহ না, উন্নতি করে বলতে চাইছি! এখন আমার ইচ্ছা হলো প্রতি বছর জন্মদিনে মালিকের পাশে থাকতে পারা, আর যদি প্রতি বছর ঝকঝকে উপহারও পাই তাহলে তো আরও ভালো।\nএত কিছু শোনার পর, আপনি নিশ্চয়ই আমার জন্য কিছু প্রস্তুত করবেন, তাই না তাই না?\n\nআপনার চিরবিনীত পরিচারিকা\nকারেন"
  },
  Mail_68898_Name = {
    Text = "বছরের পর বছর..."
  },
  Mail_68898_Sender = {
    Text = "কারেন"
  },
  Mail_68899_Desc = {
    Text = "ছোট্ট চারাগাছ:\n\nতোমার ক্রমাগত বেড়ে ওঠা দেখে আমি আরও বেশি নিশ্চিত হচ্ছি যে তোমাকে বেছে নেওয়া, তোমাকে সাহায্য করা—এটাই আমার নেওয়া সবচেয়ে সঠিক সিদ্ধান্ত।\nআমি ফসল কাটার আনন্দ অনুভব করেছি, বিশ্বাস ও ভালোবাসার সকল সেচ আমাকে মধুর প্রতিদান দিয়েছে। তুমিই আমাকে আশা ও ভবিষ্যৎ দিয়েছ।\nএখন আমি বংশবিস্তারের আবেশ ত্যাগ করে, বংশবিস্তারের বাইরে ভালোবাসার ফল উপভোগ করতে মনোনিবেশ করতে পারি।\nএই পৃথিবীর আর ইয়ারান রানির প্রয়োজন নেই, তবে হয়তো একজন সাধারণ নারীর জন্মদিনে প্রিয়জনের সঙ্গ কামনার ইচ্ছাটুকু মেনে নিতে পারে।\nসবচেয়ে সাধারণ প্রেমিক জুটির মতো, একসাথে রান্নার উপকরণ কিনতে যাওয়া, একসাথে সুস্বাদু খাবার রান্না করা, হয়তো আরও অনেক কিছু আছে যা আমি কখনো অনুভব করিনি—তাহলে প্রিয়তম, তুমি কি আমাকে পথ দেখিয়ে একটি উষ্ণ ও সাদামাটা জন্মদিন কাটাতে সাহায্য করবে?\n\nতাইয়িসি"
  },
