  Mail_68900_Desc = {
    Text = "গোপনীয়তা রক্ষাকারী:\n\nমাস্টার ক্যাসিয়া হলেন পৃথিবীর সবচেয়ে অসাধারণ পারফরম্যান্স মাস্টার, যেকোনো অভিব্যক্তি নিখুঁতভাবে অনুকরণ করতে পারেন, কিন্তু মানুষের আবেগ এমন একটি জিনিস যা যেভাবেই চেষ্টা করুন না কেন বোঝা যায় না — এটি পৃথিবীর এক রহস্য।\nআমি অনেক অনেক মানুষকে জিজ্ঞেস করেছি, কেউই আবেগের মূলনীতি স্পষ্টভাবে ব্যাখ্যা করতে পারেনি, যতক্ষণ না আমি ডোরকে জিজ্ঞেস করলাম। সে আমাকে বলল যে পৃথিবীতে মনোবিজ্ঞান নামে একটি বিষয় আছে — যদিও সহানুভূতি অনুভব করা সম্ভব নাও হতে পারে, তবু মনোবিজ্ঞান ভালোভাবে শিখলে সব আবেগের তত্ত্ব আয়ত্ত করা যায়।\nএটা সত্যিই, সত্যিই খুব আকর্ষণীয়! এত দিন ধরে ক্যাসিয়াকে যে সমস্যা জর্জরিত করেছে তা কি অবশেষে সম্পূর্ণরূপে সমাধান হতে চলেছে?\nযাই হোক, আমি তোমাকে জানাতে এসেছি যে এই সপ্তাহের মনোবিজ্ঞানের ক্লাসে আমি তোমার ক্লাসে যোগ দেব। ক্যাসিয়া সিদ্ধান্ত নিয়েছে তোমার পাশে বসবে। আগে যা যা মিস করেছি সেগুলো তোমাকে আমাকে ভালো করে পড়িয়ে দিতে হবে কিন্তু, পাশের বন্ধু~\nআচ্ছা হ্যাঁ, একটা কথা বলতে ভুলে গেছিলাম, আজ আমার জন্মদিন। এখানে আমার খুশি হওয়া উচিত, তোমারও খুশি হওয়া উচিত, তাই না?\nযদি এটা খুবই আনন্দের বিষয় হয়, তাহলে চলো স্কুলে একটা দারুণ হুল্লোড় করি! আমি ক্যাম্পাসকে স্বপ্নের মতো সুন্দর করে সাজিয়ে দেব!\n\nক্যাসিয়া"
  },
  Mail_68900_Name = {
    Text = "মনস্তত্ত্ব..."
  },
  Mail_68900_Sender = {
