  },
  Mail_68901_Desc = {
    Text = "শ্রদ্ধেয় ফ্যাকাশে দূত:\n\nএই এক বছর ধরে আপনার সাহায্য ও যত্নের জন্য ধন্যবাদ। অন্যদের প্রতি আপনার আন্তরিকতা ঠিক পিতৃদেবতার শিক্ষার মতোই মহৎ। যদিও আপনার সাথে দেখা হওয়ার সুযোগ খুব বেশি হয় না, তবু প্রতিবার সাক্ষাতে মনে হয় যেন বহুদিনের পুরনো বন্ধুর সাথে দেখা হচ্ছে, যা আমার মনে বসন্তের হাওয়ার মতো প্রশান্তি এনে দেয়।\nজন্মদিনের দিনটি বিশেষ কিছু না হলেও, বন্ধুর সাথে দেখা করার একটি অজুহাত হিসেবে এটি মনে প্রত্যাশা জাগায়। আপনি ছাড়া এই দিনটি একসাথে কাটানোর জন্য আর কাউকে আমি ভাবতে পারি না।\nআপনি আগ্রহী হলে, আমি আপনাকে আমার সাম্প্রতিক নতুন শখটি অনুভব করার জন্য আমন্ত্রণ জানাতে চাই — মাছ ধরা। অবশ্যই, রান্না বা খাওয়ার জন্য নয়, শুধু নিরবে অপেক্ষা করে ভাগ্যের দেওয়া বিস্ময়কর উপহার পাওয়ার এই প্রক্রিয়াটি উপভোগ করার জন্য। আমি আপনার সাথে এই প্রশান্ত অনুভূতি ভাগ করে নিতে চাই, প্রকৃতির মাঝে গিয়ে, হ্রদের তীরে শান্তভাবে বসে থাকতে চাই।\nএকজন পুরনো বন্ধু, দুটি ছিপ — নিশ্চয়ই এর চেয়ে ভালো দিন আর হতে পারে না।\n\nসালভাদো"
  },
  Mail_68901_Name = {
    Text = "একটি নতুন শখ: মাছ ধরা..."
  },
  Mail_68901_Sender = {
    Text = "সালভাদোর"
  },
  Mail_68902_Desc = {
    Text = "মালিক:\n\nএই বছর জন্মদিনে, এজিস আর জেনকিন আমাকে একটা কাচের উইন্ড চাইম উপহার দিয়েছে যেটা দেখতে অনেকটা ওরিটার মতো।\nআমি এটা ঘরের জানালায় ঝুলিয়ে রেখেছি, বাতাস বইলে এটা থেকে খুব সুন্দর আওয়াজ হয়, আমার মনে পড়ে যায় মা যখন আমাকে কোলে নিয়ে জানালার পাশে বসে গল্প বলতেন সেই সময়ের কথা।\nচিন্তা করবেন না মালিক, যদিও আমি প্রতিদিন মাকে মনে করি, কিন্তু মালিক আর সবাই আমার পাশে আছে বলে লিলি একা অনুভব করে না।\nএখন লিলি নিজে নিজে গল্পের বই পড়তে শিখেছে। প্রতিদিন সন্ধ্যায় কমলা রোদ ঘরে এসে পড়ে, উইন্ড চাইমের উপর পড়ে, গল্পের বইয়ের উপর দুলতে থাকা ঢেউয়ের মতো ছায়া ফেলে, পুরো ঘরটা উষ্ণ হয়ে ওঠে।\nলিলি এই সময়টায় চুপচাপ বসে থাকতে খুব ভালোবাসে, সূর্যাস্তের মেঘ আর উইন্ড চাইমের দিকে তাকিয়ে থাকতে, কী যে সুন্দর লাগে!\nআজ মালিকের যদি সময় থাকে, তাহলে এসো লিলির সাথে একসাথে চুপচাপ বসে থাকো।\n\nলিলি"
  },
  Mail_68902_Name = {
    Text = "কাঁচের বায়ুঘণ্টা..."
  },
  Mail_68902_Sender = {
    Text = "লিলি"
  },
  Mail_68903_Desc = {
    Text = "ছোট্ট বন্ধু:\n\nযদিও এই বিশেষ দিনটি সেই মানুষটির স্মরণে নির্ধারিত হয়েছিল, তবে আমাকে স্বীকার করতেই হবে যে, ছাড়ের দিন ক্রেতা এবং বিক্রেতা উভয়ের জন্যই অত্যন্ত আকর্ষণীয় একটি বিক্রয় পরিকল্পনা।\nগত জন্মদিনে, চিন্তামুক্ত দোকানের লেনদেনের অর্ডার প্রায় স্বাভাবিক সময়ের অর্ধ বছরের বিক্রির সমান ছিল, বিশেষ করে যেসব পণ্য আমি উদযাপনের বিশেষ অফার হিসেবে বের করেছিলাম সেগুলো সব মুহূর্তেই শেষ হয়ে গিয়েছিল। বলব কি মিসাগারের অতিথিরা আমার ব্যবসায় খুবই সহায়ক, নাকি বুদ্ধিমান ও সতর্ক তদন্তকারীরাও ছাড়ের প্রলোভন প্রতিরোধ করতে পারেন না?\nযাই হোক, উভয়পক্ষের আনন্দ অব্যাহত রাখতে, এই বছরও আমার জন্মদিনের উৎসবে ছাড়ের আয়োজন থাকবে। বছরে মাত্র একবার, বিশাল ছাড়, তাড়াতাড়ি কিনুন। আমার হয়ে মিসাগারে ভালো করে প্রচার করতে ভুলো না, মনে রাখার সুবিধার জন্য এই দিনটিকে দ্বৈত দশম দিবস বলা যাক।\nএছাড়াও, আমি তোমার জন্য চুপচাপ কিছু মজার ছোট জিনিস রেখে দিয়েছি, তাড়াতাড়ি আমার সাথে দেখা করতে এসো কিন্তু।\n\nডাফডেল"
  },
  Mail_68903_Name = {
    Text = "মূল্যছাড়ের দিন..."
  },
  Mail_68903_Sender = {
    Text = "ড্যাফোডিল"
  },
  Mail_68904_Desc = {
    Text = "ভাগ্যের মহান আশীর্বাদে, মিসাগার্ড বিশ্ববিদ্যালয়ের গোপনীয়তার রক্ষক, প্রজ্ঞাবান ও দয়ালু প্রভু:\nশুভকামনা!\nযদি প্রতিটি নাইটের আজীবনের ইচ্ছা হয় একজন মহান প্রভুকে অনুসরণ করা, তবে আমার নাইট জীবনে আর কোনো আক্ষেপ নেই।\nআমার জীবনে সৌভাগ্যের পাশাপাশি অনেক দুর্ভাগ্যজনক বিয়োগান্ত ঘটনা ও বীরত্বপূর্ণ রক্তপাতও ছিল, আমি জানি এই কারণে মিসাগার্ডের অনেকেই আমার প্রতি সহানুভূতি অনুভব করেছেন।\nশুধু দুঃখকষ্টের তুলনা বাদ দিলেও, মিসাগার্ডে ইতিমধ্যেই অনেক দুর্ভাগা মানুষ আছেন, এই কষ্টে পরিপূর্ণ পৃথিবীতে রক্ষার জন্য শেষ রক্তবিন্দু পর্যন্ত ঝরানো দুঃখের কিছু নয়। বরং উল্টো, অতীতে হোক বা বর্তমানে, আমি এতে গর্ব অনুভব করি এবং সর্বদা এই দেহ উৎসর্গ করতে প্রস্তুত।\nকিন্তু লেডি লোটান বলেছেন যে আমি প্রতিদিন গম্ভীর মুখে চিন্তা করতে দেখে ক্লান্ত লাগে, তাই জন্মদিনে একটু আনন্দ করতে বলেছেন, এবং জেনকিনকে ডেকে আমাকে খেলা শেখাতে বলেছেন, বলেছেন এতে আমার শৈশব ফিরে আসবে।\nলজ্জার কথা, আমার শৈশব প্রশিক্ষণে ব্যস্ত ছিল, সত্যিই খেলাধুলার কোনো অভিজ্ঞতা ছিল না, ভাবিনি যে পাঁচ বছরের শিশুও যে খেলায় দক্ষ হতে পারে বলে শোনা যায় সেটা এতটা কঠিন হবে, মনে হচ্ছে নাইটের পথের বাইরেও আমার শেখার অনেক কিছু আছে।\nযদি প্রভু আজ অবসর পান, তাহলে কি আমাদের সাথে খেলতে আসতে পারবেন? আমি দেখেছি জেনকিন পরপর দশবার জেতার পর ইতিমধ্যেই বিরক্ত হতে শুরু করেছে, প্রভু এখানে থাকলে নিশ্চয়ই একটি চমৎকার প্রতিদ্বন্দ্বিতা হবে।\n\nওজিয়ের"
  },
