  },
  Mail_68905_Desc = {
    Text = "ওহে:\n\nসেই ক্যালেন্ডারটা পেয়ে, নিশ্চয়ই এবার তুমি মহান গোলকধাঁধার প্রভুর জন্মদিন ভুলে যাওনি।\nআমি তোমাকে আমার ঘরে এসে উপহার দেওয়ার অনুমতি দিচ্ছি, আর সেই সাথে আজকের দিনে আমার সেবায় নিয়োজিত থাকবে।\nযেমন দাঁত মাজা, মুখ ধোয়া, পোশাক পরিবর্তন, খাবার পরিবেশন, আর ঘর পরিষ্কার করা, চাদর বদলানো — তোমাদের একটা শব্দ আছে না, কী যেন, মহাপরিচ্ছন্নতা!\nহ্যাঁ, এই মহাপরিচ্ছন্নতার সব কাজ তোমার উপর ন্যস্ত, আমি এসব গৃহস্থালি কাজে একদম ক্লান্ত হয়ে গেছি। আজ যেভাবেই হোক, আমি রোমে কাটানো সেই পুরনো দিনগুলোতে ফিরে যেতে চাই, যেখানে হাত বাড়ালেই পোশাক আর মুখ খুললেই খাবার — সেই জীবন উপভোগ করতে চাই।\nআজ কেউই আমাকে দিয়ে একটুও কাজ করাতে পারবে না, কেউই না!\n\nআগ্রিপ্পা"
  },
  Mail_68905_Name = {
    Text = "অতীতে প্রত্যাবর্তন…"
  },
  Mail_68905_Sender = {
    Text = "অ্যাগ্রিপা"
  },
  Mail_68906_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nসময় কত দ্রুত চলে যায়, কে ভেবেছিল যে সেই জীবন যা আমি মনে করতাম মৃত্যু পর্যন্ত চলবে, এখন আমি প্রায় মনেই করি না।\nএখন এই মহীয়সী এই ক্যান্টিনের সব ছোট কেক সম্পর্কে সবকিছু জানে, ওই অকেজো বাবুর্চিদের যতই তাড়া দিই, তারা আর কোনো নতুন কিছু বানাতে পারে না।\nতাই নতুন বছরে, আমার খাদ্য মানচিত্র আরও বড়, আরও দূরে ছড়িয়ে যাবে। প্রথমে একটা ছোট লক্ষ্য ঠিক করি: লন্ডিনিয়ামের সব কেকের দোকানের কেক খেয়ে দেখা।\nআর লাইনে দাঁড়িয়ে কেক আনার গৌরবময় কাজটা তো তোমার ওপরেই থাকবে! এই মহীয়সীর আস্থা পেয়ে তোমার বেশি খুশি হওয়ার দরকার নেই, শুধু কৃতজ্ঞচিত্তে এই ভদ্রমহিলার নাম জপ করলেই চলবে।\nযাই হোক, সেই বোকা বাবুর্চিরা কিছুটা আন্তরিকতা তো দেখিয়েছে, তাদের ফিসফিস কথাবার্তা থেকে আমি শুনতে পেয়েছি যে তারা মনে হয় একটা বিশাল দশ স্তরের কেক তৈরি করছে — হা, তারা এখনও চমক লুকাতে পারে না।\nসৃজনশীলতা একটু পুরনো ধাঁচের হলেও, হয়তো এবারের জন্মদিনের অনুষ্ঠানে আমি আরও কিছু মানুষকে আমন্ত্রণ জানাতে পারি, যেমন এই বছরে পাওয়া নতুন বন্ধুদের।\nমিসাগ্রাসে এই মহীয়সীর প্রথম বন্ধু হিসেবে, আমি তোমাকে আমার হয়ে কেকে প্রথম কাটা দেওয়ার অনুমতি দিচ্ছি।\n\nমারফি"
  },
  Mail_68906_Name = {
    Text = "দশ-স্তরের কেক..."
  },
  Mail_68906_Sender = {
    Text = "মার্ফি"
  },
  Mail_68907_Desc = {
    Text = "প্রিয় রহস্যরক্ষক:\n\nতোমার মতো বুদ্ধিমান কেউ নিশ্চয়ই মিসাগের জাদুকরী আর্কাইভ থেকে এই তথ্যটি ইতিমধ্যেই জেনে গেছ — আজকের দিনটি 「ভাগ্যবান গোয়েন্দা」-র জীবনে একটি স্মরণীয় দিন।\nজন্ম, প্রথম ব্ল্যাকজ্যাক জেতা, শততম ঘোড়দৌড় জেতা, প্রথম বদ্ধঘর হত্যা মামলা সমাধান, মৃত্যু বয়ে আনা ব্যর্থতা — সবকিছুই ঘটেছিল এই জাদুকরী ৬ই জুনে।\nতাহলে, আমার সাথে একটা ডাবলস ব্রিজ খেলবে নাকি? আজকের এই দিনটিকে আরও স্মরণীয় করে তুলি, কেমন?\n\nলেক"
  },
  Mail_68907_Name = {
    Text = "এক রাউন্ড হয়ে যাক?"
  },
  Mail_68907_Sender = {
    Text = "রাইকার"
  },
  Mail_68908_Desc = {
    Text = "এই চিঠি কোনো শুভেচ্ছা নয়, বরং একটি সতর্কবার্তা——আমাকে নিয়ন্ত্রণ করার চেষ্টা কোরো না, আমাকে শিকলে বাঁধার চেষ্টা কোরো না।\nআমি কেবল আমার নিজের।\nআমি সেই আমার মতো দেখতে লোকটার মতো নই, যে এখনও মানুষ ও পৃথিবীর প্রতি শিশুসুলভ প্রত্যাশা পোষণ করে।\n\nযে কেউ আমার \"মালিক\" হওয়ার ধৃষ্টতা দেখাবে, তাকে আমি হত্যা করব—কথা দিলাম।\n\nH"
  },
  Mail_68908_Name = {
    Text = "আমি যার..."
  },
  Mail_68908_Sender = {
    Text = "হেলট: ক্যাটেনা"
  },
  Mail_68909_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nহয়তো আমি আপনাকে আগেই জলের প্রতি আমার ভালোবাসার কথা বলেছিলাম। কোলাহলপূর্ণ মানবজগতের তুলনায়, জলের নিচের পৃথিবী কতটা শান্ত ও নিরুপদ্রব।\nআমি জলজ উদ্ভিদ আর প্রবালের মাঝে ভেসে বেড়িয়েছি, মাছের ঝাঁকের সাথে কথা বলেছি। জলের উপরিভাগ থেকে যত দূরে যাওয়া যায়, জলের রঙ তত গাঢ় অন্ধকার হয়ে আসে। ঢেউয়ের মৃদু ধাক্কায় জলের তলদেশ থেকে আকাশের দিকে তাকালে, সেই ছায়া-আলোর বিচিত্র রঙের খেলা এক মোহনীয় দৃশ্য তৈরি করে — আমার হৃদয়ে এটাই সবচেয়ে সুন্দর দৃশ্য।\nআপনি কি জানেন? কিছু সামুদ্রিক প্রাণী মানুষের চেহারা মনে রাখতে পারে। আপনি আবার গেলে, এই \"বন্ধুরা\" উৎসাহের সাথে কাছে এসে স্বাগত জানায়। যেমন আমার পরিচিত একটি বুদ্ধিমান ছোট অক্টোপাস আছে, আর একটি হালকা হলুদ রঙের সামুদ্রিক মাছ।\nজন্মদিনের এই দিনে, আমি আবার জলের নিচের পৃথিবীর কথা মনে করছি। আপনি কি আমার সাথে একবার ডুব সাঁতার দিতে রাজি হবেন? আমি আন্তরিকভাবে চাই এই শান্ত জগৎ এবং আমার অদ্ভুত বন্ধুদের সাথে আপনাকে পরিচয় করিয়ে দিতে।\n\nনিমফিয়া"
  },
  Mail_68909_Name = {
    Text = "জলতলের জগৎ..."
  },
  Mail_68909_Sender = {
    Text = "নিম্ফিয়া"
  },
  Mail_68910_Desc = {
    Text = "গোপনরক্ষক:\n\nতুমি মিসাগে আসার পর থেকে, আমি তোমার সাথে সম্পর্কিত বিষয়গুলো শিশু লালন-পালনের পদ্ধতিতে সামলাতে অভ্যস্ত হয়ে গেছি, এবং তোমার সাধারণ প্রতিক্রিয়া দেখে বলতে পারি, তোমার দুর্বলতা আমার প্রত্যাশাকেও ছাড়িয়ে গেছে।\nতবে তোমার শিক্ষক ও প্রথম অভিভাবক হিসেবে, আমি খুশি যে এই এক বছরে তোমার জন্য ঝামেলা সামলানো এবং পরিস্থিতি সামাল দেওয়ার ঘটনা ক্রমশ কমে এসেছে। যদিও তুমি যখন প্রথম ভর্তি হয়েছিলে তখন তোমার মাথা সম্পূর্ণ ফাঁকা দেখে সত্যিই হতাশ লাগছিল, কিন্তু তোমার বৃদ্ধির গতি সত্যিই প্রতিভা ও পরিশ্রম দুটোরই সমন্বয় বলা চলে।\nঅভিনন্দন, তুমি এখন একজন যোগ্য গোপনরক্ষক হয়ে উঠেছ, আমার প্রত্যাশা তুমি জলাঞ্জলি দাওনি।\nআমার জন্মদিনের মতো এরকম একটি সাধারণ দিনে, আমি তোমার জন্য একটি সফল গোপনরক্ষকের উপযুক্ত উপহার প্রস্তুত করে রেখেছি——অ্যালিস্টেয়ার একসময় যে বিশেষ প্রশিক্ষণ পরিকল্পনা ব্যবহার করেছিলেন, কেমন, উত্তেজিত হচ্ছ তো?\nজিজ্ঞেস করো না কেন আমি তোমাকে উপহার দিচ্ছি, পরীক্ষাগারে ঢুকতে না পারার দিনগুলোতে কিছু একটা করার দরকার তো, তাই না।\nতুমি প্রস্তুত হলে, প্রশিক্ষণ কক্ষে আমার কাছে এসো।\n\nডোর"
  },
  Mail_68910_Name = {
    Text = "একটি উপহার..."
  },
  Mail_68910_Sender = {Text = "ডল"},
  Mail_68911_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nএকজন নৃত্যশিল্পীর কাছে এক বছর মানে কেবল কয়েক হাজার ঘূর্ণন, কয়েক হাজার লাফ। আমার দীর্ঘদিনের সঙ্গী নাচের জুতো জোড়া বদলানো ছাড়া, সবকিছু যেন অপরিবর্তিত রয়ে গেছে, আবার সবকিছু যেন কোথাও বদলে গেছে।\nআগে যে একাকীত্বে অভ্যস্ত ছিলাম, তার তুলনায় এই এক বছরে আমি সবসময় পেয়েছি একজন বিশ্বস্ত দর্শক, একজন কিছুটা আনাড়ি নাচের সঙ্গী।\nযখনই তুমি নাচের ঘরে বসে থাকো, আমি অনুভব করি আমার শরীর আরও হালকা হয়ে যাচ্ছে, ঠিক যেন শৈশবে যখন সবে নাচ শিখতে শুরু করেছিলাম, সেই অব্যাখ্যেয় আবেগ আর উদ্দীপনায় ভরপুর।\nহয়তো আমি নিজে যতটা বিশুদ্ধ ও মহৎ ভেবেছিলাম ততটা নই। সারাজীবন নৃত্যের জন্য উৎসর্গ করার পাশাপাশি, আমি তোমার দৃষ্টিও পেতে চাই, তোমার করতালি শুনতে চাই।\nজন্মদিনের এই দিনে আবহাওয়া খুব সুন্দর, আমি আন্দাজ করতে পারছি আজ রাতের তারার আকাশ খুবই স্বচ্ছ হবে। আমার সবচেয়ে উৎসাহী দর্শক, আমার একান্ত নাচের সঙ্গী, তুমি কি আমার সাথে সেই সুন্দর হ্রদের বনে যেতে চাও, চাঁদ আর তারাদের জন্য একটি নৃত্য করতে?\n\nলিজ"
  },
  Mail_68911_Name = {
    Text = "একচেটিয়া নৃত্যসঙ্গী…"
