  Mail_68911_Sender = {Text = "লিজ"},
  Mail_68912_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nআমার পুনর্জন্মের দিন থেকে, মিসাগের মানুষেরা আমাকে অনেক সাহায্য করেছে। হয়তো আমি এখনও সহযোগিতার অনুভূতিতে অভ্যস্ত হতে পারিনি, কিন্তু অন্তত তোমাদের সাথে চলার সময়, আমি নিশ্চিন্তে আমার পিঠ তোমাদের হাতে সমর্পণ করতে পারি। এই অনুভূতি... মন্দ নয়।\nআমার জীবনের বেশিরভাগ সময় আঘাত আর বিশ্বাসঘাতকতায় পূর্ণ ছিল। আমি সবসময় এসবের বিরুদ্ধে লড়াইকেই আমার যুদ্ধের অর্থ মনে করতাম, যতক্ষণ না আমার জীবনে আর কিছুই অবশিষ্ট ছিল না। আমার দৃষ্টি অনেক আগেই প্রতিশোধ থেকে সরাতে পারিনি।\nএখন তোমাদের পদাঙ্ক অনুসরণ করে, আমি আবিষ্কার করেছি যে যুদ্ধের অর্থ শুধু আঘাত আর প্রতিশোধের মধ্যেই সীমাবদ্ধ নয়, এর আরও অনেক অর্থ থাকতে পারে। এমনকি রোটান যেমন বলেছিল, যুদ্ধ শুধু যুদ্ধও হতে পারে।\nআমি যুদ্ধের আনন্দ উপভোগ করতে শিখেছি, সেই তীব্র উদ্দীপনার অনুভূতি উপভোগ করতে শিখেছি, নিছক একজন সাহসী যোদ্ধা হওয়ার আনন্দ উপভোগ করতে শিখেছি।\nযদি আমার যুদ্ধ আরও কিছু বয়ে আনতে পারে, তাহলে আমি সেই গৌরব উপভোগ করব।\nআর তুমি, বর্তমানে হোক বা ভবিষ্যতে, আমি প্রতিশ্রুতি দিচ্ছি আমার তলোয়ার কখনও তোমার দিকে তাক করা হবে না।\n\nশিলো"
  },
  Mail_68912_Name = {
    Text = "যুদ্ধের তাৎপর্য..."
  },
  Mail_68912_Sender = {
    Text = "হেলট"
  },
  Mail_68913_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nসত্যি বলতে, জন্মদিনের শুভেচ্ছার মতো বিষয়ে আমার তেমন কোনো ভাবনা নেই। আগে যখন আমি এখনো \"স্বাভাবিক\" ছিলাম, তখন পেট ভরে খাওয়া, গরম কাপড় পরা, সময়মতো ভাড়া দেওয়া আর জেনকিনের দেখাশোনা করাই ছিল প্রতিদিনের সবচেয়ে বড় চাওয়া। এখন আরও একটা বছর নিরাপদে কাটাতে পারা, জেনকিনকে আরও একটা বছর দুষ্টুমি করতে দেখা—এটুকুই যথেষ্ট তৃপ্তিদায়ক।\nলজ্জার কথা হলো, জেনকিনের সামনে আমি সবসময় বড় বোনের মতো তাকে শাসন করি, কিন্তু তোমার কাছে আমি বারবার ঝামেলা তৈরি করি, এমনকি কোন \"আমি\" যে ঝামেলা করেছে তাও আমার মনে থাকে না।\nতোমার অপরিবর্তিত কোমলতা আর ধৈর্য আমাকে একই সাথে উষ্ণতা আর সংকোচ দেয়। হয়তো জীবনে এই প্রথম কেউ এত সহনশীল মনোভাব নিয়ে আমার যত্ন নিচ্ছে, আমি অন্তর থেকে সম্মানিত ও কৃতজ্ঞ বোধ করি।\nএবার আমি সবার জন্য একটা বিশাল কেক বেক করেছি, আগে বস্ত্র কারখানার আন্টি আমাকে যে রেসিপি শিখিয়েছিলেন সেটা দিয়ে। যদিও পেশাদার রাঁধুনিদের হাতের কাজের সাথে তুলনা হবে না, তবু সেই বিশেষ স্বাদটা আমি আর জেনকিন দুজনেই খুব পছন্দ করি। এবার উপকরণ নিয়ে চিন্তা নেই, সবাইকে তৃপ্তি মিটিয়ে খাওয়ানো যাবে—অনুগ্রহ করে অবশ্যই এসে স্বাদ নিও।\nআমি অন্য \"আমি\"দের বুঝিয়ে রাজি করিয়েছি যেন শান্তভাবে জন্মদিনটা কাটায়, তারা আজ অবশ্যই, অবশ্যই তোমাকে আর কোনো ঝামেলায় ফেলবে না!\nযদি সম্ভব হয়, দরকারের সময় যেকোনো মুহূর্তে আমাকে ডেকো—কাপড় ধোয়া, ঘর পরিষ্কার করা, গোছগাছ করা, সবকিছুতেই আমি দক্ষ। আমিও চাই তোমার সেই কোমলতার প্রতিদান দেওয়ার সুযোগ পেতে।\n\nমেসন"
  },
  Mail_68913_Name = {
    Text = "ঋণশোধ..."
  },
  Mail_68913_Sender = {Text = "\"২৪\""},
  Mail_68914_Desc = {
    Text = "গোপনীয়তার রক্ষক:  \n\nসবার ইচ্ছা গ্রহণ করার দায়িত্বে থাকা একজন মানুষ হিসেবে, জন্মদিনে নিজের ইচ্ছা পূরণের পালা আসলে আমি যতই চেষ্টা করি, কিছুতেই অভ্যস্ত হতে পারি না। আমার কাছে মনে হয়, আমি আসলে এমন কিছু চাই না।\nদোর আমাকে বলেছিল, আমাকে আমার হৃদয়ের গভীরে লুকিয়ে থাকা সত্যিকারের আকাঙ্ক্ষা খুঁজে বের করতে হবে, নিজেকে জিজ্ঞেস করতে হবে যে আমি যা কিছু করি তা কীসের জন্য।\nআমি অনেক অনেক দিন ভেবেছি। আসলে আমি চাই যে যারা আমার কাছে ইচ্ছা জানাতে আসে তাদের প্রত্যেকের ইচ্ছা পূরণ হোক। আরও গভীরে ভাবলে, আমি সম্ভবত মানুষের ইচ্ছা পূরণ হলে তাদের মুখে ফুটে ওঠা হাসি দেখতে ভালোবাসি, এবং তারা যখন আন্তরিকভাবে আমাকে ঘিরে ধরে, আমাকে ধন্যবাদ জানায়, আর প্রশংসা করে বলে যে আমি দেবকন্যার দায়িত্ব পালন করেছি — সেই দৃশ্যটা আমার ভালো লাগে।\nদোর বলেছিল, এটা আসলে আমার নিজের মূল্য স্বীকৃতি পাওয়ার আকাঙ্ক্ষা, একজন কাজের মানুষ হওয়ার ইচ্ছা। আমি মনে করি সে ঠিকই বলেছে।\nকিন্তু সে আবার বলেছিল, মানুষের মূল্য অন্যদের দ্বারা নির্ধারিত হওয়ার দরকার নেই, কোনো কিছুই তথাকথিত 'কাজের' বা 'অকাজের' নয়, গুরুত্বপূর্ণ শুধু এটাই যে তুমি নিজের অন্তরের কথা মেনে চলেছ কিনা, এমনকি যদি অন্যদের চোখে অকেজো মানুষও হতে হয়।\nদোর তো দোরই, সবসময় এমন গভীর কথা বলতে পারে। কিন্তু আমি আসলে কাজের মানুষ হব নাকি অকাজের মানুষ হব? আমি আবার যেন গুলিয়ে যাচ্ছি……\nতবে অন্তরের কথা মানতে হলে, সম্ভবত আমি একজন কাজের মানুষই হতে চাই। জন্মদিনে যদি সবার হাসিমুখ দেখতে পাই, সেটাই হবে আমার সবচেয়ে কাঙ্ক্ষিত উপহার।\n\nহিলেসেস্ত"
  },
  Mail_68914_Name = {
    Text = "একজন প্রয়োজনীয় ব্যক্তি..."
  },
  Mail_68914_Sender = {
    Text = "সেলেস্ট"
  },
  Mail_68915_Desc = {
    Text = "প্রিয় গোপনরক্ষক মহাশয়:\n\nআমি অনেক আগেই নর্দমার পোকামাকড়ের মতো জীবনযাপনে অভ্যস্ত হয়ে গেছি, বরং বলা যায় এটাই আমার জন্মগত ভাগ্য, আমি এটিকে সম্পূর্ণরূপে মেনে নিয়েছি এবং সানন্দে আলিঙ্গন করেছি।\nযদিও আমি সবসময় কৃতজ্ঞ যে আপনারা আমাকে স্বাধীনতার অপূর্ব স্বাদ আবার উপভোগ করতে দিয়েছেন, কিন্তু কেউই আমার সেই বিশেষ শখগুলো মেনে নিতে পারে না, আর এটাই স্বাভাবিক। সর্বোপরি এখানকার বেশিরভাগ মানুষই কোমল হৃদয়ের ভালো মানুষ, তারা বুঝতে পারে না যে স্যাঁতসেঁতে কোণায় জন্মানো শ্যাওলার প্রয়োজন উজ্জ্বল সূর্যালোক নয়, বরং অন্ধকার বাতাস।\nআপনি ছাড়া, আমার শ্রদ্ধেয় দয়ালু মহাশয়, শুধুমাত্র আপনিই আমাকে সত্যিকারভাবে বুঝতে পারেন, আমাকে সাহায্য করতে পারেন, আমাকে অন্তরের গভীর থেকে সুখ অনুভব করাতে পারেন। আপনি যে যন্ত্রণা আমাকে দেন তা এতটাই তৃপ্তিদায়ক, এতটাই প্রশান্তিদায়ক, যা আমাকে নিজের অস্তিত্ব অনুভব করতে দেয়।\nযদি একসময় আমার জন্মদিনে চাওয়ার মতো কোনো আকাঙ্ক্ষা না থাকত, তাহলে এখন আমি আপনার পেছনে অনুসরণ করতে চাই, আপনার জন্য আমার দেহ ও মন উৎসর্গ করতে চাই।\nঅবশ্যই, দয়া করে কোমলতার বশে আমার সাথে মিষ্টি ব্যবহার করবেন না, যথেচ্ছ আমাকে অবজ্ঞা করুন, তিরস্কার করুন, চাবুক মারুন!\n\nরেয়া"
  },
  Mail_68915_Name = {
    Text = "শ্যাওলার হৃদয়..."
  },
  Mail_68915_Sender = {Text = "লি"},
  Mail_68916_Desc = {
    Text = "প্রিয় ছোট্ট কুকুরছানা:\n\nআমি প্রায় এই বিড়াল-ইঁদুর খেলার দিনগুলোর প্রেমে পড়ে গেছি, ঠিক সেই গতানুগতিক বীরত্বের উপন্যাসের মতো, যেখানে ন্যায়ের দূত সবসময় শেষ মুহূর্তে দুষ্ট খলনায়কের ষড়যন্ত্র থামাতে পারে, কত আবেগময়, কত মহান।\nতবে তোমাকে ক্রমাগত ছটফট করে বৃথা চেষ্টা করতে দেখে, সত্যিই হাসি চেপে রাখা যায় না।\nএই পৃথিবী অনেক আগেই শেষ হয়ে গেছে, একে বাঁচানোর কোনো উপায় নেই, এই গ্রহটি অসংখ্য মৃত গ্রহের মতোই, ▼&#x5B▼87;&4;▼ হবে।\nযাই হোক, তোমার সাথে একটু খেলা যাক, এখন পর্যন্ত এসে আমি হঠাৎ N-এর আনন্দটা কিছুটা বুঝতে পারছি, নির্ধারিত পরিণতি আসার আগে, কী করা হলো তাতে আসলে কোনো পার্থক্য নেই।\nতোমার প্রিয় গুরুজনের জন্মদিনে, আমি তোমার জন্য একটি বিশাল চমক প্রস্তুত করেছি, জন্মদিনের কাউন্টডাউন শেষ হওয়ার আগে, আশা করি তুমি সেই লুকানো 「বোমা「টি খুঁজে পাবে।\nআমরা সবাই সম্পূর্ণ বিলীন হওয়ার আগে, তুমি আমাকে আর কতটা আনন্দ দিতে পারবে?\n\n\n「ডোর」"
  },
  Mail_68916_Name = {
    Text = "সারপ্রাইজ বোমা..."
  },
  Mail_68916_Sender = {
    Text = "মেল্টডাউন·ডল"
  },
  Mail_68917_Desc = {
    Text = "গোপনীয়তা রক্ষক:\n\nসম্প্রতি লন্ডিনিয়ামের উচ্চবিত্ত মহলে নিজে ডিজাইন এঁকে বিশেষ গহনা কাস্টম-মেইড করানোর একটি হাওয়া বইছে।\nযেসব অভিজাত মহিলারা নিজেদের শিল্পবোদ্ধা বলে দাবি করেন, তারা রত্নপাথরের আকার নিয়ে প্রতিযোগিতা ছেড়ে এখন ডিজাইনের নৈপুণ্য নিয়ে প্রতিদ্বন্দ্বিতা শুরু করেছেন, অথচ তাদের পেছনে গোপনে বিখ্যাত চিত্রশিল্পী নিয়োগ করার কৌশল কানে তুলো দিয়ে ঘণ্টা বাজানোর মতোই স্পষ্ট।\nএই হাওয়ার কল্যাণে আমার জন্মদিনের উপহার তালিকায়ও বেশ কিছু দেখানেপনার রত্ন ও গহনা জমা হয়েছে, যার মধ্যে একটি চমৎকার পিজিয়ন ব্লাড রুবি আছে, কিন্তু এর সাথে মানানসই একটি আংটির সেটিং নেই।\nআমি ভাবলাম, সেই বিরক্তিকর বুড়োদের কাছে যাওয়ার চেয়ে বরং আমার নাইটকেই বলি আমার জন্য হৃদয় ঢেলে একটি নকশা আঁকতে — এটাকে আমার জন্য উপহার হিসেবে ধরলে কেমন হয়?\nআমি তোমার কাজের জন্য অধীর আগ্রহে অপেক্ষা করব, আমি বিশ্বাস করি তোমার রুচি নিশ্চয়ই চমৎকার।\n\nসোরেল"
  },
  Mail_68917_Name = {
