  Mail_68918_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nতোমার সাথে প্রথম সাক্ষাতের আগে, অসংখ্য দ্বারের আড়ালে, আমি ইতিমধ্যেই অগণিত একই রকম অথচ ভিন্ন তোমাকে দেখেছি।\nআমি তোমার সুখ-দুঃখ, আনন্দ-ক্রোধ মনে রাখি, তোমার প্রতিটি পছন্দ মনে রাখি, বিভিন্ন জগতে তুমি কীভাবে এগিয়ে চলেছ তাও মনে রাখি।\nআমার কাছে, এত অসংখ্য তোমার মধ্যে, তুমিই সবচেয়ে বিশেষ। আমি যে জগতগুলো পর্যবেক্ষণ করেছি, সেগুলোকে মনে মনে নাম ও নম্বর দিয়েছি। তোমার জগতকে আমি নাম দিয়েছি \"আশা\", আর এই নামটি রেখেছিলাম তোমার সাথে দেখা হওয়ার সেই দিনে।\nএই \"আশা\" নামের দিনে, আমার মনে হয় তুমি হয়তো অন্যান্য জগতগুলো দেখতে আগ্রহী হবে। মহাবিশ্বের চোখ দিয়ে অনুভব করার মতো, আমি তোমাকে নিয়ে যাব, দ্বারের সামনে দাঁড়িয়ে আমি যা কিছু নীরবে দেখেছি তা দেখাতে।\nআর আমার চোখে তুমি কেমন, তাও দেখাতে।\n\nতাভি"
  },
  Mail_68918_Name = {
    Text = "এক অন্য তুমি..."
  },
  Mail_68918_Sender = {
    Text = "তাবিল"
  },
  Mail_68919_Desc = {
    Text = "মূলত মিসাগের সংক্ষিপ্ত ও সরল কর্মপদ্ধতি আমার মনে ধরেছিল, কিন্তু সেই মিরিয়াম নামের মহিলাটি আসার পর থেকে আমার জীবনে শান্তি বলে কিছু রইল না।\nযারা স্থিতিশীলতা ও আশ্রয় খুঁজছে, আমি তাদের প্রত্যাখ্যান করি না। এই অশান্ত পৃথিবীতে সান্ত্বনা খোঁজা জীবের স্বাভাবিক প্রবৃত্তি, এতে দোষের কিছু নেই।\nকিন্তু আমি কখনোই নিজেকে সর্বশক্তিমান দেবতা হিসেবে উপস্থাপন করতে পছন্দ করিনি, তাছাড়া লেমুরিয়া ডুবে যাওয়ার পর এখানে আর একজন উচ্চাসনে বসা দেবতা তৈরির প্রয়োজনও নেই।\nমিরিয়াম সম্ভবত অতীতের ছায়া থেকে এখনও বেরিয়ে আসতে পারেনি, তাই সেই অন্ধবিশ্বাসের রীতিনীতি এখানেও চালু করেছে। এর ফলে ক্যাম্পাসের যেখানেই যাই, সবার দৃষ্টি আমার ওপর পড়ে, এমনকি জড়িয়ে-পেঁচিয়ে ধরে—সত্যিই বিরক্তিকর।\nআজ জন্মদিন, নিশ্চয়ই সেই মহিলা আগে থেকেই জাঁকজমকপূর্ণ অনুষ্ঠানের আয়োজন করে রেখেছে। শুনলে কান ঝালাপালা, দেখলে মাথা ব্যথা—তাই সেখানে গিয়ে ঝামেলায় জড়াব না।\nযদি তোমার ইচ্ছা থাকে, চিঠির সাথে সংযুক্ত ঠিকানায় এসো, আমার সাথে হাঁটতে হাঁটতে মন শান্ত করো।\nমনে রেখো, সেই মহিলাকে জানতে দিও না।\n\nতুলু"
  },
  Mail_68919_Name = {
