  Mail_68920_Desc = {
    Text = "আমি প্রতিদিন অসহ্য ক্ষুধায় ভুগি, একটু সময়ও রক্ত না পান করলে কষ্ট হয়। কিন্তু তোমার রক্তের স্বাদ পাওয়ার পর থেকে, সেসব সাধারণ রক্তখাদ্য আমার মুখে মোমের মতো বিস্বাদ লাগে, আর তোমার রক্তের সেই অপূর্ব স্বাদ প্রতিদিন আমার গলায় ফিরে ফিরে আসে, আমাকে প্রলুব্ধ করে।\nআমি জানি একজন মানুষকে পুরো শুষে নিলে কতটুকু রক্ত পাওয়া যায়, সেই সুস্বাদু মুহূর্ত বলতে গেলে চোখের পলকেই শেষ হয়ে যায়। তোমাকে যাতে খুব তাড়াতাড়ি মরতে না হয়, তাই আমি ক্ষুধা সহ্য করতে শিখব, পরবর্তী সুস্বাদু মুহূর্তের জন্য অপেক্ষা করতে শিখব, যতদিন না আবার তোমার তাজা রক্তের স্বাদ পাই।\nহা, হায় ঈশ্বর, বিশ্বাসই হচ্ছে না যে আমি সত্যিই এটা করতে পেরেছি, আমার নিজেরই সন্দেহ হচ্ছে আমি কি ইতিমধ্যে বিবর্তিত হয়ে গেছি। আমার এত ধৈর্য ধরার কথা ভেবে, অন্তত এই তথাকথিত জন্মদিনের দিনটিতে, আমাকে একবার তোমার মিষ্টি সুস্বাদু রক্তের স্বাদ নিতে দাও না, শুধু একটুখানি, কেমন?\nআমি ট্রাউট ক্লাবে উপার্জিত টাকা দিয়ে তোমার জন্য পুষ্টি সম্পূরক কিনেছি, এবার তুমি আর নিশ্চয়ই রক্তস্বল্পতায় ভুগবে না।\n\nঅনেকদিন ধরে ক্ষুধার্ত ইউউহাশি"
  },
  Mail_68920_Name = {
    Text = "সুস্বাদু রক্ত..."
  },
  Mail_68920_Sender = {
    Text = "উভহাশ"
  },
  Mail_68921_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nএই এক বছরে প্রশিক্ষণ ক্লাসে তোমার ক্রমাগত উন্নতি দেখে আমি অত্যন্ত আনন্দিত। খুব শীঘ্রই তুমি আমার তরুণ বয়সকেও ছাড়িয়ে একজন দুর্দান্ত সৈনিক হয়ে উঠবে। তোমার প্রশিক্ষণ প্রশিক্ষক হতে পেরে আমি সত্যিই গর্বিত।\nএই বছর জন্মদিনে আমি পাহাড়ে চড়ার জন্য উপযুক্ত এক জোড়া লম্বা বুট উপহার পেয়েছি। তুমি কি আমার সাথে একটা হাইকিংয়ে যেতে আগ্রহী? নিজের বেড়ে ওঠা শারীরিক সক্ষমতা যাচাই করতে পারবে, আর সেই সাথে পাহাড়ের চূড়া থেকে সূর্যোদয় দেখতে পারবে। পর্বতমালার মাঝে শহর থেকে দূরে সেই দৃশ্য নিশ্চয়ই অপূর্ব সুন্দর হবে।\nঅবশ্য, যদি পাহাড়ে ক্যাম্পিং করে পিকনিকও হয়, সাথে ঠান্ডা তাড়ানোর জন্য এক বোতল কড়া মদ থাকে, তাহলে তো আরও নিখুঁত হবে।\n\nএলভা"
  },
  Mail_68921_Name = {
    Text = "পদব্রজ ভ্রমণ..."
  },
  Mail_68921_Sender = {
    Text = "আলভা"
  },
  Mail_68922_Desc = {
    Text = "পার্টনার:\n\nএই এক বছরে অনেক কিছু ঘটেছে, হয়তো তোমার কাছে এটা খুব সুন্দর একটা ক্যাম্পাস জীবন ছিল না।\nআমি স্বীকার করি, গত এক বছরে আমি তোমাকে অনেক বেশি চাপ দিয়েছি, আর যত্নের ক্ষেত্রে একটু কম মনোযোগী ছিলাম। সব প্রশিক্ষণই যেন একটু তাড়াহুড়ো করে করানো হয়েছে, তোমার ওপর একসাথে অনেক বেশি বোঝা চাপিয়ে দিয়েছি।\nকিন্তু আমি চাই তুমি জানো, তুমি আমার হৃদয়ে সবসময় সবচেয়ে গুরুত্বপূর্ণ মানুষ। মিসাগের গোপনীয়তা রক্ষাকারীদের বাইরে, তুমি আমার একমাত্র পার্টনার।\nহয়তো আজকের দিনে, আমি বলতে চাইছি শুধু জন্মদিনের এই একটা দিনে, আমি একটু জেদি হওয়ার চেষ্টা করতে পারি, আর তুমিও সব দায়িত্ব ভুলে যেতে পারো। আমাদের কোনো অ্যাসাইনমেন্ট বা প্রশিক্ষণের কথা ভাবতে হবে না, চলো মনের আনন্দে একটু বিশ্রাম নিই।\nশহরের অ্যামিউজমেন্ট পার্কে যাবে? থিয়েটারে? ডিপার্টমেন্ট স্টোরে নাকি রাস্তার বাজারে……যেকোনো কিছুই হোক, আমি তোমাকে যা দিতে পারিনি তা যতটা সম্ভব পুষিয়ে দিতে চাই।\nএকইসাথে, আমিও চাই এই কোনো কিছু না ভাবার দিনটায় তুমি আমার পাশে থাকো, সব পরিকল্পনা তুমিই ঠিক করো।\n\nরামোনা"
  },
