  Mail_68923_Desc = {
    Text = "প্রিয় গোপনীয়তার রক্ষক:\n\nমানবজগতে আমার কাটানো বছরগুলোতে, আমার সেই প্রিয় সেবকরা প্রতি বছর আজকের এই দিনে আমার জন্য জমকালো ভোজসভার আয়োজন করত, নানা কৌশলে আমাকে খুশি করার চেষ্টা করত।\nআসলে কিছুই ঘটেনি এমন একটি সাধারণ দিন, কিন্তু সেই অকারণ হাসিমুখগুলোর মাঝে সত্যিই আনন্দময় হয়ে উঠত। দুঃখের মাঝে সুখ খোঁজা আর শূন্য থেকে কিছু তৈরি করার দক্ষতায় মানুষ সত্যিই অতুলনীয়।\nএমনকি এই স্কুলে, যেখানে ক্যাম্পাসের মধ্যেই সমাধি গড়া হয়েছে, তোমরা এখনও এত একগুঁয়েভাবে আনন্দ সৃষ্টি করতে পারো, এটা সত্যিই আমাকে অবাক করে।\nতবে সাধারণ মানুষদের উপহারগুলো সত্যিই একঘেয়ে, তথাকথিত জন্মদিনের পার্টিও অবিশ্বাস্যরকম বিরক্তিকর, সাধারণ মানুষই তো সংখ্যাগরিষ্ঠ।\nশুধু তুমি, শুধু তোমার কথা ভাবলেই আমার কিছুটা আগ্রহ জাগে, পুরনো দিনের মতো আনন্দের স্বাদ আবার পাই।\nআমি তোমাকে আদেশ দিচ্ছি এখনই সঙ্গে সঙ্গে আমার ঘরে আসো, ভোর পর্যন্ত আমার সাথে খেলা করো। যদি ভালোভাবে সেবা করো, তাহলে আমি অনিচ্ছাসত্ত্বেও তোমাকে আমার হাতের পিঠে চুমু খাওয়ার অনুমতি দিতে পারি।\n\nওয়ান্ডা"
  },
