  Mail_68924_Desc = {
    Text = "<Del:ওয়েস্ট ডিস্ট্রিক্টের বুড়ো>গেটকিপার:\nআসলে আমি এই ধরনের আবেগঘন কিছু লেখার ইচ্ছা ছিল না, কিন্তু অ্যাজিস আমার পাশে বসে ক্রমাগত স্মৃতি আর তাৎপর্যের কথা বলে যাচ্ছিল, জোর করে আমাকে দিয়ে তোমাকে এই চিঠি লেখাচ্ছে।\nঅ্যাজিসের মুখ রক্ষার্থে, দুটো কথা বলি। ওই যে, এখানে এক বছর কাটিয়ে দিলাম, স্কুলের থাকা-খাওয়া নিয়ে সামগ্রিকভাবে আমি সন্তুষ্ট, শুধু ডর্মের বেডশিটটা একটু বেশিই পিচ্ছিল, ঘুমাতে গেলে মানিয়ে নিতে পারি না। তোমাদের কি মনে হয় না যে শুধু সেই মোটা সুতির কাপড়েই আরামে ঘুমানো যায়?\nআর যদি কিছু অভিযোগ থাকে, তাহলে ক্যান্টিনের খাবার অতিরিক্ত স্বাস্থ্যকর, খেয়ে পেট ভরে ঠিকই, কিন্তু মুখে কোনো স্বাদ থাকে না, রাস্তার খাবারের ধারেকাছেও আসে না!\nতাই এবারের জন্মদিনের পার্টিতে আমি সেই রাঁধুনিদের বিরক্ত করতে চাই না, বরং এই রন্ধন বিশেষজ্ঞ সবাইকে নিয়ে পূর্ব জেলার এক রহস্যময় গলিতে যাবে, আমি আর ব্রাউন দুজনেই বিশেষভাবে সুপারিশ করি এমন একটা স্টল আছে সেখানে, গ্যারান্টি দিচ্ছি রাস্তার সুস্বাদু খাবারে তোমরা মুগ্ধ হয়ে যাবে!\nঅবশ্যই, আজকের সব খরচ ওয়েস্ট ডিস্ট্রিক্টের বুড়োর পকেট থেকে যাবে, তোমার কোনো আপত্তি নেই তো?\n\nতোমার পুরনো বন্ধু জেনকিন ও ব্রাউন"
  },
