  Mail_68925_Desc = {
    Text = "মহানুভব:\n\nদিদির পর, আপনিই প্রথম ব্যক্তি যিনি এত আন্তরিকভাবে আমাকে সমর্থন করেছেন। আপনার আগের পরামর্শের বদৌলতে, আমি ইতিমধ্যে রেকর্ড কোম্পানির সাথে একাধিক অ্যালবাম প্রকাশ করেছি এবং শীঘ্রই আমার একক কনসার্ট অনুষ্ঠিত হতে যাচ্ছে।\nআমি এই গ্রহে আমার প্রথম কনসার্টটি আমার জন্মদিনে রাখতে চাই, এখানে আমার নতুন জীবনের স্মরণে।\nআমি চাই আপনি সশরীরে উপস্থিত থেকে আমার সর্বোচ্চ প্রচেষ্টার গান শুনুন। আমি আপনাকে এবং দিদিকে বিশেষ অতিথি হিসেবে শেষ পর্বে মঞ্চে আমন্ত্রণ জানাতে চাই, আমার সাথে আমার নতুন গান গাইতে—আপনার কী মত?\nহ্যাঁ, এই বিষয়টা আমার দিদিকে বলবেন না, কারণ এটা তারও জন্মদিন, আমি তাকে একটা চমক দিতে চাই।\nআর দিদির সাথে আমার যে প্রতিশ্রুতি ছিল নিজের জন্য একটা জন্মদিনের ইচ্ছা পূরণের—আমি চাই এই গ্রহে আমার কণ্ঠস্বর আবার উজ্জ্বল হয়ে উঠুক।\n\nটিঙ্কট"
  },
