  Mail_68926_Desc = {
    Text = "প্রিয় গোপনরক্ষক:\n\nকখন যে আরও একটা বছর পেরিয়ে গেল বুঝতেই পারলাম না। মিসাগে আমার প্রতিটি দিন অত্যন্ত আনন্দের — সবার সাথে খেলা, একসাথে ক্লাস করা, আর অনেক অনেক সুস্বাদু খাবার খাওয়া — এটাই আমার জীবনের সবচেয়ে সুখের সময়। মাঝে মাঝে মিশনে যাওয়ার সময় একটু নার্ভাস লাগলেও, সবার সাথে মিলে লড়াই করতে গেলে অ্যাজিস কখনোই ভয় পায় না।\nএই বছরও আপনাকে অনেক ঝামেলায় ফেলেছি বলে সত্যিই দুঃখিত। যদিও বেশিরভাগ সময় জেনকিনই দুষ্টুমি করে, তবে সে শুধু সবাইকে খুশি করতে চায়। আশা করি আমাদের অসাবধানতা আর ধৃষ্টতার জন্য আপনি কিছু মনে করবেন না।\nজেনকিনের কথা বলতে গেলে, এবার সে আমার জন্মদিনে একটা জোনাকি ধরা প্রতিযোগিতা আয়োজনের প্রস্তাব দিয়েছে। সে অনেক স্বচ্ছ বয়াম জোগাড় করেছে, বলছে সেগুলো দিয়ে অনেক অনেক জোনাকি বাতি বানাবে। শেষে যার বাতি সবচেয়ে উজ্জ্বল হবে, সে-ই পাবে 'পোকা-ধরা সম্রাট' উপাধি।\nযদিও 'পোকা-ধরা সম্রাট' শুনতে একটু হাস্যকর, তবে গ্রীষ্মে যে বনটা সবসময় জোনাকিতে ভরে থাকে সেটা সত্যিই অপূর্ব সুন্দর। আপনার ব্যস্ততার মাঝে যদি একটু অবসর পান, তাহলে আপনাকেও স্বাগত জানাই আমাদের সাথে সেই বনে আসতে — তারার মতো মিটমিট করা সেই দৃশ্যটা একবার দেখতে।\n\nঅ্যাজিস"
  },
  Mail_68926_Name = {
