  Mail_68927_Desc = {
    Text = "গোপনরক্ষক! কিছুদিন আগে সমুদ্রে সাঁতার কাটতে গিয়ে, অরিটা একটা নতুন বন্ধুর সাথে দেখা হয়েছে যে বিদ্যুৎ ছাড়তে পারে! দেখতে গোলগোল, চ্যাপ্টা, একটা বড় পিৎজার মতো!\nঅরিটা ওকে হাই বলতে গিয়েছিল, হঠাৎ গায়ে ঝিনঝিন লাগল, আর নতুন বন্ধুটাও সাথে সাথে চলে গেল।\nফিরে আসার পর ডোর আমাকে বলল ওটা ছিল ইলেকট্রিক রে যে বিদ্যুৎ ছাড়ছিল, অরিটা ঠিক বুঝতে পারেনি, তবে মনে হয় নতুন বন্ধুটা দারুণ! ঠিক সময়ে অরিটার জন্মদিনও এসে গেছে, গোপনরক্ষক অরিটার সাথে গিয়ে নতুন বন্ধুকে নিয়ে আসো, অরিটার সঙ্গীদের সাথে একসাথে থাকবে! ওই ঝিনঝিনে অনুভূতি, গোপনরক্ষকেরও নিশ্চয়ই ভালো লাগবে!\n\nঅরিটা"
  },
  Mail_68927_Name = {
    Text = "ঝটকা দেওয়া এক নতুন বন্ধু..."
