  Mail_68928_Desc = {
    Text = "শ্রদ্ধেয় গোপনরক্ষক:\n\nশৈশবে জন্মদিন আমার কাছে ছিল বাবার কঠোর দাবি, এক মুহূর্তও শিথিল না হওয়া বাদ্যযন্ত্র অনুশীলন।\nঅহংকার করা যাবে না, অস্থির হওয়া যাবে না, অলস হওয়া যাবে না — মা চুপিচুপি আমার জন্য একটুকরো কেক তৈরি করতেন, সেটুকু বাদ দিলে এই দিনটি আমার কাছে ছিল শুধু একটি কঠোর তিরস্কার, যেখানে গত এক বছরে আমার সমস্ত ত্রুটি চিহ্নিত করা হতো।\nআজ পর্যন্ত, আমি আর সংগীতের শিক্ষানবিশ নই, এবং আপনার কল্যাণে সেই মহিমান্বিত দ্বারে স্পর্শ করতে পেরেছি, সর্বোচ্চ সংগীতের মন্দিরে প্রবেশ করতে পেরেছি। কিন্তু ছোটবেলা থেকে পাওয়া শিক্ষা আমাকে এমনভাবে গড়ে দিয়েছে যে সাধারণ আনন্দের প্রতি আমার কোনো আকাঙ্ক্ষা নেই।\nকেবল সংগীত, কেবল আপনার জন্য সেই নিয়তি-নির্ধারিত শান্তিসংগীত বাজানো — এটাই আমার জীবনের চূড়ান্ত সাধনা, এটাই একমাত্র মুহূর্ত যখন আমি অস্তিত্বের অর্থ অনুভব করতে পারি।\nযদি আপনি আজ রাতে ঘুমানোর আগের সময়টুকু আমাকে দিতে রাজি হন, আমি সারারাত আপনার জন্য আমার আত্মায় খোদাই করা সেই সুর বাজাতে চাই, ভোরের আলো ফোটা পর্যন্ত।\n\nহ্যামলিন"
  },
