  },
  Mail_68929_Desc = {
    Text = "ছোকরা:\n\nতোমাদের এখানে আসার পর থেকে ভেবেছিলাম অবশেষে সেই গোঁড়া পাগলী মহিলার হাত থেকে মুক্তি পেলাম, কিন্তু তোমাদের এই ভুতুড়ে জায়গার নিয়মকানুন তো সেই মহিলার চেয়েও বেশি। কতদিন হলো আমি জানিই না যে প্রাণ খুলে মজা করা কাকে বলে!\nগলাভরে মদ খাওয়া যাবে না, সুন্দরীদের সাথে ফ্লার্ট করা যাবে না, ক্যাম্পফায়ার ভোজ করা যাবে না, এমনকি তোমাদের এখানকার কাবাবও ফিলিস্তিনের ধারেকাছেও আসে না! জানি না এত ফ্যাকাশে স্বাদহীন জীবন তোমরা কীভাবে কাটাও।\nতবে শক্তিশালীরা পরিবেশ নিয়ে অভিযোগ করে না। আমার একটু দাপাদাপির পর, আমি তোমাদের শহরে আবারও একজন মহান গ্যাং নেতা হয়ে উঠেছি।\nমহান গলিয়াথের প্রভুর জন্মদিন উপলক্ষে, আমি দয়াপরবশ হয়ে তোমাকে আমার অনুসারীদের আয়োজিত ভোজসভায় আমন্ত্রণ জানাচ্ছি। উৎকৃষ্ট মদ, সুস্বাদু মাংস আর সুন্দরীদের কোনো কমতি নেই — তোমার মতো দুনিয়া না-দেখা বাচ্চার চোখ খুলে যাবে।\nআগের বন্ধুত্বের খাতিরে, তোমার কাছে কোনো উপহার চাইছি না। শুধু তোমার শ্রদ্ধা নিয়ে এসো, শক্তিশালীর পুনরুত্থানে আশীর্বাদ জানাও।\nচোখ বড় বড় করে ভালো করে দেখে নাও, আগামী বছরের আজকের দিনে, তার পরের বছরের আজকের দিনে, যেখানেই থাকি না কেন, আমি নতুন এক বিজয়যাত্রা শুরু করব।\n\nগলিয়াথ"
  },
  Mail_68929_Name = {
    Text = "যাত্রা…"
  },
  Mail_68929_Sender = {
    Text = "গোলিয়াথ"
  },
  Mail_68930_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nমূলত আমি কখনো এই তুচ্ছ দেহের জন্মদিন উদযাপনের কথা ভাবিনি, এটিকে কেবল সাধারণ সাধনার দিন হিসেবেই গণ্য করতাম। কিন্তু অপ্রত্যাশিতভাবে আজ সকালে মহারাজ আমাকে খুঁজে বের করলেন এবং মৌখিক আদেশ জারি করলেন যে আজ আমি মহারাজ বা সাধনা সম্পর্কিত কোনো কাজ করতে পারব না, পুরো একটি দিন সম্পূর্ণরূপে নিজের জন্য কাটাতে হবে।\nএত দিন-রাত পর মহারাজ প্রথমবারের মতো এভাবে আমার কথা মনে রেখেছেন, এতে আমি অত্যন্ত বিচলিত ও কৃতজ্ঞ। কিন্তু আমি ইতিমধ্যেই এই জীবন সম্পূর্ণরূপে মহারাজের কাছে উৎসর্গ করেছি, তাই হঠাৎ বুঝতে পারলাম না কোথায় যাব, কী করব।\nঅনেকক্ষণ ভাবার পর, এখন একমাত্র যা সামান্য আক্ষেপের বিষয় বলা যায়, তা হলো মার্ফির প্রতি আমার অপরাধবোধ। মাতৃভূমির পুনরুত্থানের জন্য হলেও, আমার কখনো বিন্দুমাত্র অনুতাপ হয়নি, তবে তার কাছে যা ঋণ রয়ে গেছে, আমি নিজেও জানি তা পরিশোধ করা বা পূরণ করা সম্ভব নয়।\nকিন্তু, যদি সত্যিই আমার অন্তর থেকে কিছু করতে চাওয়ার ইচ্ছা থাকে, তবে সম্ভবত নির্লজ্জভাবে আরও একবার একজন মায়ের যা করা উচিত তা করতে চাই।\nআমি বিশেষভাবে সেই মেয়েটির একসময়ের প্রিয় মিষ্টি কিনে এনেছি। একজন ঘৃণ্য, অযোগ্য মায়ের শেষ ইচ্ছা পূরণ হিসেবে ধরে নিন — আপনাকে কি অনুরোধ করতে পারি এই উপহারটি তার হাতে পৌঁছে দিতে? তাকে বলবেন না যে এটি আমার পাঠানো, শুধু বলবেন আপনিই প্রস্তুত করেছেন।\nসম্মতির প্রত্যাশায়, অসীম কৃতজ্ঞতা সহ।\n\nমিরিয়াম"
  },
  Mail_68930_Name = {
    Text = "প্রায়শ্চিত্ত..."
  },
  Mail_68930_Sender = {
    Text = "মিরিয়াম"
  },
  Mail_68931_Desc = {
    Text = "আহা, আমার বুদ্ধিমান চিন্তাভাবনার পর, আমি মানুষের জন্মদিনের তাৎপর্য পুরোপুরি বুঝে গেছি। তথাকথিত কারো জন্য বিশেষ একটি দিন হলো বিরল বিশেষ সুবিধা প্রয়োগের সুযোগ পাওয়া, মূল্যবান জিনিস পাওয়ার সুযোগ, এবং অন্যদের কাছে নির্দ্বিধায় ইচ্ছা প্রকাশ করার সুযোগ।\nসাধারণ দিনে যে ইচ্ছাগুলো বলার সাহস হয় না বা ভাবাও হয় না, এই দিনে সেগুলো পূরণ হওয়ার সুযোগ থাকে। হা, এটা তো যেকোনো উৎসবের চেয়েও বেশি রোমাঞ্চকর উচ্ছৃঙ্খলতার দিন!\nমনে হচ্ছে আগের এত বছরে আমি এত বিশেষ সুবিধার সুযোগ মিস করেছি। তবে ভালো কথা হলো, আমার দীর্ঘ আয়ু অনুযায়ী, সামনে আমার আরও অনেক অনেক জন্মদিন আছে ইচ্ছা পূরণ করার জন্য।\nতাহলে, জন্মদিনের দিনে সবাইকে আমার সাথে মনের সুখে একটা লড়াই করতে বলা, এটা তো খুব সহজেই পূরণ করা যায় এমন একটা ইচ্ছা, তাই না?\n\nলোটান"
  },
  Mail_68931_Name = {
    Text = "জন্মদিনের তারকার বিশেষ সুবিধা..."
  },
  Mail_68931_Sender = {
    Text = "লোতান"
  },
  Mail_68932_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nবয়স বাড়ার সাথে সাথে জন্মদিন ধীরে ধীরে ক্যালেন্ডারের এমন একটি দিনে পরিণত হয় যা চোখের পলকে উপেক্ষা করে যায়, প্রায়ই অসাবধানে মনে পড়ার আগেই জন্মদিনটা বয়ে যাওয়া জলের মতো নীরবে পেরিয়ে যায়।\nপ্রাপ্তবয়স্কদের জগতে জন্মদিন উদযাপন শুধু শিশু আর অলস মানুষদের বিশেষাধিকার, এই ব্যাপারে আমিও একজন বিরক্তিকর বড় মানুষে পরিণত হয়েছি, জন্মদিন নিয়ে আর কোনো প্রত্যাশা নেই।\nএকবার হঠাৎ মনে হলো, নিজের জন্য একটি সুন্দর কেকের ভাস্কর্য খোদাই করি, তারপরের কয়েক বছর জন্মদিন ভুলে কেক অর্ডার করতে না পারার সমস্যা আর হয়নি, বরং সরাসরি জন্মদিনের দিন গুদাম থেকে এই কখনো-না-পচা উদযাপনের সামগ্রীটি বের করে, মোমবাতি ফুঁ দেওয়ার আনুষ্ঠানিকতাটুকু পালন করি, ব্যস জন্মদিন শেষ।\nমিসাগারে আসার পরেই আবিষ্কার করলাম যে অলস আর ব্যস্ত মানুষ একই ব্যক্তির মধ্যে সহাবস্থান করতে পারে, আর এখানকার মানুষেরা শুধু নিজে একা বিরক্ত হয়ে সন্তুষ্ট থাকে না, সবাইকে একসাথে টেনে এনে বিরক্ত করতেই হবে।\nএই দুই বছরে মিসাগারে যত জন্মদিনের পার্টিতে যোগ দিয়েছি তা আমার আগের অর্ধেক জীবনে যোগ দেওয়া সব জন্মদিনের পার্টির চেয়েও বেশি, আরও মজার ব্যাপার হলো এই ধরনের বিরক্তিকর উদযাপনেও আমি এক টুকরো অদ্ভুত আনন্দ খুঁজে পেয়েছি।\nহয়তো বিষাদময় ও গম্ভীর বিষয়বস্তুর বাইরে, জীবনের বোকামিতে ভরা দৃশ্যগুলো চিত্রিত করাও শিল্পের সৌন্দর্যে পরিপূর্ণ হতে পারে।\nএই কথা বলতে গিয়ে মনে হলো, এবারের জন্মদিনের সৃষ্টি পরিকল্পনা হবে একটি গোপনীয়তার রক্ষকের বোকা হাসির আবক্ষ মূর্তি খোদাই করা, যেটা দিয়ে আমার ভাস্কর্য কেকটা ধরে রাখা যাবে।\nতাড়াতাড়ি আমার স্টুডিওতে এসো কিন্তু, আমার মিউজ মডেল।\n\nশান"
  },
  Mail_68932_Name = {
    Text = "একঘেয়ে মজা..."
  },
  Mail_68932_Sender = {
    Text = "সাঙ্গা"
  },
  Mail_68933_Desc = {
    Text = "চিঠি খুলে শান্তিতে পড়ো:\n\nঅনেক ভেবেচিন্তে, এই ধ্বংসপ্রাপ্ত পৃথিবীতে বসে এই চিঠিটা লিখছি। অনেকদিন ধরেই নিজের জন্মদিনের কথা প্রায় ভুলেই গিয়েছিলাম, এমন একটা পৃথিবীতে উদযাপনের কোনো মানেই হয় না।\nকিন্তু, তোমার সাথে দেখা হওয়ার পর থেকে আমি ক্রমশ লোভী হয়ে উঠছি, দিনের পর দিন, এমনকি অভ্যস্ত একাকীত্বটাও এখন অসহ্য লাগে।\nযখনই এমন হয়, আমার মনে এক অদ্ভুত অনুভূতি জেগে ওঠে, সেই পৃথিবীর আমার প্রতি একটুখানি ঈর্ষা, হয়তো সামান্য হিংসাও। দেখো, আমার মতো যুক্তিবাদী বলে দাবি করা মানুষেরও এমন হীন মনোভাবের দিন আসে, এতেই বোঝা যায় মানুষের ন্যায়পরায়ণতা আর বিচারবুদ্ধিরও সীমা আছে।\nআমি জানি তুমি আমাকে কী আমন্ত্রণ জানাবে, কিন্তু স্থান-কালের জন্য অপ্রয়োজনীয় বিঘ্ন যতটা সম্ভব এড়ানো উচিত, আমার তোমার পৃথিবীতে যাওয়া উচিত নয়, আর যাবও না।\nএটুকু লেখার সময়, আমি মহাবিশ্বের দিকে তাকিয়ে আছি, সুড়ঙ্গ খোলার জায়গাটার দিকে, যদি তুমিও ঠিক এই মুহূর্তে মাথা তুলে তাকিয়ে থাকো, তাহলে আমরাও একই তারার আকাশ একসাথে দেখছি বলা যায়।\nআশা করি এই চিঠিটা আমার হয়ে, স্থান-কাল পেরিয়ে, ভেসে ভেসে তোমার হাতের তালুতে পৌঁছাবে, তোমার চোখ আর ঠোঁট ছুঁয়ে, তোমার সাথে দেখা করবে, তোমার পাশে থাকবে।\nযখন তুমি এই চিঠির কাগজটাকে জড়িয়ে ধরবে, আমি পৃথিবীর এই প্রান্তে বসে তোমাকে জড়িয়ে ধরার কল্পনা করব।\n\n「রামোনা」"
  },
