  Mail_68933_Sender = {
    Text = "রামোনা: টাইমওর্ন"
  },
  Mail_68934_Desc = {
    Text = "আমার ছোট্ট·বন্দী:\n\nতুমি কি জানো, যেমন বিভিন্ন প্রাণীর খাদ্যতালিকা ভিন্ন হয়, তেমনি বিভিন্ন মানুষের উষ্ণতার চাহিদাও আলাদা। কারো জন্য একটি কাপড় গায়ে জড়িয়ে নেওয়াই যথেষ্ট, কারো দরকার হয় একজোড়া উষ্ণ হাত, একটি উষ্ণ আলিঙ্গন, আবার কারো প্রয়োজন এমন তাপমাত্রা যেখানে মোম গলে যায়।\nসেই জ্বলন্ত, আঠালো উষ্ণতা প্রতিটি স্নায়ুপ্রান্তে খোদাই হয়ে যায়, স্পষ্টভাবে ফুটিয়ে তোলে মোমের আঁকাবাঁকা পথে গড়িয়ে পড়ার রেখা, হালকা যন্ত্রণা, শিহরণ জাগানো স্পর্শ—যতক্ষণ না নিজের অজান্তেই চিৎকার করে ওঠো, ততক্ষণ পর্যন্ত নিজের অস্তিত্বকে পুরোপুরি অনুভব করা যায় না।\nকখনো আমি নিজেই মোমবাতি হয়ে উঠি, ছাপ রেখে যাওয়ার আনন্দ উপভোগ করি, আবার কখনো মোমবাতির উষ্ণতায় মুগ্ধ হয়ে পড়ি, সেই যন্ত্রণাদায়ক, মধুর উষ্ণতার জন্য তৃষ্ণার্ত হই।\nমিসাগে শীতকাল এসে গেছে, ইদানীং আমি প্রায়ই ঠান্ডা অনুভব করছি, আর ঠান্ডার সাথে আসা একাকীত্বও। প্রিয়, তুমি নিশ্চয়ই জানো আজ কোন দিন। আমার ইচ্ছা খুবই সাধারণ, আর তোমার মতো দয়ালু কেউ নিশ্চয়ই আমার একাকীত্ব দূর করার উষ্ণতা নিয়ে আসতে রাজি হবে।\n\nপান্দিয়া"
  },
  Mail_68934_Name = {
    Text = "উষ্ণতা প্রয়োজন..."
  },
  Mail_68934_Sender = {
