  },
  Mail_68935_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nএই বছর আমি এবং টিঙ্কট পরস্পরের সাথে একটি চুক্তি করেছি যে, আমাদের জন্মদিনের ইচ্ছা শুধুমাত্র নিজেদের জন্যই হতে হবে, একে অপরের জন্য কোনো ইচ্ছা পোষণ করা যাবে না।\nযদিও সে-ই প্রথম রাগ করে এই চুক্তিটা প্রস্তাব করেছিল, কিন্তু স্পষ্টতই এটা তাকেও বিপদে ফেলেছে।\nআমরা দুজন এত দীর্ঘ সময় ধরে একে অপরের সাথে জড়িয়ে আছি যে, সাধারণ মানুষের মতো স্বাধীনভাবে চিন্তা করাটাও একটা কঠিন কাজ। কিন্তু এত সাহায্য ও যত্নে ভরা এই নতুন জীবনে পুনর্জন্ম লাভ করে, স্বাধীনভাবে চলতে শেখার জন্য এর চেয়ে ভালো সময় আর নেই।\nতাহলে আমার সতর্ক বিবেচনার পর, আমি এই বছরের ইচ্ছাটা ঠিক করে ফেলেছি: পাঁচজন নতুন বন্ধু তৈরি করা... না, তিনজনই হোক। সর্বোপরি, নিজেকে বদলানোর মতো বিষয়ে ধীরে ধীরে এগোনোই ভালো।\nআমার বর্তমানে একমাত্র এবং এত জনপ্রিয় বন্ধু হিসেবে, তুমি কি আমাকে বন্ধু তৈরির কিছু গোপন কৌশল শেখাতে পারো?\n\nফেইন্ট"
  },
  Mail_68935_Name = {
    Text = "বন্ধুত্বের কামনা..."
