  Mail_68936_Desc = {
    Text = "রহস্যরক্ষক: \n\nপ্রতি বছর জন্মদিনে মোমবাতি নেভানোর সময় আমি একই ইচ্ছা পোষণ করি — নিখুঁত রক্তধারার রূপান্তর। আমি আসলে সবসময় জানতাম যে রক্তধারার প্রতি আমার এই আবেশ অন্যদের চোখে হয়তো জেদ, হাস্যকর, এমনকি করুণা ও ঘৃণার যোগ্য।\nকিন্তু তুমি আলাদা। যেকোনো সময়ে, আমি জানি তুমি সবসময় আমাকে এই পথে এগিয়ে যেতে সমর্থন করবে — বাধায় ধাক্কা খেলেও, পড়ে গেলেও, ব্যর্থ হয়ে ফিরে এলেও। অন্যদের হাসির মধ্যে তুমিই প্রথম যে আমার কথা ভেবেছ।\nহয়তো তুমি বা অন্য কেউই বুঝতে পারবে না ছোটবেলা থেকে নিপীড়িত ও অপমানিত একজন মানুষ কতটা বোঝা বহন করে চলে, কিন্তু কিছু যায় আসে না। এই রূপান্তরের পথের সমস্ত কষ্ট আমার রক্তমাংসে ও পুষ্টিতে পরিণত হয়েছে, আমাকে বারবার উঠে দাঁড়াতে ও প্রতিরোধ করতে শক্তি জুগিয়েছে।\nআমি আর সেই অসহায় কিশোর নেই। যতই পরীক্ষা আসুক, আমি দৃঢ়ভাবে শেষ মুহূর্ত পর্যন্ত এগিয়ে যাব।\nততক্ষণ পর্যন্ত, দয়া করে আমার দিকে তাকিয়ে থাকো, আমার সাফল্যের জন্য অপেক্ষা করো।\nআচ্ছা, তুমি আগে আমাকে যে পঞ্চাশ টাকা দিয়েছিলে, আমি বলেছিলাম ফেরত দেব। এখন পুরোটা জমা হয়ে গেছে, এমনকি দুই টাকা বেশিও হয়েছে — সেটা পুরস্কার হিসেবে একসাথে তোমাকে দিচ্ছি।\n\nকেকেস"
  },
