  Mail_68938_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nপ্রতি জন্মদিনে, আমি পুরো একটি দিন ব্যয় করি অতীতের স্মৃতিগুলো মনের মধ্যে খুঁটিয়ে খুঁটিয়ে স্মরণ করতে, একই দিনলিপি আবারও লিখে রাখতে।\nস্বদেশ থেকে যত দূরে থাকি, পুরনো স্মৃতিগুলো যেন তত ঝাপসা হয়ে যায়— সেই দিনগুলো যখন আলোর পথ ধরে প্রত্যাবর্তনকারীর জন্য অপেক্ষা করতাম, সেই দিনগুলো যখন দূর থেকে রাজার মহিমা শ্রদ্ধাভরে দেখতাম— সব যেন আর স্পষ্ট মনে পড়ে না।\nকিন্তু আমি ভুলতে চাই না, আমি কখনোই ভুলব না। অপেক্ষা যতই দীর্ঘ ও অন্তহীন হোক, আত্মা পুড়ে ছাই হলেও, এই আলোকরশ্মি কখনো ম্লান হবে না— যেদিন মাতৃভূমি পুনর্জাগরিত হবে, আমিই হব সেই প্রথম আলো যা ডাকে সাড়া দেবে।\nআমি পুনর্মিলনের অসংখ্য দৃশ্য কল্পনা করেছি, কিন্তু কখনো ভাবিনি এই স্থানে রাজা ও পুরোহিতের সাথে আবার দেখা হবে। তোমাদের সেই কথা অনুসারে বলতে গেলে, যেখানে হৃদয় শান্তি পায় সেটাই যদি স্বদেশ হয়, তাহলে এখানটাকে আমার দ্বিতীয় স্বদেশ বলা চলে, আর আমার দিনলিপিতে যা লেখা ছিল তা অবশেষে স্মৃতিচারণ থেকে প্রতিদিনের নতুন স্মৃতিতে পরিণত হয়েছে।\nকোনো পুরস্কার বা উপহারের প্রয়োজন নেই— আবারও রাজার পাশে থেকে অনুসরণ করতে পারাটাই সবচেয়ে বড় সৌভাগ্য।\nযদি এই দেহের আলো স্বদেশের সমুদ্রতলকে আলোকিত করতে না পারে, তবে তা রাজার পদচিহ্ন অনুসরণ করুক, আপাতত এই স্থলভূমির রাজ্যকেই আলোকিত করুক।\n\nফ্যালোস"
