  Mail_68939_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nআমাকে অভিনন্দন, তোমাকেও অভিনন্দন, মিসাগেকে অভিনন্দন, অভিনন্দন যে আমরা অন্ধকার আতঙ্কের তাড়া থেকে আরও একটি বছর টিকে থাকতে পেরেছি।\nআজ শুধু একটি সাধারণ জন্মদিন নয়, আজ আমার বেঁচে থাকার স্মারক দিবস, আমার অদম্য জীবনীশক্তির প্রশংসার দিন।\nবেঁচে থাকা, এই সহজ সরল শব্দটির মধ্যে কতটা কষ্ট লুকিয়ে আছে। এই উত্তপ্ত প্রাণশক্তির সাথে কেবল গরম কফির সুগন্ধই তুলনীয়। এসো গোপনীয়তার রক্ষক, কফি ধর্মে যোগ দাও, চলো আমরা জাগরণের প্রশংসা করি, বেঁচে থাকার প্রতিটি মুহূর্তের প্রশংসা করি\n\nচিঠির সাথে পাঠানো একটি নোট:\nহায়, উইনকেল আবারও অতিরিক্ত কফি পান করেছে, স্নায়ুবিক উত্তেজনা আর চরম ক্লান্তির ফলে সরাসরি টেবিলের সামনে অজ্ঞান হয়ে পড়েছে। আমি তাকে স্কুলের চিকিৎসা কক্ষে নিয়ে গেছি, চিন্তা করো না।\nতবে অজ্ঞান হওয়ার আগে সে তার সংগ্রহের একটি কফি বিনের প্যাকেট বের করে চিঠির কাগজের সাথে রেখেছিল, মনে হচ্ছে তোমাকে উপহার দিতে চেয়েছিল, তাই আমি চিঠির সাথে পাঠিয়ে দিলাম। আশা করি জেগে ওঠার পর সে অনুতাপ করবে না।\nআর তার জন্মদিনের কথা বলতে গেলে, উদযাপন পার্টির চেয়ে বরং তাকে ভালো করে বিশ্রাম নিতে দেওয়াটাই হয়তো সবচেয়ে ভালো উপহার হবে।\n——সিলভিয়া"
  },
  Mail_68939_Name = {
    Text = "আমাদের জীবনের বন্দনা..."
