  Mail_68940_Desc = {
    Text = "গোপনীয়তার রক্ষক:\n\nহাহাহা! ঘরের প্রতিটি কোণায় ১২টি রিমাইন্ডার খোদাই করে এবং ৩৬টি নোট লিখে (হয়তো আরও বেশি ছিল কিন্তু আমি সেগুলো খুঁজে পাইনি) অবিরাম চেষ্টার পর, অবশেষে আমি সবার প্রত্যাশা পূরণ করে মনে রাখতে পেরেছি যে আজ আমার জন্মদিন!\nতোমরা হয়তো ভাবোনি, আসলে আমি নিজেও আজ সকালেই মনে করেছি, তবে এটা সবই এই এক বছরের কঠোর প্রস্তুতির ফল — আমি এমন একটা সুন্দর দিন মিস করতে চাই না।\nগতবার সবাই মিলে যে পার্টি করেছিলাম সেটা সত্যিই খুব আনন্দের ছিল, বিশেষ করে কার সাথে যেন কী খেলা খেলেছিলাম, আর কোনো একটা মিষ্টি খেয়েছিলাম... যাক গে, মোটকথা খুব মজা হয়েছিল!\nছোটবেলায় জন্মদিনে মা সবসময় আমাকে একটা অ্যাডভেঞ্চার গল্পের বই কিনে দিতেন, আমরা দুজন প্রতিদিন ঘুমানোর আগে একসাথে গা ঘেঁষে পড়তাম আর পড়তাম, তারপর স্বপ্নে দারুণ সব অ্যাডভেঞ্চারের স্বপ্ন দেখতাম। যদিও ঘুম থেকে উঠলে তাড়াতাড়ি ভুলে যেতাম, কিন্তু সেই আনন্দটা মনের মধ্যে রয়ে যেত — আমি বিশ্বাস করি মূল্যবান অনুভূতি কখনো ভোলা যায় না।\nতাছাড়া ভুলে যাওয়ারও তো সুবিধা আছে! যদিও আমি মনে নেই আগের পার্টিতে কী কী করেছিলাম, কিন্তু আজ আমি সব আবার নতুন করে উপভোগ করতে পারব — গতবারের আনন্দটা প্যাক করে আমাকে আরেকবার দিয়ে দাও!\n\nপ্রত্যাশায় পূর্ণ নোতিরা"
  },
