    Text = "প্রিয় কিপার, \n       V1.7.1 আপডেটে 「প্রজনন উন্মাদনা」 ইভেন্টের 「হেলট: ক্যাটেনা」র আনলক অবস্থা অস্বাভাবিকভাবে হারিয়ে গিয়েছিল। তুমি যেহেতু পূর্বে আনলক করা অবস্থা হারানোর পর তা পুনরায় আনলক করেছ, তাই পুনরায় আনলক করার সময় ব্যবহৃত 「রিয়েলিটি ভার্জ *3」 আমরা তোমাকে ক্ষতিপূরণ হিসেবে প্রদান করব। অনুগ্রহ করে যাচাই করো।"
