  },
  Mail_74841_Desc = {
    Text = "সঙ্গী:\n\nগত বছর আজকের দিনে, আমি কল্পনাও করতে পারিনি যে মাত্র এক বছর পর আমাকে এই চিঠিটি একটি ফাঁকা মেইলবক্সে ফেলতে হবে।\nসেই সময় তুমি সবে মিসাগে এসেছিলে, একজন দুরন্ত আর অলস ছাত্রের থেকে তোমার কোনো পার্থক্য ছিল না। এখন ভাবলে বুঝতে পারি, আমি তখন প্রায়ই তোমার প্রতি অতিরিক্ত কঠোর ছিলাম, আর নিজের সেই যুক্তিবাদী ও সংযত মুখোশটাকে বেশি গুরুত্ব দিতাম।\nআসলে গত বছর এই দিনে আমি একগুচ্ছ ফুল কিনেছিলাম। আমি লাইব্রেরির দরজার সামনে দাঁড়িয়ে, লাল ফিতা আর গাঢ় সবুজ মোড়কের কাগজে শোয়ানো সেই গোলাপগুলোর দিকে অনেকক্ষণ তাকিয়ে ছিলাম, শেষ পর্যন্ত সেগুলো আমার বিছানার পাশে রেখে দিয়েছিলাম।\nএক বছরে ফুলগুলো অনেক আগেই শুকিয়ে গেছে, শুধু সেই উজ্জ্বল লাল সাটিন ফিতাটা K-0617 নম্বর রুপালি চাবিতে বেঁধে রেখেছি, যা এখনও আগের মতোই উজ্জ্বল।\nআমি কতটা, কতটা চাই আবার একগুচ্ছ গোলাপ কিনতে, কিন্তু এখন সেগুলো আমার বিছানার পাশে আবার ঝরে পড়া ছাড়া আর কোনো গন্তব্য নেই।\nসবকিছুর বিস্তারিত সমাধান তালিকা করার অভ্যাস আমার, তাই অনুশোচনার স্বাদ আমার কাছে এতটাই নতুন আর তিক্ত।\nতবু আমি প্রায় অন্ধ বিশ্বাসের মতো একটা আস্থা বুকে ধরে রেখেছি—তোমার আত্মা কখনও চলে যায়নি বলে মনে করি। হয়তো তুমি সাময়িকভাবে মহাবিশ্বের কোথাও ঘুরে বেড়াচ্ছ, কিন্তু শেষ পর্যন্ত এখানে ফিরে আসবে, আমার পাশে।\nআমি এটাকে অলীক কল্পনা মনে করি না, কারণ যখনই আমি কালো পুকুরে এসে তোমার মুখের দিকে তাকাই, হৃদয়ে এখনও তোমার সাথে সংযোগ ও অনুরণনের সেই উষ্ণ তাপ অনুভব করতে পারি।\nআমি সেই পুনর্মিলনের দিনটিতে সর্বদা বিশ্বাস রাখব এবং আশা করব। যেদিন আমাদের হাত আবার পরস্পরকে ধরবে, সেদিন আজকের বকেয়া গোলাপগুলো আমি নিজ হাতে তোমার হাতে তুলে দেব।\n\nরামোনা"
  },
