  Mail_79390_Desc = {
    Text = "প্রিয় রক্ষক, \n 「মরিমেন্স」-কে সমর্থন করার জন্য আপনাকে ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে আরও উন্নত গেমিং অভিজ্ঞতা প্রদান করার জন্য, আমরা আন্তরিকভাবে আপনাকে নিম্নলিখিত অভিজ্ঞতা-গবেষণা প্রশ্নাবলি পূরণ করার আমন্ত্রণ জানাচ্ছি। কৃতজ্ঞতার নিদর্শন হিসেবে, আমরা পুরস্কার হিসেবে [Silver*200] প্রস্তুত করেছি, যা আপনি প্রশ্নাবলি সম্পন্ন করার পর সংগ্রহ করতে পারবেন। প্রশ্নাবলির শেষ সময় 17 মার্চ সকাল 9:00। অনুগ্রহ করে সময়মতো এটি পূরণ করে দিন।\n   <SurveyLink:[Click to Fill]>\n   আমরা প্রতিটি রক্ষকের পরামর্শ মনোযোগ দিয়ে শুনব, আর আপনার প্রতিক্রিয়া নিঃসন্দেহে মিথাগ বিশ্ববিদ্যালয়কে ক্রমশ আরও উন্নত করে তুলবে!\n — রৌপ্য চাবি যেন আপনার পথ আলোকিত করে।"
