  Mail_80091_Desc = {
    Text = "গোপনীয়তা রক্ষাকারী:\n\nযখন তুমি এই চিঠিটি খুলবে, তার মানে হলো আমি তোমার মনে যে ইঙ্গিত রোপণ করেছিলাম তা কার্যকর হয়ে গেছে।\nহা, চিন্তা করো না। এটি শুধুমাত্র আমার জন্মদিনের অনুষ্ঠান সুষ্ঠুভাবে সম্পন্ন করার জন্য প্রয়োগ করা একটি তুচ্ছ সম্মোহন, এটি তোমার উপর কোনো প্রভাব ফেলবে না।\nএরপর, তোমার মনের গভীর থেকে কেনাকাটা করার তীব্র ইচ্ছা জাগবে, সেই তাগিদ মেনে রাস্তায় বেরিয়ে পড়ো, সেই বর্ণিল দোকানের জানালা থেকে আমার মনের সাথে সবচেয়ে মানানসই একটি উপহার বেছে নাও, তারপর আমার হাতে পৌঁছে দাও।\nআমি জানি এই মুহূর্তে তোমার মনে সন্দেহ আছে, এবং আমি এর যৌক্তিকতাও স্বীকার করি, কিন্তু জন্মদিনের নায়কের কিছু বিশেষ সুবিধা থাকে, তাই না? আমি এমনটা করেছি শুধু এই ভয়ে যে তুমি এই বিশেষ দিনটি ভুলে যাবে। সর্বোপরি, তুমি তো আমার সবচেয়ে কাঙ্ক্ষিত অতিথি।\nশেষে, আমি ধৈর্য ধরে তোমার আগমনের অপেক্ষায় থাকব——উপহারটি ভুলো না।\n\nক্লেমেন্টাইন"
  },
