    Text = "প্রিয় রক্ষক,\n  「মরিমেন্স」-কে সমর্থন করার জন্য আপনাকে ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে আপনার গেমিং অভিজ্ঞতা আরও সমৃদ্ধ করতে, আমরা আপনাকে নিম্নলিখিত অভিজ্ঞতা-জরিপটি পূরণ করার আমন্ত্রণ জানাচ্ছি। আপনার সহযোগিতার প্রতি কৃতজ্ঞতা জানাতে, আমরা পুরস্কার হিসেবে 「সিলভার*200」 প্রস্তুত করেছি, যা জরিপ সম্পন্ন করার পর সংগ্রহযোগ্য থাকবে। জরিপের শেষ সময় 14 এপ্রিল সকাল 9:00, অনুগ্রহ করে অবশ্যই সময়মতো জমা দিন।\n<SurveyLink:\"পূরণ করতে ক্লিক করুন\">\nআমরা প্রতিটি রক্ষকের পরামর্শ গভীর মনোযোগ দিয়ে বিবেচনা করব, আর আপনার প্রতিক্রিয়া নিঃসন্দেহে মিথাগ বিশ্ববিদ্যালয়কে আরও উন্নত করে তুলবে!\n—রৌপ্য চাবি যেন পথ প্রদর্শন করে।"
