  Mail_81326_Desc = {
    Text = "প্রিয় উপকারী:\n\nআজকের দিনটি আমার এবং পলিডিউসিসের কাছে সারা বছরের একমাত্র উৎসব। চার্চে থাকাকালীন, আমাদের নিজেদের গুরুত্বের প্রতি অতিরিক্ত মনোযোগ দেওয়ার অনুমতি ছিল না। আমাদের সমস্ত মূল্য কেবল প্রদীপবাহকের সেবা করার এই চিরন্তন কর্তব্যের মধ্যেই নিহিত ছিল, সেই বিশ্বাসের সামনে অন্য যেকোনো উৎসবও ছিল অর্থহীন মায়া।\nকিন্তু প্রতি জন্মদিনে, আমি এবং পলিডিউসিস তবুও গোপনে উদযাপন করতাম। আমরা পরিচারকদের অগোচরে একে অপরের জন্য যতটা সম্ভব ছোট একটি উপহার প্রস্তুত করতাম, তারপর গোপনে এই দিনটির জন্য অপেক্ষা করতাম।\nজন্মদিনের উদযাপনের মুহূর্তটি সাধারণত গভীর রাতে হতো——সেটাই ছিল আমাদের দিনের একমাত্র মুক্ত সময়। পলিডিউসিসের দক্ষ হাত আর বুদ্ধি সবসময় তার উপহারকে আমারটার চেয়ে উৎকৃষ্ট করে তুলত। একবার সে এমনকি ঝরে পড়া পালক জমিয়ে একটি ফুটন্ত ফুল বুনে ফেলেছিল।\nআসলে আমি চমক প্রস্তুত করতে তেমন পারদর্শী নই। পলিডিউসিস সবসময় বলে যে আমার স্বাভাবিক মুখের ভাব আগেই সব ফাঁস করে দেয়। আর আমার কাছে যা আছে তা আপনার চোখে নিশ্চয়ই আরও বেশি তুচ্ছ ও নীরস মনে হবে। তবে আজ আমি আপনার সাথে আনন্দ ভাগ করে নেওয়ার একটি চমৎকার উপায় ভেবে বের করেছি।\nযখন রাতে আপনি জানালায় তিনবার টোকা দেওয়ার শব্দ শুনবেন, দয়া করে ভয় পাবেন না, জানালা খুলুন——আমি আপনাকে মেঘ আর রাতের বাতাসের স্পর্শ অনুভব করাতে নিয়ে যাব।\n\nক্যাস্টর"
