  Mail_84142_Desc = {
    Text = "গোপনীয়তার রক্ষক: \n\nমিলিত হওয়ার আগে, আমি এই চিঠিটি লিখেছি, আনুষ্ঠানিকভাবে আপনাকে আমার 「জন্মদিনের সমুদ্রযাত্রা」-তে আমন্ত্রণ জানাতে এবং এর পরিচয় দিতে।\nএই যাত্রার প্রথম গন্তব্য হলো টেমস নদী। আমরা একটি মালবাহী জাহাজ থেকে রূপান্তরিত ভাসমান রেস্তোরাঁয় উঠব, নদীতে ভেসে ভেসে টিনজাত মধু-মাখানো আনারস আর রাম উপভোগ করব। এটি নাবিকদের জন্মদিনে বিশেষভাবে পরিবেশিত সুস্বাদু খাবার, আশা করি আপনার ভালো লাগবে।\nএই যাত্রার দ্বিতীয় গন্তব্য হলো বন্দরের পর্যবেক্ষণ মঞ্চ। নিশ্চিন্ত থাকুন, আমি ইতিমধ্যে হট এয়ার বেলুন অ্যাসোসিয়েশনের কাছ থেকে পর্যবেক্ষণের অনুমতি নিয়ে রেখেছি। যখন হট এয়ার বেলুন আকাশে উঠবে এবং সমগ্র লন্ডনের নৌপথ দেখা যাবে, তখন আমরা একসাথে কেক কাটব উদযাপন হিসেবে।\nআগে, সমুদ্রযাত্রার সুযোগ-সুবিধা সীমিত ছিল, তথাকথিত জন্মদিনের কেক ছিল কেবল ছুতোরের ওক কাঠ আর ক্যারামেল দিয়ে তৈরি একটি মডেল, তাই আমি কেকের আসল স্বাদ জানি না। এবার আপনার সাথে একসাথে স্বাদ নিতে পারব, আমি মনে করি খাবারের সুস্বাদুতার বাইরেও আমি আরও অনেক কিছু পাব।\nতৃতীয় গন্তব্য, বা বলা উচিত তৃতীয় পর্ব, হলো কাস্টম তারার মানচিত্র। আমি সামুদ্রিক মানচিত্রে আমার জন্মের সময়কার জ্যোতিষ্কের অবস্থান চিহ্নিত করেছি। আপনার আপত্তি না থাকলে, আমি আপনারটিও সেখানে চিহ্নিত করতে চাই। এই অনন্য নৌচালনা তারার মানচিত্র হবে সবচেয়ে সংরক্ষণযোগ্য উপহার।\nসত্যি বলতে, এই চিঠি লেখার সময় আমি দ্বিধায় পড়েছিলাম। এই কাজগুলো নিঃসন্দেহে সাধারণ সীমানা ছাড়িয়ে যায়, কিন্তু আজ একটি বিশেষ দিন, এবং আপনি আমার কাছে একজন বিশেষ মানুষ, যার জন্য নিয়ম ভাঙার যোগ্য।\nতাই অনুগ্রহ করে অবশ্যই প্রত্যাখ্যান করবেন না, এবং সময়মতো উপস্থিত হবেন।\n\nক্রেপারস্যান্ট"
  },
