    Text = "প্রিয় রক্ষক, \n「ঝড়ের নিচে দোলায়মান」 ইভেন্টটি সমাপ্ত হয়েছে। অবশিষ্ট ইভেন্ট মুদ্রা 「Signal Flags」 এখন প্রতিটি পতাকার বিনিময়ে 40টি 「Rose Scrips」 হারে বিনিময় করা হবে। অনুগ্রহ করে আপনার ভাণ্ডার অবশ্যই পরীক্ষা করুন, রক্ষক।"
