  Mail_89903_Desc = {
    Text = "সম্মানিত রক্ষক：\n        《বিস্মৃতির পূর্বরাত》-এর প্রতি আপনার সমর্থন ও স্বীকৃতির জন্য ধন্যবাদ। মিথাগ বিশ্ববিদ্যালয়ে রক্ষকদের আরও ভালো গেমিং অভিজ্ঞতা প্রদানের লক্ষ্যে, আমরা আপনাকে নিচের অভিজ্ঞতা জরিপ প্রশ্নমালাটি পূরণ করতে আমন্ত্রণ জানাচ্ছি। আপনার সহযোগিতার কৃতজ্ঞতাস্বরূপ, আমরা পুরস্কার হিসেবে 「সিলভার」× 200 প্রস্তুত করেছি, প্রশ্নমালা সম্পন্ন করলেই সংগ্রহযোগ্য। প্রশ্নমালার শেষ সময় 9 নভেম্বর সকাল 9:00, সময়মতো পূরণ করতে ভুলবেন না।\n        <SurveyLink:【পূরণ করতে এখানে ক্লিক করুন】>\n        আমরা প্রতিটি রক্ষকের পরামর্শ মনোযোগ দিয়ে শুনব, আপনার মতামত অবশ্যই মিথাগ বিশ্ববিদ্যালয়কে আরও উন্নত করবে!\n        ——রৌপ্য চাবি পথ দেখাক।"
