  Mail_94503_Desc = {
    Text = "আমার পথপ্রদর্শক আলো:\n\nআমি এবং ক্যাস্টর এখানে আসার পর থেকে আপনি আমাদের যে যত্ন নিয়েছেন তা আমাদের নতুন জীবন দেওয়ার সমতুল্য। আমাদের জন্য যত্ন করে তৈরি করা জন্মদিনের কেকটির জন্য আপনাকে ধন্যবাদ। যদিও আপনি কেকের উপর যে দুটি পাখি এঁকেছিলেন সেগুলোকে প্রজাপতি ভেবে ফেলার জন্য আমি সত্যিই দুঃখিত, তবে আমরা এই উপহারটি সত্যিই খুব পছন্দ করেছি। এটাই প্রথমবার আমরা অন্য কারো কাছ থেকে জন্মদিনের উপহার পেলাম।\nআমরা অধ্যক্ষ হোলেটের কাছ থেকেও স্কুলের পক্ষ থেকে একটি শুভেচ্ছা কার্ড পেয়েছি। সেই সাদা খামের উপর সোনালি অলংকৃত সিলমোহর লাগানো ছিল, আর ভেতরে সুন্দর শুভকামনায় ভরা ছিল। এটি সত্যিই একটি উষ্ণ জায়গা। আমাদের জীবনে এর আগে কখনো এত সুখী মুহূর্ত আসেনি।\nদয়া করে আমার এবং ক্যাস্টরের সাথে জন্মদিন উদযাপন করতে আসুন। এটি আমাদের শৈশব থেকে পালন করা একটি রীতি। আমাদের উপকারকারী হিসেবে আপনার জন্যও আমরা বিনিময়ের উপহার প্রস্তুত করেছি — ক্যাস্টরের ঝরে পড়া পালক দিয়ে আমি একটি মুকুট বুনেছি।\nআমি এই অমসৃণ মুকুটটি আপনাকে উৎসর্গ করছি, আমাদের শ্রদ্ধার সামান্য প্রকাশ হিসেবে। আমি আমার বাকি জীবন আপনার পাশে থেকে এই মহান বিদ্যালয়ের মহৎ দর্শন অনুসরণ করতে এবং প্রকৃত পাপ ও অন্ধকার দূর করতে চাই।\nঅনেকদিন এসব করিনি বলে ক্যাস্টর আমার হাতের কাজ নিয়ে হাসাহাসি করেছে, বলেছে ছোটবেলার মতো ভালো হয়নি। আশা করি আপনি এটি তুচ্ছ মনে করবেন না।\n\nপলিডিউসিস"
