    Text = "আমার আদুরে ছোট্ট বন্ধু:\n\nছোট্ট বন্ধু, আজ আমার আগমনের দিন।\nঅবিরাম জ্বলতে থাকা আগুনের গোলা হিসেবে নয়, বরং কেটিগুলা নামের মেয়েটির জন্মদিন।\nজীবিত থাকাকালীন অভ্যাস অনুযায়ী, এই দিনে আমরা একটি জমকালো ভোজসভার আয়োজন করি, মনের আনন্দে মদ আর ঝলসানো মাংস উপভোগ করি।\nঅবশ্যই, সবসময় কিছু দুষ্টু ছেলে পরিবেশ না বুঝে আমাকে নিয়ে ঠাট্টা করে যে আমি আরও এক বছর বুড়ো হয়ে গেছি, তাই আমি আমার মুষ্টি দিয়ে তাদের মাথায় শুভেচ্ছা জানাই।\nআর এখন, এই ভোজসভায় একটি নতুন উদ্দেশ্য যোগ হয়েছে — আমাদের একসাথে কাটানো সেই পুরনো দিনগুলোকে স্মরণ করা।\nএই বছর আমি আরও একটি কার্যক্রম যোগ করতে চাই, আর সেটা হলো — আমাদের ছোট্ট বন্ধুকে শিকার করা!\nজানো, আমি ইতিমধ্যেই অধীর আগ্রহে অপেক্ষা করছি তোমাকে ধরে আমার ভোজসভায় নিয়ে আসতে, তোমার সেই লাজুক অসহায় আদুরে অভিব্যক্তি, আধা মাতাল আধা জাগ্রত ঘোলাটে চোখ, আর ভেতর থেকে ছড়িয়ে পড়া মিষ্টি সুগন্ধ দিয়ে আমার এবারের জন্মদিনের ভোজসভা সাজাতে — এটা হবে আমার জন্মের পর থেকে পাওয়া সেরা জন্মদিনের উপহার!\nএখন পালানোর পরিকল্পনা করতে শুরু করলে দেরি হয়ে যাবে, কারণ তুমি যখন এই চিঠিটা পড়ছ... আমি·ইতি·মধ্যে·তোমার·দরজার·সামনে·এসে·পড়েছি।\nভয় পেয়ো না, ছোট্ট বন্ধু, সবকিছু ঠিকঠাক থাকলে, তুমি এখানে শুধু সেরা গল্প শুনবে, আর সবচেয়ে সুস্বাদু খাবার উপভোগ করবে।\nঅবশ্য, বন্দী হওয়া ছোট্ট পশুর সাথে একটু দুর্ঘটনা ঘটাও তো স্বাভাবিক, তাই না?\nচুপচাপ আমার সাথে চলো ছোট্ট বন্ধু, আজ রাতে তোমার সেই সুন্দর সময়, আমার সাথেই কাটানোর জন্য নির্ধারিত।\n\nকেটিগুলা"
  },
