  Mail_96012_Desc = {
    Text = "প্রিয় রক্ষক:\n「লক্ষ সূর্যের অবতরণ「 ইভেন্টটি সমাপ্ত হয়েছে। এখন আমরা অবশিষ্ট ইভেন্ট আইটেমগুলোকে প্রতি পিসে রোজ স্ক্রিপ*40-এ রূপান্তর করব। দয়া করে সেগুলো সংগ্রহ করতে ভুলবে না।"
