  Mail_96323_Desc = {
    Text = "গোপনীয়তার রক্ষক মহাশয়:\n\nজীবিতরা জন্মদিন উদযাপন করে তাদের অবশিষ্ট জীবনে অর্থ খুঁজে পেতে। আর আমি কেবল এই রাতটিকে ব্যবহার করি মৃত্যুর সুগন্ধকে আরও গাঢ় ও মোহময় করে রান্না করতে।\nযারা আর সংগ্রাম করে না, আর কোনো আকুলতা বহন করে না — সেই মৃতদের জীবদ্দশার সকল কলুষ ধুয়ে যায়। তাদের অনুশোচনা সূক্ষ্ম লবণের মতো, ঠিক সময়ে আঁচের তাপে রক্তের রেখায় মিশে গিয়ে এক আর্দ্র ও বশীভূত সুরভি তৈরি করে। তাদের হাড় থেকে ভেসে আসে মৃদু ফাটলের শব্দ, ত্বক থেকে চুইয়ে পড়া তেল পুদিনার মতো হালকা, আর আত্মার গভীরে লুকানো অসমাপ্ত কথাগুলো ধীরে ধীরে জ্বাল দেওয়ার মধ্যে বেরিয়ে আসে, রেখে যায় এক সূক্ষ্ম মিষ্টতার আভাস। আমি অনেক আগেই কল্পনা করতে শুরু করেছি তোমার নিস্তব্ধ বস্তুতে রূপান্তরিত হওয়ার দৃশ্য — চুল্লির আগুনের সামনে ত্বক টানটান হওয়ার মুচমুচে শব্দ, হাড় ও মাংসের মাঝখান থেকে বাষ্পীভূত হওয়া আবেগ, তোমার বিশুদ্ধ আত্মা ধীরে ধীরে গ্রাস হওয়ার মিষ্টি স্বাদ...\nকিন্তু তুমি আলাদা।\nতুমি এখনও জ্বলছ, এখনও স্পন্দিত হচ্ছ, অথচ তোমার এমন এক সুগন্ধ আছে যা কোনো মৃতের সাথে তুলনীয় নয় — মন ও আত্মাকে মোহিত করে। তুমি সেই পরিপক্বতা যার জন্য আমি অপেক্ষা করতে রাজি, এমনকি আমি চাই এই অপেক্ষা অনন্তকালের চেয়েও দীর্ঘ হোক।\nএই অসংখ্য পুনরাবৃত্ত বর্ষচক্রে, তোমার আবির্ভাব আমার জন্মদিনকে অর্থ দিয়েছে। এটি আর শুধু চমৎকার ভোজনের জন্য নয়, বরং তোমার এখনও স্পন্দমান জীবনের জন্য।\n\nদুলেরসাইন"
